with nuevas(numero,viejo,sec) as (values
(97,'04ca5c154f35365ec21004e3a5a4062e',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ọ̀bàrà dice que las respuestas a nuestros problemas están dentro de nosotros y muy cerca. La persona puede esperar un cambio positivo en su día a día. Algo que perteneció a su padre se ha guardado como riqueza por mucho tiempo y no se perderá. Hay falta de hijos, y debe ir a una ciudad vecina a ofrendar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera un cambio y no ve que lo que necesita ya está cerca (relato de Owa).", "Pregunta por algo de su padre o por un bien antiguo de la familia (relato de Monírèrè).", "Busca un oficio o una forma de ganarse la vida (relato del pescador Dẹ̀dó)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Encontrar lo que busca.", "La herencia del padre que llega.", "Hijos.", "Larga vida y salud; un oficio, como el pescador.", "Quedar fuera de un conflicto que no es suyo."]}, {"titulo": "Ibi y advertencias", "puntos": ["La ignorancia: lo que buscamos está a nuestro lado y no lo vemos.", "Quedarse en medio de una guerra ajena."]}, {"titulo": "Enseñanza principal", "texto": "Lo que buscamos vive cerca de nosotros; solo la ignorancia nos impide verlo. A veces la mejor salida de un conflicto es irse al campo, como el grillo: 'La guerra de la ciudad no llega a la granja'."}, {"titulo": "Relatos reunidos", "puntos": ["Ọwa encuentra lo que busca. Ọ̀rúnmìlà, testigo de la creación, le dijo a Ọwa que lo que buscamos está junto a nosotros y que solo la ignorancia nos impide verlo, y que ofrendara para que Bara Àgbọnnìrègún se lo mostrara. Ofreció una gallina, 20,000 cauríes y medicina de Ifá con dos cabezas de iguana. Se dijo: 'Ọwa siempre encontrará lo que busca'.", "Dẹ'do, el pescador. Le dijeron a Dẹ'do que sería pescador y que ofrendara para tener vida larga y salud: hojas de pẹpẹrẹkun, una carnera, una paloma y 2,800 cauríes. Cumplió.", "La hija del hombre rico. Mọ́nírèré, hija de un hombre rico y anciano, ofrendó porque la riqueza de su padre estaba a la orilla del río y debía llegar a ella. Ofreció y la riqueza le llegó. 'Vemos tu belleza, y tu belleza sigue en los hijos.'", "El grillo se va al campo. Había guerra en la ciudad. Ifá consultó para Ìrè, el grillo, y le pidió ofrendar para no quedar envuelto en el conflicto. Ofreció y se fue al campo, donde se hizo una casa con balcón y vivió tranquilo. Hasta hoy canta: 'La guerra de la ciudad no llegó a la granja'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọwa: una gallina, 20,000 cauríes y dos cabezas de iguana como medicina de Ifá.", "Dẹ'do: hojas de pẹpẹrẹkun, una carnera, una paloma y 2,800 cauríes.", "Para hijos: ofrenda en una ciudad vecina."]}, {"titulo": "Relaciones espirituales", "texto": "Bara Àgbọnnìrègún revela lo escondido. Èṣù Òdàrà es el sacerdote del grillo en el campo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Cabezas de iguana, hojas de pẹpẹrẹkun, gallina, carnera, paloma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 97.1 (yorùbá): O mi ri mi, Me rii, / Ọ̀wọ́nrín'Bàrà: / a dífá fún Qwa / Wọ̀n ni: / Ohun ti a nwa mbẹ / nitosi ẹni Afaimo! / Wọ̀n niki á rúbọ / ki Bara Àgbọnnìrègún le fihan'ni. / Ọ̀rúnmìlà Ẹlẹrí İpín, / İbikeji Olódumare, / Ó ni: / \"ohun ti a nwa nbẹ nitosi eni. / Afaimo!\" / Ẹbọ: Agbẹbo-adiyẹ, egbàáwa owó / ati ewé Ifá (Orí awonriwon Méjì) / Ó gbọ̀ ó rú. / Wọ̀n ni: / To! Abariwọn, / Oowa a maa ri ohun ti nwa o. / El me ve a mí, yo no lo veo.", "Verso 97.2 (yorùbá): Awọn mbẹ n'lbara Apẹja / li a da fún Dẹ'do, / Wọ̀n ni: / Apẹja ni Dẹ'do maa ṣe, / Wọ̀n niki ó wa rúbọ, / Emigigun ati aralile: / Pẹpẹrẹkun, àgùtàn, / ẹyẹlé ati ẹgbèrinlá owó. / Ó gbó ó rú. / Las redes traen abundancia / a los pescadores en Ibara:", "REZO: OJUANI BARA OJUANI LOZURE KURIPA IGBA EÑI LOWO OTO OBARA OPOPA EÑI LOGUE ORE ORUWA KOTO KOTO OFIKO ADIFAFUN BEBE ARUNMALE OUNKO, AKUKO, EYELE LEBO.", "REZO: KURIPA IBA LOGUO OTO ABARRA INILOGUE ORE ONA GUA OFICO CODIE ADIFAFUN BOBO ORUNMILA AUCO LEBO EYELE OUNKO LEBO.", "REZO: OJUANI LOZURE LOZURE IFA ODARA LODE IFA IFA OMO LEKESE LE IRE IFA OMO LEVISA IFA ODARA YEYE IFA OMO AWO SOMU."]}]$q$::jsonb),
(98,'86b4fc27f3b1f68929121b2b946e366a',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ọ̀kànràn dice que hay días para reír y días para llorar. En lo malo pide ofrendar para evitar acusaciones falsas; en lo bueno anuncia tiempo de alegría y risa. La persona necesita ser más realista en lo cotidiano. Pide respetar los tabúes y ofrendar para que no haya muertes ni pleitos graves entre los hijos, ni le quiten lo que es suyo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Debe ver con realismo un asunto diario y separar la preocupación de los hechos.", "Teme acusaciones falsas o arrastra penas pasadas (relato de la tortuga).", "Hay motivo de alegría y de reunión (relato del ave Egaṣẹṣẹ).", "Debe respetar las prohibiciones y evitar pleitos graves entre los hijos (relato de los peces e Ìkòrò)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un día de alegría y fiesta.", "Ganar un lugar nuevo, como el pez en el agua.", "Proteger lo que es suyo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Acusaciones falsas y pleitos judiciales.", "Divertirse sin ofrendar mientras hay enemigos cerca.", "Creerse a salvo y perder su lugar."]}, {"titulo": "Enseñanza principal", "texto": "El que se cree capaz de convertir cualquier pena en risa puede terminar pagando el doble. Preguntar cómo se hace la ofrenda y cumplirla bien es lo que salva al cangrejo."}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga y las acusaciones. Se preguntó qué día era, y los adivinos dijeron que era día de pena y de acusaciones falsas, y que la tortuga debía ofrecer ẹfun, osùn, una paloma, hojas de algodón y 2,200 cauríes. La tortuga no ofreció y dijo que no había asunto penoso en el mundo que ella no pudiera volver risa. Cuando las acusaciones le llovieron, fue a ofrendar, pero le dijeron que ahora era el doble. Pagó.", "Ẹgaṣẹṣẹ, el pájaro del algodonero. Ẹgaṣẹṣẹ preguntó qué día era y le dijeron que era día de alegría y diversión. Ofreció una paloma, una jícara de ñame machacado, sopa, vino de palma y 3,200 cauríes.", "El cangrejo y los peces. A los peces, a Ìkòrò y al cangrejo les pidieron ofrendar con cuidado. El cangrejo fue el único que preguntó cómo hacerlo, y le pidieron mucho aceite de palma y un chivo grande por ataques que vendrían de enemigos de tierra. Cumplió. Los peces e Ìkòrò no ofrecieron y se dedicaron a divertirse. Èṣù les dijo a los hombres: '¿No ven que no ofrendaron y que su carne es sabrosa? Vayan a pescarlos'.", "El pez y la rata. La rata vivía en las aguas profundas y el pez en el campo abierto. A la rata le pidieron ofrendar para no perder su lugar, y dijo que nada del campo podía amenazar las aguas. El pez fue con el sacerdote Àjàlúbòró, que le preparó una medicina con manteca de cacao en una olla de barro para que se untara el cuerpo y entrara al agua. El pez entró, se adaptó y desplazó a la rata, que tuvo que irse al campo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra acusaciones: ẹfun, osùn, una paloma, hojas de algodón (òwú) y 2,200 cauríes; tarde, el doble.", "Para la alegría: una paloma, ñame machacado, sopa, vino de palma y 3,200 cauríes.", "El cangrejo: mucho aceite de palma y un chivo grande.", "El pez: manteca de cacao en olla de barro para untarse."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù castiga al que no ofrenda. Àjàlúbòró, el sacerdote, le da al pez su lugar en el agua."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de òwú (algodón, Gossypium) machacadas con ẹfun, osùn y los demás ingredientes para hacer un jabón de baño. Manteca de cacao, aceite de palma, ñame machacado, vino de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 98.1 (yorùbá): Qjọ kan mbẹ qjo-ẹrin / Qjo miran mbẹ ojọ Ekun. / A ni: ewo ni a kan yi? / Wọ̀n ni: ojọ ibànújẹ, / A daa fObahun ljapá / af'oràn-bi-ẹkún-ṣ'ẹrín. / Wọ̀n ni: / oni ojẹ edunrunmo / nitorinaa ki ó rúbọ: / Efun, osùn, ẹyẹlé, / ewé òwú ati ogbokànlá owó. / Ó gbọ̀ ko rúbọ. / O ni: / kosi òràn ibànújé tio le kan òun / li ayé ki òun mafiṣe erin. / Ó wa rúbọ nikẹhin / nigbati edunrunmo papqju. / Nitorinaa kiwọn tooṣe ewé Ifá fún un, / wọ̀n ni: eru goke. / Ó gbọ̀ ó rú,", "Verso 98.2 (yorùbá): Qjọ kan mbẹ qjọ erín, / ọ̀jọ kan mbẹ qjọ ẹkún: / a daa f'Ẹgaṣẹṣẹ / eyẹ orí òwú. / O ni: Ewo li eyi? / Wọ̀n ni: / Qjo ayọ̀ ati ojọ ere, / a niki ó rúbọ: / Eyẹlé, igbá-iyán, / awo-obẹ, emu / ati egberindilógún owó. / Ó gbọ̀ ó rú", "REZO: OJUANI POKARAN OKANA APUERI APORON ELEBO ANIMARU EBBO OUN BABALAWO LODAFUN ERI LOWO LE EYA OKUE ERA PADAN NI ANSERE LODO ORUNMILA PUKUYE PURAN ADIFAFUN AOMBI AKUKO, EYELE LEBO. MARORAENDO ABO, EURE, EYELE LEBO.", "REZO: AKUORU OKORUN ELEBO A NIMARU EBO AUN BABALAWO LODIFAFUN ERITOGUOLE ELLAWO ARU CADAN NI ANSERE LODO ORUNMILA.", "REZO: KUKUTE KUKU ADIFAFUN ACAMBI EYELE AKUKO LEBO MORORA UNTORI ENUE ABO AURE EYELE LEBO.", "REZO: AKUARI APORUN ANIMARI EBBO AUN BABALAWO LODAFUN ERI LOWO LE EYEKUO ARARA PADAN NI ANSERE LODO ORUNLO KUKUYE KUREN ADIFAFUN AUMBI EYELE AKUKO LEBO MORORA ENDE ABE AURE EYELE OLBO."]}]$q$::jsonb),
(99,'6d95642f11fb0ec3b4c4322a9bd83701',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ògúndá habla de conflictos y dificultades en los negocios y en el hogar. La persona está en un pleito que no puede ganar y debe ofrendar para reducir sus pérdidas. Con la ofrenda se mantiene firme aunque la rodeen enemigos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está en un pleito costoso y debe ver si le conviene seguir.", "Siente hostilidad a su alrededor y teme perder su lugar (relato del árbol Odán).", "Una pareja quiere salir adelante junta (relato de Ọ̀wọ́nrín y Egúntán)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Quedar de pie ante un ataque fuerte.", "Ser respetado.", "Crecer en el mundo junto con la pareja."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enemigos que contratan a alguien para tumbarlo.", "Seguir en un pleito perdido."]}, {"titulo": "Enseñanza principal", "texto": "El que está firme y ofrenda no se dobla aunque el viento sople muy fuerte. Cuando la pelea no se puede ganar, lo sabio es cortar las pérdidas."}, {"titulo": "Relatos reunidos", "puntos": ["El odán y el monstruo. Todos los árboles del campo le tenían rabia al odán, que estaba siempre de pie a cielo abierto, y contrataron a un monstruo para que lo golpeara. Al odán le pidieron una rata, pescado ahumado, aceite de palma, òrí, 2,400 cauríes y medicina de Ifá. Ofreció, y se dijo: 'El monstruo no podrá con el odán; seguirá a cielo abierto por fuerte que sople el viento y siempre será respetado'.", "Ọ̀wọ̀n y su esposa Egúntán. Pèrègún-susu consultó para Ọ̀wọ̀n y para su esposa Egúntán, para que crecieran en el mundo. Ofrecieron una paloma, una carnera, 44,000 cauríes y medicina de Ifá."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El odán: una rata, pescado ahumado, aceite de palma, òrí, 2,400 cauríes y medicina de Ifá.", "La pareja: una paloma, una carnera, 44,000 cauríes y medicina de Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá sostiene al que todos atacan."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Odán (Ficus thonningii, parecido al jagüey). Hojas de oloyinwin trituradas en agua para lavarse la cabeza con jabón. Pescado ahumado, òrí, aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 99.1 (yorùbá): Ọ̀wọ́nrín-Egúntán: / a difá f'odán / Odán mbẹ laarin-ọ̀tá / (gbogbo igi oko ni nse ọ̀tá rẹ̀). / Wọ̀n lọ bẹ Ewele (orọ) / lowẹ wipe kiolo bawon / lu Aba (Qdán) / ti nfi ojoojimo (tosantoru) / duro ni ita, / biobaku ki a lefi àwon igi miran / ti nse ọ̀tá rè rợ po rè / ninu qjà ati ita gbogbo. / A niki wa rúbo / ki Ewele maleluu. / Ẹbọ: Eku, eja-aro, / epo, òrí, egbejilá owó ati ewé Ifá. / Ó gbọ̀ ó rú. / Wọ̀n ni: / Ewele ku lu Aba ita, / owọ yoo maa jẹ fun o.", "Verso 99.2 (yorùbá): Pèrègún-susu / a difá f'Owọ̀n / a bu f'Egúntán, / A niki wọ̀n wa rubo, / Ayé Qwọ̀n ati ti Egúntán aya rẹ̀ a gun. / Ẹbọ: Ẹyelé, àgùntàn, / ẹgbaa mẹjilelogún owó ati ewé lfa / Ó gbó ó rú.", "REZO: OJUANI OGUNDA OLOFIN APATAKIN IMALE AKAKAIVE OZAIN GBOGBO IMALE OLOFIN ASHERE EGUNGUN AWE. UNBO ASHIRE ILE IFA IGBO ORE OBIRIN BIDAJUN ASHIRE ORUN ANONA.", "REZO: OJUANI OGUNDA OPA AKRICO CHALESI ADIFAFUN AROKOMOLLA AKUKO LEBO CORA.", "REZO: APATAKIN IMALO ALAKAIYO OSIA BOGBO IMALE OLOFIN ASHORE GUNGUN AWO UMBO ASHIRE ILA IFA IGBO OKO OBIRIO BIDAJUN ASHIRORO ANCHA ENSHE TURUSILE APETO GORISHO BOGBO KALENO EMOKALABA OBINI OJUANI NIOSI ADIFAFUN ORO MABINU AYODO LAYEDE PA OBINI OLOFIN ISIHO AYODE ILE OLOFIN GORISHA KAFEREFUN OLOFIN LODAFUN EGGUN MEYI.", "REZO: OMA KOIBUMOIBO KONDAYONI EKUN INLO NI IGUI INKIN YAREKO OBINI ADI INA OPA EKUN.", "REZO: ADIFAFUN ORUNMILA OMODE OUJE OLOFIN SATIEDEMU LODAFUN ELE ASHIRI ADE ODDUN.", "REZO: OJUANI DAWAN OMO OKUNI AWO ODARA OMO NIFA ODE TIWALIKE NILE KUETE SI BABA OKBI OMONI OKUN LAYE ADIFAFUN ASHUPA."]}]$q$::jsonb),
(100,'f73ffda09fe64d6d4fd0faf444d6bc0d',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ọ̀sá pide enfrentar con valor los conflictos que vienen y ser prudente con las nuevas parejas. Debe tener cuidado con alguien que llegue a su vida en apuros, huyendo o después de haber dejado o engañado a su pareja anterior. Para tener grandeza y respeto se ofrece una gallina de cinco dedos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Enfrenta una disputa y quiere mantenerse firme sin actuar por impulso.", "Alguien que acaba de dejar otra relación quiere entrar en su vida (relato de Ọ̀wọ́nrín).", "Debe distinguir entre ayudar por compasión y cargar obligaciones que todavía no conoce."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Honor, respeto y autoridad al entrar a la lucha.", "Una mujer que llega para ser su pareja.", "Grandeza."]}, {"titulo": "Ibi y advertencias", "puntos": ["Huir el día de la pelea.", "Recibir sin cuidado a una pareja que huyó de su casa."]}, {"titulo": "Enseñanza principal", "texto": "Elegbara, el trueno y el leopardo no huyen el día de la pelea; tampoco quien tiene este signo ni los que lo siguen. Pero el valor en la lucha no es lo mismo que abrir la casa sin precaución."}, {"titulo": "Relatos reunidos", "puntos": ["El que no huye de la pelea. Elegbara no huye el día de la pelea; Ààrá, el trueno, no huye; Ẹkùn, el leopardo, no huye; y quien recita esto tampoco, ni sus seguidores. Es un rezo para entrar a la lucha con honor, respeto y autoridad.", "Ọ̀wọ̀n y la mujer fugitiva. Le advirtieron a Ọ̀wọ̀n que una mujer que había escapado de su casa o de su esposo venía para ser su esposa, y que debía ofrendar para que ella entrara en su casa con precaución. Ofreció un caracol babosa, 2,000 cauríes y medicina de Ifá, y el adivino le preparó la medicina para comer."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la lucha: el rezo pronunciado sobre iyẹ̀-ìrosùn marcado con este signo, con ipẹ-ele molido en una calabaza y agidi (harina de maíz cocida), que se come junto con los seguidores.", "Para la mujer que llega: un caracol babosa, 2,000 cauríes y medicina de Ifá; la masa del caracol se seca y se cocina en sopa con hojas de ẹ̀sọ para que la coma el cliente.", "Para grandeza y respeto: una gallina de cinco dedos; si no se consigue, cinco gallinas y un huevo enterrado en un lugar limpio, con iyẹ̀-ìrosùn regado sobre el huevo antes de taparlo."]}, {"titulo": "Relaciones espirituales", "texto": "Elegbara (Èṣù), Ààrá (el trueno, de Ṣàngó) y el leopardo son modelos de valor."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ipẹ-ele, agidi, hojas de ẹ̀sọ (Elytraria marginata), caracol babosa, gallina de cinco dedos, huevo, iyẹ̀-ìrosùn."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 100.1 (yorùbá): Ọ̀wọ́nrín-Ọ̀sá: / Flégbárá kiisá lojo ijà, / ajàgbuyi niti Ẹlẹgbárá. / Ààrá kii sá lọjọ ija, / Ajàgbuyi niti Ààrá. / Ẹkùn kiisá lojọ ijà, / Ajàgbuyi niti Ẹkùn / Emi ko maa sá lọjo ijà, / ki awọn ọmọ (ogun) èhin mi / ma (le) sá lọjọ ijà. / Ki a gba iyi / kiagba ọlá / ninu ijà naa.", "Verso 100.2 (yorùbá): Ikun awo ojú-ònà: / a dífá f'Ọ̀wọ́nrín. / Wọ̀n ni: / \"Obirin kan isansá nbọ waa ṣe aya rè\". / Wọ̀n ni: / \"ẹbẹ niki o ṣe kioba a lefi ẹso de sinu ilé rè\". / Ẹbọ: İgbín, ẹgbẹ̀wá owó ati ewé Ifá. / Ó gbọ̀ ó rú. / Wọ̀n ṣe ewé Ifá fún un jẹ. / Ikun el awo del camino:", "REZO: OJUANI BOSA KOPATO LOTA KORATO OWO LOGUN ASAYENI LOWO ORUNMILA, AKUKO, ADIE LEBO.", "REZO: OJUANI BOSA BOMOSA ADIFAFUN OKUN ATI OBATALA. IFA FORE IRE OMO ESHU ATI OLOFIN.", "SUYERE: “BABA EGGUN LAMIGBAYE OKOKAN LAMILORO OKOKAN LAWEO OSUN”.", "REZO: INSHE NISHE TOYU INBERIN BAMBA LODO LOYU EJA ONA ATOSI NILEMU ADIFAFUN ELEBUTE. BABA AWO IBERIKI IWO LODUN KOTOTEFA.", "SUYERE: AWO NIBAO NIMU IYALO.", "REZO: ORUN IGBALE OJUANI BOSA ARUFIN ARUFIN ADIE ARAÑA ORUNIMOLE ORO NILEO AWO.", "REZO: OJUANI OMO OSA META BI OMOLERIKU ETUTU KAPATO AWO ADIFAFUN OLOFIN OSUN TIKI LAYENIFA ADIE IFA FORE OMO ESHU LODAFUN ORUNMILA.", "REZO: OJUANI BOSA WAJA ADIFAFUN OMO TINSHOMO OLOKUN OMO LORUBO IRE META EBBO."]}]$q$::jsonb),
(101,'b24fbbde30058d3db643e3b16af44ab8',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ìká garantiza el éxito a quien vive con moderación y equilibrio. En lo malo da soluciones para evitar la muerte y protegerse del rencor, el desprecio y la envidia. La persona debe pensar con cuidado antes de actuar y no tener sus cosas en desorden. Usa hojas frescas como medicina."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Debe pensar antes de actuar o de gastar (relato de Afiwon-ṣe-ohun-gbogbo y Oyinbo).", "El bienestar puede llegar poco a poco.", "Siente desprecio de otros o teme por su seguridad (relatos de Ademoorin Ayankale y de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Dinero, pareja, hijos y todo lo bueno que llega a la casa.", "No perder nunca el equilibrio.", "Escapar de la muerte.", "Que las manos del que lo desprecia no puedan dañarlo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desorden y desequilibrio.", "Rencor y desprecio de otros.", "Enemigos reales y brujería."]}, {"titulo": "Enseñanza principal", "texto": "Ọ̀wọ̀n no come, no bebe, no se viste ni construye sin calcular antes. Las hojas son las que reparan el mundo: cuando algo se descompone, se buscan las hojas adecuadas."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀wọ̀n se ríe. Ọ̀rúnmìlà explicó que Ọ̀wọ̀n se reía a carcajadas porque la fortuna de dinero, de pareja y de hijos entraba a su casa. Su vida era perfecta porque todo lo ponía en equilibrio y calculaba antes de comer, beber, vestirse o construir. Ifá consultó para Afiwon y para Oyinbo y les pidió cuatro pimientas de guinea, medicina con hojas de emú, cuatro murciélagos, cuatro sacos grandes y 42,000 cauríes para nunca perder el equilibrio. 'Lo que agarra la tenaza no se cae.'", "Ademoorin y la muerte. Le pidieron a Ademoorin Ayankale una tortuga, semillas de ẹ̀sọ-ikú y 24,000 cauríes para no caer en manos de la muerte, o para que, si caía, la muerte no pudiera matarlo. 'El niño que no camina no se vuelve sabio.'", "Las manos que desprecian. Ọ̀rúnmìlà iba a recorrer el mundo y ofreció nueces de kola secas, semillas de ayo, kola amarga seca, una paloma, una gallina, 20,000 cauríes y medicina de Ifá para que las manos de los que lo despreciaban no tuvieran poder sobre él. 'Ninguna uña de hombre daña la kola; las manos de los que te desprecian no te afectarán.'", "Las hojas, hijo mayor de Ọ̀rúnmìlà. Ògún quería ser rey de Atúnléayéṣe, y los que eligen reyes le dijeron que nadie es rey sin un hijo mayor. Le preguntaron quién era su primogénito y respondió: 'La maldad'. Nadie quiso poner a la maldad en el trono. Lo mismo pasó con Òòṣà, cuyo primogénito era el sufrimiento. Cuando Ọ̀rúnmìlà dijo que su primogénito eran las hojas medicinales, se sorprendieron. Explicó que para conseguir lo bueno hay que buscar las hojas adecuadas, porque ellas reparan las cosas. Así el mundo se volvió un mejor lugar, y hasta hoy, cuando algo anda mal, se buscan ciertas hojas. Su fuente es Ìtún Ẹrin, el reino de las hojas que curan.", "Ọ̀rúnmìlà entre las brujas. Ọ̀rúnmìlà dormía en medio de las brujas y al alcance de la muerte, rodeado de todos los ajogun, y preguntó si podrían alcanzarlo. Le dijeron que con la ofrenda los superaría. Cumplió y ninguno pudo dañarlo. 'Como la piel resbalosa del pez que se escapa de las manos, escapamos de las brujas.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para el equilibrio: cuatro pimientas de guinea, medicina con hojas de emú, cuatro murciélagos, cuatro sacos grandes y 42,000 cauríes.", "Contra la muerte: una tortuga, semillas de ẹ̀sọ-ikú y 24,000 cauríes.", "Contra el desprecio: kola seca, semillas de ayo, kola amarga seca, una paloma, una gallina, 20,000 cauríes y medicina de Ifá.", "Contra enemigos: un pescado fresco picado en seis o nueve partes, mezclado con mucho aceite de palma."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà tiene por primogénito a las hojas medicinales. Ògún y Òòṣà quedan fuera del trono por lo que traen consigo. Los ajogun y las brujas no alcanzan al que ofrenda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de emú (Oldenlandia corymbosa o Baissea axillaris), hojas frescas como medicina, pimienta de guinea, kola, kola amarga, semillas de ayo, semillas de ẹ̀sọ-ikú, pescado fresco con aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 101.1 (yorùbá): Ọ̀rúnmìlà I: Ọ̀wọ́nrín'Ká, / Mi: Ọ̀wọ́nrín'Ká. / Mo ni: eetiri ti Qwọ̀n fi nrin kaakaa? / Ọ̀rúnmìlà dahun o ni: Ọ̀wọ̀n nrin kaakaa / nigbati owó wa ni'lé / li ọmọ wa ni'lé / ati ohun rere gbogbo, / ayé Qwọ̀n gun gẹgẹ. / Wọ̀n ngbe ohun gbogbo wa sori iwòn: / Qwọ̀n kiljẹun / kiomawon on kiotoojẹẹ, / wọ̀n kiimu omi / kiomawon on kiotoomuu, / Qwọ̀n kiilo aṣo / kiomawon on kiotoo loo, / Ọ̀wọ̀n kiikọle / kiomawòn on wo kiotoo kọọ: / a difá f'Afiwon-ṣe-ohun-gbogbo / n'lfẹ-Ooyẹ / a bu f'Oyinbo, / a niki wọ̀n wa rúbọ / kiwọn ma baa ju iwọ̀n nu laelae: / Ataare mérin, ewé ẹmú, àdán mérin, / Qkẹ-id'ẹrù (okẹ tiafi ndi ẹrù) mẹrin, / egbàá mọ̀kànlélógún owó li ẹbọ. / Wọ̀n rúbọ, / a ṣ'ewé Ifá fún wọn, wọ̀n gbaa. / A ni: / \"Ohun ẹmu (ba) mu kiibo\". / \"Àdán kiimu'gi kiobo\".", "Verso 101.2 (yorùbá): Karinlo, / Karinbowale, / Bi ọmọ ko rín ọmọ kiigbón: / li a da fAdemogrín Ayankale, / wọn niki o wa rúbo / kio ma baa bọs'ọwọ̀ ikú, / bioba bos'owọ̀ ikú / ki ikú ma le pa a. / Abawun, eso-ikú / ati ẹgbàá méjilá owó. / Ó gbọ̀ ó rú.", "Verso 101.3 (yorùbá): Ọ̀wọ́nrín'Kaye: / a difá f'Ọ̀rúnmìlà. / A niki Ọ̀rúnmìlà rúbọ, / bi oun ti maa nrin ka ayé yi, / ki ọwọ̀ àwọn Abatẹnijẹ ma le ran. / Ebọ: Obi-gbigbe, omo-ayo, / orógbó-gbigbe, ẹyẹlé, adiyẹ, / egbàáwa owó ati ewé Ifá. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Eekanna Eleekanna / kiiran obi-gbigbe\", / \"Eekanna Eleekanna / kiiran orógbó-gbigbe\", / \"Eekanaa Eleekanna / kiiran omo-ayo\", / \"ki ọwọ̀ àwọn Abatẹnijẹ / kioma le rán o\". / Bayi ni Ọ̀rúnmìlà ṣe / ti ọwọ̀ àwọn Abatẹnijẹ ko fi le ran an.", "REZO: OJUANI BOKA OTOBALE ADEMI IKABALE ADIÑA AWI ADIFAFUN OTE TINSHOMO BOISHE TINSHOMO ABUPE EKA ADA OMO OLOFIN.", "REZO: OTOBALE ODONI IKABALE ADIÑA AGUI ADIFAFUN OTO TINCHONA BOICA TINCHONA ABURE ACA OMO OLOFIN AKUKO LEBO AUCO EYA LEBO. ARDU EDEBI IBORU IBOYA IBOCHE CHE.", "REZO: OTOBALE ODOMI IKORDIE ODINAGUI ADIFAFUN OTO TINSHOMO EBBO. IKA DUNI AKA OMO OLOFIN.", "SUYERE: ABIBIDE OZAIN ABIBIDE OZAIN ADIFAFUN EKO.", "REZO: OJUANI BOKA IKA IKALE KALAKAYE EYENI OLOFIN YEWELE YEWELEYE OZAIN AWANIYU KUEKUESE KON MUELESE MEYI WANWAN OGUERE LAGORI OBAYDE NI ORISHAOKO.", "REZO: OJUANI BOKA ANADULE TUTALE AWO OMO LOGUINDO FABEWA AWARI OLOTA ATOPEKE AGUN DALE AWO OLANTA EGGUN UNSORO AWO AWORI OLANTA EGGUN UNSO DELONA INLE FABEWA OJUANI BOKA.", "REZO: BADUTO ELODO LOKUO TOTO LOFUN WAYO IGUA KOLASHE WA ODA SHE ILE AWO OJUANI BOKA ETU, PASHA BURUKU EÑA KANLOSI BURUKU TIO UMBOMI PAKO ADIFAFUN IWI, ADIFAFUN ESI."]}]$q$::jsonb),
(102,'4a340afd2433d8e66ecb6e864d8a0daf',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Òtúrúpọ̀n da soluciones para evitar que los hijos mueran pequeños y para volver de un viaje con buena fortuna; ayuda a prevenir los abortos. Lo bueno que ha estado limitado se le dará. Trae suerte con las mujeres, y pide escuchar los buenos consejos para no salirse del camino."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme por un embarazo o por la salud de sus hijos (relato de Ekún-o-de-bẹ).", "Va a viajar y quiere volver bien (relato de Ọ̀rúnmìlà).", "Desea pareja y siente que las oportunidades se le han cerrado (relato de Itú)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos que viven.", "Regresar de lejos con buena fortuna.", "Pareja; muchas esposas, como Itú.", "Volver al camino correcto."]}, {"titulo": "Ibi y advertencias", "puntos": ["Muerte temprana de los hijos (àbíkú).", "Pérdida de embarazos.", "Tomar caminos equivocados en la vida.", "Llorar sin hacer nada."]}, {"titulo": "Enseñanza principal", "texto": "Llorar no resuelve nada: hay que actuar. El que se equivocaba de camino, como Ṣàngó, puede volver a la ruta correcta con la ofrenda."}, {"titulo": "Relatos reunidos", "puntos": ["El que llorando no logra nada. Ifá consultó para Ẹkún-o-de'bẹ, cuyos hijos morían pequeños, para que dejara de traer hijos àbíkú. Le marcaron cuatro gallinas, 28,000 cauríes y medicina de Ifá. Su nombre recuerda que llorar no sirve; hay que actuar.", "Ọ̀rúnmìlà vuelve de lejos. Ọ̀rúnmìlà viajaba a un lugar distante y le dijeron que regresaría a casa con buena fortuna. Ofreció dos palomas y 4,000 cauríes.", "Itú y las esposas. Itú lloraba porque no tenía mujer. Le dijeron que cuando las esposas llegaran serían muchas, y le pidieron bastante pimienta de caimán para masticarla y escupirla mientras se lamentaba. Ofreció, y hoy Itú anda rodeado de esposas. Cantaba: 'Ọ̀wọ́nrín bàtú bàtú, desátame, ya tengo esposa'.", "La pierna herida y Ṣàngó. La pierna de Ọ̀wọ́nrín tenía una herida infectada, por eso cojeaba y tropezaba. Ifá consultó para Ṣàngó, que venía del cielo a la tierra y andaba siempre por caminos equivocados. Ofreció, mandó torrentes de truenos y volvió a su ruta."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra la muerte de los hijos: cuatro gallinas, 28,000 cauríes y medicina de Ifá.", "Para el viaje: dos palomas y 4,000 cauríes.", "Para pareja: una gallina, un gallo y pimienta de caimán."]}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó recobra su camino con el trueno. Ifá protege a los hijos àbíkú."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pimienta de caimán (ataare), gallinas, gallo, palomas. Ante embarazos que se pierden o niños que enferman, es necesario también el médico."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 102.1 (yorùbá): Abánidárò: / li o difá fún Ekún-o-de'bẹ / nitori àbíkú omo rè. / Wọ̀n niki o wa ṣebọ / kiole yeebi àbikú omo-ẹhin / nigbagbogbo. / Ebọ: Agbebo-adiyẹ mérin, / egbàá mẹrinlá owó ati ewé Ifá. / Abánidárò (el simpatizante):", "Verso 102.2 (yorùbá): Ọ̀wọ́nrín nre àjò / o ko Òtúrúpọ̀n l'ọna: / a daa fún Ọ̀rúnmìlà. / Wọ̀n nì: / Ọ̀rúnmìlà a ri're bowale. / Ẹbọ: Eyẹlé Méjì / ati egbàá Méjì owó. / Ó gbọ̀ ó rú. / \"Ọ̀wọ́nrín iba de viaje / y encontró Òtúrúpọ̀n en el camino\":", "REZO: OJUANI BATRUPON IKA KALERE OKOLISHIRAWO OMO OLUO POPO VITI BABARE NI IFA MAYIRE AWO OMO OZAIN MORUBURO OJUANI BATRUPON OMO OKOFA LAWO GURANDE IFA NI OREFUN OYA, KAFEREFUN ORUNMILA.", "REZO: AGUICAN NIMBRE LEÑI ECHU MARE ADIFAFUN ADAERO ACUORO ANI ECHADUN ALLE EYELE MARERA NIFI ILLA AUCO EKU LEBO.", "REZO: ODA OSE AGUAROCO EBO CORU OLLUGUN EBO CORU ALLOENROCO ALLO ELLU ORO ETOMAQUEQUE RE ARILLORIO OMA KEKERE OGUEMA.", "REZO: IQUI CAN NIMBR ILE ECHU MARE ELEGBA ADIFAFUN ODE ORO OENORO INO ECHODU.", "REZO: OJUANI BATRUPON BANKOYE ADIFAFUN YEKINO OLONU KOKOIBE OMOKOBORE KANIWA UNKO KADEA YAGUGU ARUGBO LODAFUN ORUNMILA OLUPAMORA AWO.", "REZO: OJUANI BATRUPON IFA FORE OBA INLE BAYA INGIRA IFA MONI AWO LOTARE IFA KAFEREFUN ADIBO ALAWANA ONIRE INTORI ARA ILE UNLO ASHE ELEGBARA ADORE UNTEFA IRE ASHEGUN OTA OJUANI BATRUPON.", "REZO: IFA KALARE OKOLISHIRAWO OMO OLUO POPO BEBERE NI IFA NAYIRE AWO OMO OZAIN MORUBORO OJUANI BATRUPON IFA YANYANIRE OYA IFA MOFUN OMIYAWAO INLE FELEYEKUN IFA ONIRE ORIFA OMO NI OBA OZAIN OJUANI ENI BATRUPON OMO OKOYA LA AWO GURANDE IFA NI OLONA OBARA ENI IFA KAFEREFUN OZAIN, KAFEREFUN OYA, KAFEREFUN ORUNMILA.", "REZO: OJUANI PURU PURU OMO BATRUPON OTA KUKU IWAN TURU EGGUN OMONI BOSHERE OKUTE NITIYOKO OBIÑIÑI ADIFAFUN KUTUNLA INLE TIBOSHE OKUTA LAOMA BEYE NIFA IFA OMOLAYE OJUANI", "BATRUPON OMA TUTU EGO OYOTUN OFINITO OTE EROFE INLE OBASHERE GUO GUE OLUPERIKO AWO OMA TUTU KUELE ADIFA EGGUN ONIMATENE EGGUN OKUTA PALASHORO LODAFUN EGGUN.", "SUYERE: EROPO EROFA KOFIYE DENU KOFIYE DEKUN KOFIYE DE BOGBO ARA."]}]$q$::jsonb),
(103,'ad96cf502727aa1b8e8727f54c36165d',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Òtúrá pide evitar el pleito con alguien mucho más fuerte y no buscar venganza ni desquite por daños sufridos. La persona puede haber perdido la fe en que le toque algo bueno; debe ofrendar para recibirlo. Le deben dinero, pero debe tener paciencia y no cobrar con malos modos, porque hay quien prefiere verlo muerto antes que pagarle."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere vengarse o responder a golpes a una ofensa (relato del caracol Igbin y el leopardo).", "Su rival tiene más poder y necesita otra forma de protegerse.", "Perdió la esperanza de que lleguen tiempos mejores (relato de la hoja gbégbé).", "Le faltan los medios para hacer su trabajo (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que el destino pelee por él.", "Recibir bendiciones; estar siempre verde, como la hoja de gbégbé.", "Hallar con qué ofrendar a Ifá en los últimos días."]}, {"titulo": "Ibi y advertencias", "puntos": ["Pelear con quien es más fuerte.", "Cobrar deudas con violencia.", "Deudores que lo quieren muerto."]}, {"titulo": "Enseñanza principal", "texto": "El caracol no debe retar al leopardo: se le deja a Ọlọ́run, que es más poderoso que nosotros. Y el que cobra con malas formas, como el escarabajo del ñame, termina asado junto con la comida."}, {"titulo": "Relatos reunidos", "puntos": ["El caracol y el leopardo. El caracol iba a pelear con el leopardo. El adivino le dijo que el leopardo siempre está listo para atacar y que el caracol no debía retarlo; que eso se le dejaba a Ọlọ́run. Le pidieron una tortuga y 3,200 cauríes para que el destino peleara por él. Ofreció.", "La hoja de gbégbé. A la hoja de gbégbé le pidieron dieciséis kolas amargas y 44,000 cauríes para poder confiar en que le llegaría algo bueno. Ofreció, y se dijo que la muerte y la enfermedad no la tocarían y que siempre estaría verde y llena.", "Ọ̀rúnmìlà sin con qué ofrendar. Ọ̀rúnmìlà dijo que ya no encontraba cosas para ofrendar a su Ifá. Le pidieron cuidar la tierra y ofrendar. Lo hizo, y le aseguraron que tendría con qué ofrendar a su ikin hasta sus últimos días.", "El escarabajo del ñame. El ñame le debía mucho dinero al escarabajo, que lo reclamaba sin cesar y de mala manera. Los sacerdotes le advirtieron que junto al ñame había un enemigo poderoso. No hizo caso. Un día fue a cobrar a la fuerza, no le pagaron y se quedó adentro del ñame comiéndoselo. Llegaron los campesinos a cosechar, se llevaron los ñames a casa y, al pelarlos, encontraron al escarabajo. Lo ensartaron en un palo, lo asaron y se lo comieron con el ñame machacado. Se acordó tarde de la advertencia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El caracol: una tortuga y 3,200 cauríes.", "La gbégbé: dieciséis kolas amargas y 44,000 cauríes.", "Para evitar malas situaciones: una papilla grande de maíz (àkàsù) para Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ọlọ́run pelea por el débil que ofrenda. Ifá recibe la papilla de maíz."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hoja de gbégbé (Icacina trichantha), kola amarga, papilla de maíz, tortuga, ñame."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 103.1 (yorùbá): ljamja ko turasilẹ lẹẹkan: / a difá fún İgbin Omẹso, / nlọ b'Ẹkùn jijà ojiji. / Wọ̀n ni: / \"Ẹkùn wa ni imura tẹlẹ / nigbagbogbo, / ki İgbín maṣe, / ẹniti a kolemu Ọlórun liaa fún\". / Wọ̀n niki o wa rúbọ / ki İpín le jà fún un. / Ẹbọ: Abahun-İjapá, / Egberindílógún owó. / Ó rúbọ. / \"Ijamja está siempre preparado\":", "Verso 103.2 (yorùbá): \"A waa-waa: a rii\": / a difá fún Ewé-gbégbé, / wọ̀n niki ó wa rúbọ, / kioba ler'ohun rere gbẹkẹle. / Ẹbọ: Orógbó mẹrindilógún, / egbàá méjilélógún owó. / Ó gbọ̀ ó rú. / Wọ̀n nì: / \"Ikú koniipa Gbégbé, / àrùn koniidee gun'lẹ. / Ara yoo matuu tojotẹrun\" / \"El que busca y busca: encuentra\":", "REZO: OJUANI ALAKENTU SHATIKI NABO OLU ARA ADIFAFUN ORUNMILA TINSHAWO ILE OLOKUNI LODAFUN OBANLA.", "REZO: SHAKUTI MEBO OLUARA ADIFAFUN ORUNMILA TINCHAWO ILE OLOKUN AURE LEBO CHAQUITI LEBO OLUO ARO ADIFAFUN OSHOSI TINCHELE LERI EDO AKUKO LEBO EYELE AKUKO LEBO. IKU KIPA MOSU LOLLU AWO.", "REZO: SHIKITI NEBO OLU ARU ADIFAFUN ORUNMILA TINSHA IBO ILE OLOKUN LODAFUN OBANLA.", "REZO: TANIWA LIBO OMI MIO NOTORI KINI NI TORI KINI OMINI OKUTELE OMONI EÑI ADIE.", "REZO: TINSHE ILE OLOFIN EWE ELEBO AIKITI LEBO OLUWO ARO ADIFAFUN ENISI TINSHE RE LERI ABO, AKUKO LEBO, EYELE LEBO KI PALAYI AWO.", "REZO: SHAKITI NEBO ALDORA ADIFAFUN ADIFAFUN ORUNMILA TINSHOKE ILA OLOKUN AURE LEBO SHIKI LEBO OLUO AWO ADIFAFUN OSHOSIS, TINSHERO LERI, ODO AKUKO LEBO, EYELE LEBO, IKU KIFA YOYI OWO.", "REZO: OJUANI ALAKENTU OMO YOBI IFA ALA ALA MEYO BOKUN ALAKENTU ABO OBA MOGUIRE ALAKENTU OLOKUN MOYOKU TOBA NI MOGUN MOYARE ALAKENTU AWANI WE WE ELEGBARA OMOSU ALAKENTU MO OZAIN OUNSHISHE OMO ALAKENTU OLOFIN OBONI YOBI ODARA YOBI IFA OBA NI YARE OZAIN IFA KAFEREFUN ELEGBARA, OZAIN, OLOKUN, ATI OBATALA ONA NI YERE OBA TINSHE ELEGBARA ALAKENTU ETU, ABO NI YARE.", "REZO: ADIFAFUN AWO ODO AWO FIWERE AWO AKUTA ODARA NI EGGUN ABERE OWO OFA OLOWO OJU MUNI WIRI ABU FENI YAWO INSHEKITI INSHEKITI OKUTA SOTTUN AYE OLOFIN AWO ORUN IGUI EKUGAÑA ORUN BELEKUN OLUBE SIWERA OKU GBOGBO ENI", "OKUA AWO OLOFIN BABOSU LAYE EYA ONI AWAYATIO OLOFIN YAWAO LODAFUN ORUNMILA KAFERFUN OLOFIN.", "REZO: OSHAGRIÑAN UMBO AIYE ÑAN ÑAN ORISHA NILE OLODUMARE EYIGBO OLOFIN AIYE LODAFUN OSHAGRIÑAN OSODE AWO ODE IFA OJUANI ALAKENTU EDA IDA MURIN OKUNI AKUKO EYELA OBINI AKUKO AIYE.", "REZO: MAFEREFUN BABALU AYE MAFEREFUN OLOKUN NI EBO OLUGARA ADIFAFUN ORUNMILA TINSHAWO ILE OLOKUN EURE LEBO SHAKITI LERO OLUO ARA ADIFAFUN OSHOSI TINSHORO LERI OKE OKO AKUKO LEBO EYELE LEBO.", "REZO: OJUANI ALAKENTU OJUANI MONI SHAKITI NIBO OLUWO ARA TINSHAWO ILE OLOFIN ADIFAFUN ORUNMILA TINSHERO OKE, ADIFAFUN OGGUN ATI OSHOSI.", "REZO: OJUANI ALAKENTU YERE YERE SOKUN YERE YERE AWO OSI BERELU LOKUN OBINI TOYELERE ASHE BABA OLOFIN OLUWO BAYARE WAWA NILE BABA OSI BABA IYATOLO BABA YOKUN LODO LERI ANIERE BAYERE OUN LONI."]}]$q$::jsonb),
(104,'7814e44965795d511d25f2ed20caf32c',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ìrẹtẹ̀ pide no ser desconfiado ni receloso en exceso, y reflexionar sobre sus ideas, motivos y metas. Hay personas que ponen en peligro su vida y la de quienes viven con él, y debe ofrendar para vencerlas. No debe contarle sus secretos a su pareja, porque por ahí intentarán entrar sus enemigos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Sospecha de otros y debe separar los hechos de sus miedos.", "Va a ocupar un cargo y debe pensar cómo ejercerlo (relato de Ọlọ́fin Iwajo).", "Puede retar o menospreciar a alguien cuya reacción no puede controlar (relato de Afi-niṣ-egan).", "Hay un peligro escondido en una relación de confianza (relato de Oníwèémò y el Gusano)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un buen momento para obtener un cargo o un título.", "Descubrir y vencer al falso amigo.", "Salvarse de una condena gracias a la verdad."]}, {"titulo": "Ibi y advertencias", "puntos": ["Menospreciar a otros y que Èṣù lo empuje contra alguien más fuerte.", "Contar secretos a la pareja.", "Un amigo cercano que es enemigo oculto."]}, {"titulo": "Enseñanza principal", "texto": "El sueño no le teme a la muerte; a las mujeres no se les cuentan los secretos; y el hijo ajeno no es igual al propio. Así se llamaban los tres peinados de Abéṣùjiyàn, y los tres resultaron ciertos."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlófin Iwajo y su tiempo de mando. 'No hay guerra en el campo ni conspiración en la ciudad', le dijeron a Ọlófin Iwajo: era buen tiempo para obtener un título. Ofreció dieciséis caracoles babosa, un perro y 14,000 cauríes para que la alegría de su mando no volviera a mucha gente ladrona, estafadora o loca.", "El despreciador. Ọ̀wọ̀n se burlaba de Ìrẹtẹ̀ preguntando qué podía hacerle, y le dijeron que Ìrẹtẹ̀ podía pisotearlo. A Afi'niṣ'ẹgan, el que desprecia, le pidieron ñame asado machacado y nueve caracoles para que Èṣù no lo empujara contra alguien más poderoso. No ofreció.", "El gallo y el gusano. El gusano y el gallo vivían en la misma propiedad y se decían grandes amigos, pero el gusano quería quedarse con todo. El gallo tuvo pesadillas y fue con Ọ̀rúnmìlà, que vio en el tablero a una persona delgada, su enemigo, y le preparó una ofrenda con mucho iyẹ̀-ìrosùn para las puertas de enfrente y de atrás. Esa noche el gusano pasó por encima de la ofrenda, quedó paralizado y se partió en pedazos. En la mañana el gallo se los comió. Cuando la gente buscaba al gusano, el gallo no aguantó y cantó: 'Al gusano lo cortaron en pedazos, y en el estómago está enterrado el falso amigo'.", "Los tres peinados de Abéṣùjiyàn. Abéṣùjiyàn, sacerdote de Ọlófin, se cortó tres figuras en el pelo y decía que eran peinados de sabiduría cuyos nombres solo él sabía. El rey lo tomó a su lado con sueldo, pero quería saber los nombres, y mandó pagarle en secreto a la esposa para que los averiguara. Ella le insistió durante meses hasta que él se los dijo uno por uno, y ella fue con el rey: 'El sueño no le teme a la muerte', 'A las mujeres no se les cuentan los secretos' y 'La protección no iguala al linaje: el hijo ajeno no es como el propio'. El rey lo llamó, le dijo los nombres, lo mandó atar en el patio y ordenó decapitarlo en siete días. Una noche el rey lo encontró dormido y roncando, y pensó que el primer nombre era cierto. El día de la ejecución, el hijo adoptivo de Abéṣùjiyàn corrió llorando al rey, pero para pedir la faja que su padre llevaba puesta, porque era suya. El rey detuvo todo y dijo que los tres nombres se habían cumplido: el sueño no le temió a la muerte, la esposa vendió el secreto y el hijo ajeno pensó primero en su tela. Lo soltaron y le pidieron disculpas."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọlófin: dieciséis caracoles babosa, un perro y 14,000 cauríes.", "El despreciador: ñame asado machacado y nueve caracoles babosa.", "Contra el falso amigo: ofrenda con mucho iyẹ̀-ìrosùn en la entrada principal y en la de atrás."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù empuja al que desprecia. Ọ̀rúnmìlà descubre al enemigo oculto. Ọlófin y el rey ponen a prueba al sabio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Iyẹ̀-ìrosùn, caracoles babosa, ñame asado."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 104.1 (yorùbá): Kos'ogun ni papa, / Kos'ọ̀tẹ laarin ilu. / A dífá fún Ọlófin Iwajo. / Wọ̀n niki: / \"Ọtẹ (igba) rẹ̀ lori oyé a sunwòn\". / Wọ̀n niki Ọlofin rúbo, / ki ayè igba rè / ma le mu opolopo èniyàn / di ole tabi asínwín. / Ẹbọ: İgbin mẹridilógún, / ajá, egbàáje owó. / Ó gbọ̀ ó rú.", "Verso 104.2 (yorùbá): Ọ̀wọ̀n nrín Ìrẹtẹ̀: / \"I kinni Ìrẹtẹ̀ maa ṣe?\" / Wọ̀n ni: \"Ìrẹtẹ̀ le teẹ ri\": / a difá fún Okunrin kan Afi'niṣ'ẹgan. / Wọ̀n niki o wa rúbọ, / ki Èṣú ma tiilo ba eniti o juu. / Ebọ: lgbá ewo, igbín mésàn. / Ô gbó ko rú.", "REZO: OJUANI BIRETE AKITI BABA OPEKU ADIFAFUN OLOFIN APARI ADIFAFUN PALA KOREY.", "REZO: AKITI BABA OPECUN AOPOPO ADIFAFUN OLOFIN APARI EYELE LEBO PARAKOLE ADIFAFUN AKUKO LEBO ADIE EKU LEBO.", "REZO: OKITI BABA OCEAN AOPOCO ADIFAFUN OLOFIN APARI EYELE LEBO PARAKOLE ADIFAFUN AKUKO LEBO ADIE EKU LEBO.", "REZO: MU EYENU IWA ADIFAFUN NIYE BURE ALARA OJUANI BIRETE ATAKUAKO ADIFAFUN AKUKO TINRELE OGGUN AKEKE FON SOLU ADIFAFUN ORUNMILA GUORITO OLA ADIFAFUN OBATALA.EBBO: AKUKO, BOGBO TENUYEN."]}]$q$::jsonb),
(105,'32d840c5b2a9d419742ec90ae4bf2ec6',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Ọ̀ṣẹ́ habla de victoria sobre los adversarios. La persona suele ser acusada de promiscuidad. La pobreza ya se está acabando; hay que ofrendar para que no queden huellas de los malos tiempos. Ifá no deja que sus cosas estén en desorden."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay chismes sobre su vida íntima o teme que lo juzguen injustamente.", "Debe confirmar de qué lo acusan antes de responder (relato de Ọ̀wọ́nrín acusado).", "Siente que termina una etapa de pobreza o tristeza.", "Puede llegar bienestar a su casa (verso de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que en la casa no haya motivos de llanto.", "Vencer a los adversarios y a las acusaciones falsas.", "El fin de la pobreza y la llegada de la riqueza."]}, {"titulo": "Ibi y advertencias", "puntos": ["Acusaciones falsas, sobre todo de infidelidad.", "Hacer mucho sin ver progreso."]}, {"titulo": "Enseñanza principal", "texto": "Lavarse en el río con la medicina de Ifá es dejar atrás la pobreza. Y cuando las deidades no responden, Ọ̀rúnmìlà les hizo notar su descontento hasta que lo escucharon."}, {"titulo": "Relatos reunidos", "puntos": ["La casa de Ọ̀rúnmìlà sin llanto. Le dijeron a Ọ̀rúnmìlà que él y los suyos nunca tendrían motivo para llorar. Ofreció una paloma y 3,200 cauríes.", "Ọ̀wọ́nrín acusado. Decían que Ọ̀wọ́nrín había hecho algo malo, pero no era cierto: lo acusaban falsamente. Le dijeron que podía vencer a sus adversarios si ofrecía un gallo, una piedra de rayo (ẹdùn àrá) y 2,200 cauríes. Cumplió y puso la piedra de rayo sobre Ifá.", "Ọ̀rúnmìlà lava la pobreza. Le dijeron a Ọ̀rúnmìlà que la pobreza dura que lo acompañaba estaba por terminar. Le prepararon una medicina de Ifá y lo mandaron al arroyo a lavar de su cuerpo y de su destino todo lo que pintaba mal. Al terminar le dijeron: '¡La pobreza terminó; ahora llega la riqueza!'.", "Ọ̀rúnmìlà y los tabúes de las deidades. Ọ̀rúnmìlà hacía de todo y no avanzaba. Le dijeron que las deidades no escuchaban lo que les pedía, y que les pusiera enfrente sus propios tabúes; cuando le preguntaran por qué, debía responder que estaba inconforme porque no atendían sus ruegos. Sabía que Ọ̀ṣun no bebe vino de sorgo, que cuatrocientas deidades no soportan el tinte negro y doscientas no soportan la orina. Pintó su casa con tinte negro, la rodeó de orina y le dio a Ọ̀ṣun un poco de vino de sorgo. Las deidades le reclamaron y él les dijo: 'Cada día les ruego y no veo respuesta'. Le aseguraron que sus penas habían terminado."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: una paloma y 3,200 cauríes.", "Contra acusaciones: un gallo, una piedra de rayo (ẹdùn àrá) y 2,200 cauríes; la piedra se pone sobre Ifá.", "Para acabar con la pobreza: baño en el arroyo con la medicina que prepare Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "La piedra de rayo pertenece a Ṣàngó y se pone sobre Ifá. Ọ̀ṣun no bebe vino de sorgo. Las cuatrocientas deidades tienen sus tabúes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Piedra de rayo (ẹdùn àrá), hojas de èsisi, gallo, paloma. Agua de arroyo para el baño."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 105.1 (yorùbá): Ọ̀wọ́nrín-Ṣẹ̀: / a dífá fún Ọ̀rúnmìlà. / Wọ̀n ni: / \"Ọ̀rúnmìlà ati àwọn ará ilé rè / koniiri ràn ẹkún laelae\". / Wọ̀n niki o rúbo. / Eyẹlé ati ẹgberindilógún owó. / Ó rúbọ.", "Verso 105.2 (yorùbá): \"Ọ̀wọ́nrín koṣẹ, / Ọ̀wọ́nrín koro, / wọ̀n ndunrunmo Ọ̀wọ́nrín\": / A ni: \"Ọ̀wọ́nrín a ṣẹ wọn, / ki Ọ̀wọ́nrín wa ṣẹbo\": / Akuko-adiyẹ, ẹdùn-ààrá / ati ogbokànlá owó. / Ó gbọ̀ ó rú. / O fi edùn-ààrá le Ifá.", "REZO: OJUANI BOSHE OMONISHE KAFEREFUN YEMAYA ATI OBATALA BABA BOEFA KERUGBO KOLOWO BUDO INKA LAFESHE KORUBO INTERI SHEKE LOSA KAMIBASHE AMARERA ORISHA ELEGBARA OBOFE OGUN YOBI.", "REZO: OJUANI SHESHERO ABANIDO ASHEBO ASHEBO AGBARO NI ORUNMILA ADDONILO ENI FOBA ONARA OMOFA BOKO NI GBOADUN OBAN ENI AKUKO.", "SUYERE: OSINI BOE KONI OBAN OWO NIFA MEYI LATISHO"]}]$q$::jsonb),
(106,'a2c773571dadd82acb7790c08ff9c123',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Òfún pide ofrendar para ser útil, capaz y querido, como forma de evitar desgracias, y habla de la supremacía de Ifá. La persona no puede quedarse con una sola idea: debe tener la mente amplia para aprovechar muchas oportunidades. No debe ejercer su trabajo solo entre familiares. Entre hermanos, el mayor debe ofrendar para que el menor no se burle de él ni le quite lo suyo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está tan fijado en una sola oportunidad que no ve las demás.", "Teme un cambio muy grande y necesita prepararse sin dramatizar (relato de la gente de Ifẹ̀-Ooyẹ).", "Quiere que su trabajo sea útil y conocido (relato de Ọ̀rúnmìlà y las visitas).", "Está mezclando el trabajo con problemas de familia."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una casa siempre llena de gente; fama.", "Todas las bendiciones llegan fácil.", "Paz en el matrimonio de por vida."]}, {"titulo": "Ibi y advertencias", "puntos": ["Grandes pérdidas por no prepararse a tiempo.", "Trabajar solo para la familia.", "Que el hermano menor desobedezca, se burle o se quede con lo del mayor."]}, {"titulo": "Enseñanza principal", "texto": "Ifá no es solo para la familia: lo que dice Ifá se recibe de todos los que vienen. Y el hermano mayor que se queda dormido puede perder su lugar, como Orò frente a Eégún."}, {"titulo": "Relatos reunidos", "puntos": ["Ifẹ-Ooyẹ y el tiempo de volar. El adivino dijo a la gente de Ifẹ-Ooyẹ que vendría un tiempo en que todas las personas del mundo viajarían por el aire entre el cielo y la tierra, como los pájaros, y que ofrendaran para no sufrir grandes pérdidas entonces. Les pidió algodón de egúngún, cuatro palomas blancas, cuatro carneras blancas, cuatro vacas blancas, un pájaro àgbe y 32,000 cauríes. No ofrecieron: dijeron que ellos ofrendaban para andar sobre la tierra. Por eso no pudieron andar por el aire.", "La casa llena de Ọ̀rúnmìlà. Le dijeron a Ọ̀rúnmìlà que su casa nunca estaría vacía, que todo el pueblo sabría de su fama y lo buscaría. Ofreció un caracol babosa, hojas de ẹ̀sọ y 20,000 cauríes, y prepararon las hierbas para Ifá.", "Ológoṣé y su Ifá de familia. Ológoṣé practicaba Ifá solo como asunto de familia. Le pidieron ofrendar y dejar de hacerlo así. Cumplió, y su vida mejoró: lo que dijera Ifá, eso recibiría de sus clientes, y los campesinos le traían el dinero honrado de sus cosechas.", "Eégún y Orò. Eégún y su hermano mayor Orò venían del cielo a la tierra, y les pidieron ofrendar antes de salir. Eégún ofreció la única ropa que tenía. Al llegar a la primera ciudad, Orò le dijo que entrara a ver, pero Eégún respondió que estaba desnudo. Orò se quitó su ropa y se la dio. Eégún entró vestido y la gente, asombrada, lo cargó en hombros bailando, y él se olvidó de su hermano. Orò se quedó dormido afuera; cuando despertó entró furioso a la ciudad gritando que se lo tragaría, pero como estaba desnudo tuvo que esconderse detrás de una pared."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ifẹ-Ooyẹ: algodón de egúngún, cuatro palomas blancas, cuatro carneras blancas, cuatro vacas blancas, un pájaro àgbe y 32,000 cauríes.", "Ọ̀rúnmìlà: un caracol babosa, hojas de ẹ̀sọ y 20,000 cauríes.", "Ñames y palomas para Ifá.", "La esposa debe tener lista una jarra con cucharón para recoger agua cuando se necesite."]}, {"titulo": "Relaciones espirituales", "texto": "Eégún y Orò son hermanos; Orò no se deja ver por las mujeres. Ifá está por encima de los asuntos de familia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de ẹ̀sọ (Elytraria marginata), algodón de egúngún, ñame, palomas blancas, caracol babosa, jarra con cucharón."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 106.1 (yorùbá): Ọ̀wọ́nrín Fú, Ọ̀wọ́nrín Fú: / a difá fún wọ̀n ni Ifè-Ooyẹ. / Wọ̀n ni: / \"Igbaa kan mbowa, igbakan ma nbọ o, / àwọn omọ aráyé yoo maa rín ni ofurufu / ayé ati ğrun (bi ẹyẹ)\" / Wọ̀n niki Ife (gbogbo ilu naa) wa rúbọ / kioma baa si ofo pupo nigbanaa. / Koniibẹrẹ ni Ifẹ, / ṣugbón ofo tiomaamuwa yoo kari ayé. / Ẹbọ: Ôwú egúngún, / eyẹlé fúnfün mẹrin, / àgutàn fúnfún mérin, / maalu fúnfún mérin, / iyè-àgbe / ati egbàá mẹrindílógún owó. / Wọ̀n gbọ̀ wọ̀n ko rú. / Wọ̀n ni: / \"àwọ̀n ti rúbọ atẹpẹ lori ilẹ o\"; / Àwọn konii rin lofuurufu.", "Verso 106.2 (yorùbá): Ọ̀wọ́nrín Fú ipe: / a dífá f'Ọ̀rúnmìlà. / Wọ̀n ni: / \"ilé Ọ̀rúnmìlà koniidero / (opọ èniyàn ni yoo maa waa), / gbogbo èniyàn ni yoo maa gbọ usi rè / tìi wọn o maa waa\" / Ẹbọ: Igbín, ewé èsọ / ati egbàáwa owó. / Ó gbọ̀ ó rú, / Wọ̀n ṣe ewé, Ifá fún un. / Wọ̀n ni: / \"gbogbo ire yoo maa gba eso wa\". / \"Ọ̀wọ́nrín suena la trompeta\":", "REZO: OJUANI BOFUN IRE AYE OMI BEBE ONISHEGUN YIDU OBAYELERU ADIFAFUN AKONI YEMAYA LODAFUN APAYA ATI OBATALA.", "REZO: OMIBIBE OINI CHEPU LLIDU EBALLALELA ADIFAFUN ACONI LORUBO EGUEFA ACAFOLORICO LODAFUN APALLA UMBARI OCO LAIMBA CHO TA LEGUE DEGUELLE ENI OLUMI ACU EKU EYA LEBO.", "REZO: ORUNMILA ARA OKO ESHU KUMI ISO KOWON BIYOIBO IYEFA OMO ODDUN IFA BENI INI SUA MIWA WOKE KAYENU AIBE AINI PEKUA SESE ORUNMILA KUKU BOLE.", "REZO: MANIARO ILE ALARA NISHAWO LODETAKO OJUANI BOFUN ORIBONI OSA ARAYE ADIFAFUN ARA ARUN ADASILE OKUNI OKAN FIRIPO LODAFUN OLOFIN.", "+++"]}]$q$::jsonb),
(107,'d7f5e775fd98917c7639019e3b386744',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ogbè habla del gran respeto y poder que alcanza quien sigue con devoción lo que dice Ifá. El escepticismo, la desconfianza y la falta de fe de la persona le están frenando el progreso. Ifá le desea muchos hijos fuertes, que su vida sea agradable y que sus cosas no se echen a perder."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Duda de un camino o de un consejo y esa desconfianza frena sus decisiones.", "Quiere que su palabra tenga peso y usarla para arreglar conflictos (relato de Eko).", "Avisó de un peligro y salió perjudicado por quien no quiso escuchar (relato de Adifala y Oṣin).", "Espera bienestar y descendencia."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Gran influencia: lo que diga será escuchado hasta en el cielo.", "Vida larga.", "Muchos hijos llenos de vida.", "Que la muerte, la enfermedad y la pérdida salgan de la casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desconfiar del babaláwo y burlarse de sus predicciones.", "Una muerte repentina por no ofrendar.", "Ajogun que se meten en la casa."]}, {"titulo": "Enseñanza principal", "texto": "Nadie debe desacreditar lo que anuncia un babaláwo. Ọṣin encerró al adivino que le predijo la muerte, y cayó del techo el mismo día que llegaba su novia."}, {"titulo": "Relatos reunidos", "puntos": ["Ẹko, cuya palabra es final. Ọ̀bàràbobo consultó para Ẹko, descendiente de Àjàlọ́run, y anunció que lo que Ẹko dijera siempre se escucharía en el cielo. Ofreció una carnera. Quien recibe este signo tendrá mucha influencia y vivirá largo tiempo.", "Adifala y Ọṣin. Adifala consultó para Ọṣin y le dijo que ofreciera siete carneros y 14,000 cauríes para evitar una muerte repentina en los siguientes siete días. Ọṣin no ofreció, y además mandó apresar y atar al adivino. Adifala cantaba cada día: 'Soy el adivino cuyas predicciones se cumplen en cuanto salen en el tablero: mañana Ọṣin irá al río, barrerá la casa, subirá al tejado…'. El día que le traían una novia de lejos, Ọṣin barrió de prisa y subió por una escalera al techo para verla llegar. Se cayó y la pared se le vino encima. Mandaron soltar a Adifala, que pidió de inmediato diez carneras, diez gallos, diez vacas y la propia novia como ofrenda. Mientras se hacía la ofrenda, Ọṣin despertó.", "El gusano en el pantano. El gusano lloraba porque no tenía hijos. Le pidieron ofrendar y le desearon muchos. Fue al río, se instaló en el pantano, ahí se casó y empezó a tener hijos. Cantaba alabando a Ọ̀bàrà bo bòó, como el sonido de los gusanos al meterse en su madriguera.", "El fuego que espanta a los ajogun. Òtòntò Ìròkò consultó para la gente de la ciudad de Ìdó, el clan que usa la llama ardiente para alejar a la muerte. Preguntaron si los ajogun los atraparían. Ofrecieron, y la muerte, la enfermedad y la pérdida salieron corriendo. Cantaban: 'Que la muerte de esta casa empaque y se vaya; encenderemos el fuego de Ifá para quemarla'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ẹko: una carnera.", "Ọṣin: siete carneros y 14,000 cauríes; tarde: diez carneras, diez gallos y diez vacas.", "Contra los ajogun: la ofrenda se pasa por una llama ardiente antes de presentarla a Èṣù."]}, {"titulo": "Relaciones espirituales", "texto": "Àjàlọ́run es el antepasado de Ẹko. Èṣù recibe la ofrenda pasada por fuego. Ifá defiende la palabra del babaláwo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Carnera, carneros, gallos. Fuego (la llama de Ifá) para alejar a los ajogun."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 107.1 (yorùbá): Obàràbobo awo Eko: / li o dífá fEko / tiiṣe ọmọ Ajàlọ̀run. / A ni: / \"eyiti Eko ba wi ni wọn maamur'orun\". / Àgùtàn ni ẹbọ. / Ó gbọ̀ ó rú. / Ifá I: / \"eniti a dá'fá fún a l'àṣẹ ninu ayé\". / \"Emi rẹ̀ yoo gun\".", "Verso 107.2 (yorùbá): Irofá-ab'ẹnújigini awó ilé Ọ̀rúnmìlà: / li o dífá f'Adifala / nlọ dífá f'Qṣin. / Ó niki Oṣin rúbo / kiomaba kú titi qjo meje: / Agbo meje ati egbàáje owó ni ẹbọ. / Oṣin kò ko rú. / O mu Adifala de, / Adifala nkorin bayi: / Emi Adifaṣẹ leti Opon / Ibaratiele, Ibaratiele, / Ọla dandan l'Oṣin ma kú. / Ibaratiele, Ibaratiele, / A gb'amu a re Odò, / Ibaratiele, Ibaratiele. / A m'owẹ a gbalẹ'de, / Ibaratiele, Ibaratiele. / A gbe'ba a g'orule ati bẹẹ bẹẹ. / Babaláwo naa nṣe bayi lojoojumo. / O wa di ọjọ́ kan bayi Ọjọ́ naa jẹ ọjọ́ / ti wọn ngbe iyàwó / bowa fún Qṣin l'okere. / Oṣin ni: / Òun a yara gbalẹ / kiwọn too gbe iyàwó de, / Ó mu qwọ o ngbalẹ. / Bioti gbalẹ tan, / o ni oun a gun'ke ki oun ṣọ wọn wo. / O gbe iba o gun orule / lati ri iyàwó l'okere. / Ó ṣubu. Ogiri wo luu. / Wọn ranṣẹ lọ da Adifala wa. / Adifala ni: / Kiwọn yara lọ rú ohun méwà oke ilé, / àgùtàn méwà, akuko-adiyẹ méwá, / maalu méwà ati iyawo / ti wọn ngbe bọ l'okankan ati bẹẹ beẹ. / Bi wọn ti nrúbọ lọwọ ni Qṣin ji. / Ifá niki a maṣe maa d'éjà Babaláwo.", "REZO: OBARA BOGBE LANTOSI OMODU OMI KE EBOADA FELEBO, OKILANFIRU EKU, OKILANFIRU EYA, OKILANFIRU JIO JIO. TO IBAN ESHU SOKOBONI ESTERA ELEBO.", "REZO: OBARA BOBE LANTOSI OMO EGUEI CHIRIGUNCHI LENI LEBO ENI AUN LANTOSI AGUN CHIRI GUNCHI OMO OSO A UN ACARODA OMOONI ECHIGUINI AÑO OBURU AMPIRIN OCURU EMIBUCU AÑI AMPRIMOCURU ONIBUCU INIBI COCUNABU LEGUO QUINIAFIRU ANFIO ADIE OLLANRU LOGU TIN IAFIRA ADIE FIO FORUNOMI APEPE A BIADIE LECHORUN LLALLEO EBANQUINU ENIQUI ANFUFUBO ERANLOSEMERERU QUEPO LODAFUN QUIERUN LODAFUN ELEBO.", "REZO: OBARA BOBE LANTOSI OMA QUI CHERE OMA ERU CADANINCHEMA ELEBA ERIAMBO LEBO A UN MIN SI OMA ETUCHE RECUNCHE OMA ERUNCOCO ERA NINCHEMA ENIN QUIRREFIRU AFINCURA BACLE BAMBO COCO BACU LOGUO CHEREGUN NECHE ABE DAFE LEBO INI QUIRAN FURI OFI ERALLU BARU COLAMORU LEGUO CHEREGUNCHE EBO DAFERU ENI PUIN LANFIRU AFI ADIE JIO GIO FIORUBA.", "REZO: OMO OSUN EMO SHEREGUNDI OMO OSUN KARODA OMO OMO ELEGBA OMO LATONSU OMO IKU AUN SHIRIGUNDI AFIN AKUNI AMBI IKU UMBO KOKUMARE OMO OGUN LOWO KINI EFINI AUN FI AYA BOLU ORUN UMBO KOYA MARUN LOWO RINI AMBIRU ANFI ADIE JOKONU ONI EMA KUEKUE BI ADIE TOSHARAN YEYEO ABANKUNI OMIKI EFASI.", "REZO ARARA: DASIGBO OBARA BOGBE. DASI AFAFA DAGINU AFARA", "SUYERE: OBARA BOBE IFA TIMODASHE IFA TIMODASHE OBARA BOBE IFA TIMODASHE IFA TIMODASHE.", "REZO: OMO FA AGBORUN IFA BARA NI IMALE ATEFA NI ODDUN, OGBARA BOGBE IWA ASADELU OFO IGBODUN EBBO ASHILEKUN EYELE LEBO ASHOLA FUNFUN LEBO LERI EBBO OFA META LEBO, OKOLELAGUN OWO.", "SUYERE: “IOLAMO DE MONIFA LOPA ANAYE OBARA BOGBE IFA TIMODASHE”", "REZO: OMO OSUN EMI SHREGUNDI OMO OSUN KAROLA OMO ELEGBA OMO LANTOSI OMO EKI AUN SHEREKUN DI AFIN OKUNI AMBI IKU ILE UMBO KOKU MARU OMO OGUN LOWO KINI EFIRU AUN FI EYA ROBI ARUN UMBO KOYA MARUN LOWO ABAKUNO ONIKI AFIRI ORUBO ANFIARAN ASHOSI ASHENE SIRU KEBO KODAFUN ELEBO KIERUN KOLAFUN ELERU KODAFUN ELEGBA SHIRIGUNSHI."]}]$q$::jsonb),
(108,'6c8a059ef7be1f187d00b34240a938a2',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ọ̀yẹ̀kú advierte sobre la insubordinación en la casa y en el trabajo. La persona enfrenta a un compañero o socio muy dominante. Ifá le desea buena fortuna con las mujeres y en los negocios, y pide ofrendar por su lugar de trabajo, porque hay quien quiere cerrarle el camino del sustento."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un socio o compañero que quiere mandarlo todo.", "Duda entre cumplir una obligación o mantener su independencia (relato del tamborero del rey).", "Sus clientes o seguidores no reconocen su autoridad (relato de Ọ̀rúnmìlà).", "Desea encontrar pareja (relato de Ṣèkèrè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Muchas esposas o pareja; la gente lo quiere.", "Éxito en el negocio.", "Que no le cierren el camino del trabajo y del alimento.", "Recuperar el dominio sobre los suyos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Insubordinación: el tamborero que ya no quiere servir al rey, el esclavo que no quiere servir a su amo.", "Clientes o subordinados que rechazan su autoridad.", "Enemigos que quieren truncar su alegría."]}, {"titulo": "Enseñanza principal", "texto": "Lo que uno esconde con soberbia puede encontrarlo quien ofrendó. Los campesinos no ofrendaron y escondieron el grano apretándolo con los talones; Èṣù le enseñó al pájaro a escuchar las huellas."}, {"titulo": "Relatos reunidos", "puntos": ["El tamborero del rey. Alukoso, el tamborero del rey, dijo que ya no le serviría. El esclavo dijo que nunca serviría a su amo. Para eso se apacigua a Ifá con una gallina, y Ifá la acepta.", "Ọ̀rúnmìlà y los clientes rebeldes. Cuando los clientes de Ọ̀rúnmìlà rechazaron su autoridad, le pidieron diez ratas, hojas de irẹ y jabón. Ofreció, y el babaláwo trituró todo para que se bañara con ello.", "Ṣẹ̀kẹ̀rẹ̀ y las esposas. Ṣẹ̀kẹ̀rẹ̀ lloraba porque no tenía esposa. Le dijeron que tendría muchas, pero que debía bailar y hacer sonar su música para ellas. Cuando empezó a sonar, todas las muchachas lo siguieron bailando y sin darse cuenta entraron a su casa; muchas se quedaron y le dieron hijos. También tuvo tanto dinero que se lo tejía al cuerpo.", "El pájaro y los granos escondidos. Àparò, el pájaro del monte, salía a buscar su comida y ofrendó. Los campesinos también habían consultado y les dijeron que ofrendaran para que no les encontraran sus granos, pero respondieron que nadie se los robaría: sembrarían el maíz y el sorgo y los apretarían con los pies y los talones. Cuando llegó el pájaro, solo veía huellas. Èṣù le dijo que escuchara las huellas; el pájaro escarbó donde sonaban y encontró el maíz. Los campesinos volvieron y no entendían cómo, escondiéndolo tanto, los pájaros lo hallaban."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para apaciguar a Ifá: una gallina.", "Ọ̀rúnmìlà: diez ratas, hojas de irẹ y jabón, triturados para bañarse.", "Para el lugar de trabajo: la ofrenda que marque Ifá contra los que quieren bloquearlo."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù guía al pájaro hacia el grano. Ifá recibe la gallina que apacigua."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de irẹ (Funtumia elastica) con jabón, para baño. Gallina, ratas, maíz, sorgo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 108.1 (yorùbá): Alukoso Ọba / i oun ko dẹ sin'Ba. / İbárá-Ọ̀yẹ̀kú o gbó bẹẹ ri a? / Alulù-Ọba / i oun o tun sin'Ba. / Ọ̀bàrà-Ọ̀yẹ̀kú o gbọ̀ bẹẹ ri a? / Erú ni: oun ko sin olúwa. / Agbebo-adiyẹ ni ki afi bọ Ifá. / Biabafi Agbebo-adiyẹ bọ Ifá. / Ifá yoo gb'ẹbẹ.", "Verso 108.2 (yorùbá): Iṣin-niif'orí-gbogbo-iṣ'ade, / Ogbo-ọ̀pè-nii-f'orùn-i-ṣ'aron: / wọ̀n ṣe Ifá fOrúnmila / nigbati wọ̀n ko sin in mọ. / Eku-awosin méwà, ewé (Irẹ) / ati Ọ̀ṣẹ́ ni ebọ. / Ó gbọ̀ ó rú. / Babaláwo gun wọn pọ / fun un kioma fiwẹ.", "REZO: OBARA YEKU KEKERE OMA AYE ERI OMI AYE AIBO OMA AYE APUPARERE APUPE GOGO IKU OPAWEWE IKU APASHERE ORUNLA LORUGBO IDA AGUTAN EBEWA AYAPA, AKUKO LEBO.", "REZO: QUEQUEERE OMA ERE OMA ALLE OIBO OMA ALLE AKUPARARE ACUPE GE GE IBUPA CHERE LORUBO IDA AGATAN EBEGUA AYAPA AKUKO LEBO.", "REZO: QUE QUE ERE OMA AYE NIBO AYE OKUPARADE AKUPE GE GE ISUPA SHERE LOROBO IDA AGETAN EBEGUA AYAPA AKUKO LEBO.", "REZO: OBARA YEKU OMA ERE OMA AYE, OMA AYE APUPARADE APUPE GEGE IHU APASHARE, ORUNLA LOROBO IDA AGUTAN EBEMA AYADA, AKUKO LEBO. AQUI FUE DONDE OBATALA MANDO A BUSCAR A LOS MONOS PARA DARLES LAS GRACIAS Y ESTOS NO FUERON, POR FALTAS QUE TUVIERON."]}]$q$::jsonb),
(109,'192b0b6fc741aab2a018fb3da1c25e9a',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ìwòrì establece que el dinero es importante, pero nunca más que la sabiduría, el conocimiento, la salud y el buen carácter. La persona necesita crecer en lo espiritual y mantener el equilibrio emocional. Ifá le desea hijos, una casa y vida agradable, y pide ofrendar contra los que echan a perder las cosas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está tomando todas sus decisiones solo por el dinero (relato del debate con Ọ̀rúnmìlà).", "Necesita cuidar su equilibrio emocional y su vida espiritual.", "Desea tener hijos o construir su casa."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Muchos hijos.", "Construir una casa.", "Descanso para los niños que tienen pesadillas.", "Respeto y protección de la comunidad del cielo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Amar demasiado el dinero: le estropea el carácter.", "Despreciar a los babaláwo y a los que curan.", "Que alguien le destruya lo que ha logrado.", "Niños con pesadillas por sus compañeros del cielo."]}, {"titulo": "Enseñanza principal", "texto": "El dinero engrandece a la persona, pero también puede arruinarle el carácter; tener dinero no evita la ceguera, la locura, la invalidez ni la enfermedad. El buen carácter es la esencia de la belleza. Hay que honrar a Ifá y a la sabiduría."}, {"titulo": "Relatos reunidos", "puntos": ["La gente que corría tras el dinero. Toda la gente decía que el dinero era lo más importante y dejaba todo por perseguirlo. Ọ̀rúnmìlà les dijo que en parte tenían razón y en parte no: el dinero engrandece, pero quien lo ama demasiado echa a perder su carácter, y el dinero no evita la enfermedad. Les pidió una rata, un pescado, una chiva, una jícara de ñame machacado, otra de ẹ̀kuru y 20,000 cauríes. Se negaron e insultaron a los babaláwo y a los curanderos. Con el tiempo enfermaron, tristes y sin apoyo, y empezaron a morir día tras día. Cuando ya no aguantaban, fueron a pedir perdón. Desde entonces los babaláwo son tratados con respeto en todo el mundo.", "La rana blanca. La rana blanca iba a ser esposa del pantano y preguntó si tendría hijos. Ofreció y tuvo muchísimos, todos blancos; podía tener cuatrocientos de una vez. Le advirtieron que ofrendara también contra los que echan a perder las cosas, pero respondió que en su pantano nadie la molestaría. Èṣù les mostró a los campesinos la tierra fértil junto al pantano; llegaron a cultivar y le destruyeron la casa.", "Egbé y las pesadillas. Un grupo de Egbé venía del cielo a la tierra. Al dormir tenían pesadillas: veían a sus compañeros del cielo. Les dijeron que dieran ẹ̀kuru blanco para que esos compañeros comieran. Ofrecieron y descansaron. Así se fundaron las asociaciones en la tierra, y es la asociación del cielo la que cuida la honra de uno en la tierra. 'No dejes que nos humillen.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Una rata, un pescado, una chiva, una jícara de ñame machacado, una jícara de ẹ̀kuru y 20,000 cauríes.", "Para hijos: una azada; y otra ofrenda contra los que echan a perder las cosas.", "Para los niños con pesadillas: ẹ̀kuru blanco servido a los mayores y a los niños."]}, {"titulo": "Relaciones espirituales", "texto": "Egbé, los compañeros del cielo, cuidan a los niños y a las asociaciones. Èṣù castiga a la rana confiada. Ifá y la sabiduría deben honrarse por encima del dinero."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹ̀kuru blanco (frijol cocido sin guiso), ñame machacado, chiva, rata, pescado, azada."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 109.1 (yorùbá): Ọ̀ròbàntà-awúwobi-owú: / a dífá f'Ayé, / nijo ti gbogbo omọ aráyé / ńpón owó pe kosi ohun miran / mọ ninu ayé tio tun níyì mọọ rara. / Wọ̀n ni àwọ̀n o kọ ohungbogbo silẹ, / àwọn o maa sáré mọ owọ. / Ọ̀rúnmìlà ni eyiti ẹ nro niti owó bẹẹ ni, / eyiti ẹ nro niti owó bẹẹ kọ. / Ifá lia ba maa yẹ. / Ọgbọ̀n lia ba maa yẹ, / àwọn lia baama bu iyin fún. / Agbeniga laape owó. / Abiwàjẹ laape owó. / Eni ba feran owó l'afẹju, / iwà rẹ a bajẹ. / İwàrere li oṣo èniyàn. / Bi ẹ n'owó lọwọ / ko wipe ki ẹ ma di afójú, / ko wipe ki ẹ ma di aṣiwèrè, / ko wipe ki ẹ ma di aro, / ko wipe ki ẹ ma di olókùnrùn / ati bẹẹbẹẹ, / abukù ara gbogbo le de ba yin. / xẹ̀ lọ t n n / ki ẹ tún èrò gbà, / ki ẹ mu iwàrere, / ki ẹ mu ọgbọ̀n, / Kiẹ wa rúbo, / ki ara le ro yin tinutode. / Wọ̀n ni: Kil'ebọ? / Eku, eja, ewúrẹ, / igba-ewo, igbá-ekuru / ati egbàáwa owó. / Wọ̀n kọ, wọ̀n ko rú. / Wọn nbu Babaláwo, / Oniṣègün ati Adáhunṣe. / Wọ̀n nfi wọn ṣe yeye ka'de. / O pẹ diẹ ṣa ni wọ̀n bẹrẹsii ṣaisan. / Ara wọ̀n ko'da, / ibinújé wọ̀n po, / won ko r'eni gba wọn. / Wọ̀n nkú li ojoojumo, / ọ̀ràn ibajẹ ati itiju nba wọn, / wọ̀n ko le pe Babaláwo / ati bẹẹbẹẹ wa goa wọn. / O pẹ titi ara wọn ko gba eyi mọ. / Nikẹhin wọ̀n wa bẹ Babaláwo. / Lati ọjọ naa ni àwọn Babaláwo / ti ńniyi ninu ayé.", "REZO: OBARA WORI ANKO NIYEN ERANKO EKU IBA EWEFA ELEBO OBARA WEREKO ADIFAFUN ESHU.", "REZO: IWORY ESHU OFORESO QUEJUNQUE IBADAROSO ONI ODA LEI OGUN BEREQUE LLAMA ALLANA ADOFAFIN SEGUA ERU LENI OTI ADIE MEGUA AICORDIE EKU EYA EBELLO OWO.", "REZO: OBARA ORI AMACONILLA ERA AGUTAN LEBO IBA AGUEFA.", "REZO: OGE OKUNRIN ADIFAFUN AGGAYU EDE KETE ABE ILOSUN BOGBO AIRE MINU BOGBO OGE IKU EDE KAFEREUN OPE.", "REZO: OBARA NIFA ELEGBARA BARATIYO OMO IFA ELEGBARA IFA WA OMO ELEGBARA IFA LANIRE OBARANIRE AWO IFA ONLO BERE LAYO OBARA MORI, ELEGBARA OMO IFA IRE ELEGBARA INLE MERI LAYE INLE TIMBELAYE OBARA JIRE IWORY IFA ODUDUWA BARA LAYE BI AYE OLOFIN IRE AYE TIMBELAYE."]}]$q$::jsonb),
(110,'319db4407e4266500dc289a081011993',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ìdí advierte sobre la pérdida de la independencia y de la integridad. La relación de pareja se desequilibra por una demanda que no se está cumpliendo. Ifá pide quedarse en casa y no salir de viaje sin consultar el momento; y pide ofrendar para que sus secretos no salgan a la luz y no alejarse de su familia, que es la que los cubre."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una exigencia de la pareja está desequilibrando la relación y hay que hablarla.", "Él o su comunidad temen una amenaza de fuera o una separación de familias (relato de Ọlọ́fin y los forasteros).", "Tiene un viaje posible y debe confirmar si es el momento."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que sus secretos queden cubiertos.", "Hijos.", "Protección para la gente del pueblo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Forasteros que llegan sin invitación y se llevan a la gente.", "Salir de viaje sin el permiso de Ifá y perder la fortuna en la casa y fuera.", "Exponer sus secretos o alejarse de su familia.", "La deshonra por la vida sexual sin orden."]}, {"titulo": "Enseñanza principal", "texto": "Hay que consultar a Ifá antes de emprender un viaje. El loro salió sin hacer caso, no encontró ñame en Ifẹ, y mientras tanto lo vendieron también en su casa. Son los nuestros quienes cubren nuestros secretos."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlófin y los forasteros. Le advirtieron a Ọlófin que un día llegarían forasteros sin invitación a juntar a las familias del pueblo y llevárselas a otra ciudad. Le pidieron aceite de palma para Èṣù, dieciséis palomas para rogarse la cabeza con una cada día, y una medicina para llevar al mercado y que la gente se frotara el cuerpo con ella.", "Las mujeres de vida sin honor. El adivino de las mujeres consultó para las que se iban con todos los hombres y les advirtió que se arriesgaban, que así se pierde el honor y que nadie prospera de ese modo. Les pidió reconocer su error y ofrecer dos palomas, dos caracoles babosa, òrí, 8,000 cauríes y medicina de Ifá.", "El loro que no se quedó en casa. A Odíderé, el loro, le pidieron ofrendar y quedarse en casa. No hizo caso: lo llamaron de fuera y salió a Ifẹ a comprar ñame. Cuando llegó ya se había vendido todo y solo quedaban los tallos secos. Mientras tanto, en su casa también llegó el vendedor de ñame y se acabó antes de que él regresara. Ifá le recordó: 'Te dije que me consultaras antes de cualquier viaje'. Desde entonces se queda en casa.", "Olọ̀bàrà cubre a Ìdí. Olọ̀bàrà iba a cubrir a Ìdí y ofreció; así los secretos quedaron tapados. 'Es quien nos quiere el que nos cubre; son los nuestros los que cubren nuestros secretos.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọlófin: aceite de palma para Èṣù, dieciséis palomas (una diaria para la cabeza) y medicina de Ifá para el mercado.", "Las mujeres: dos palomas, dos caracoles babosa, òrí, 8,000 cauríes y medicina de Ifá.", "Para cubrir los secretos: una tela."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù recibe el aceite de palma. Orí se ruega a diario con paloma."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de olúṣesájú (Petiveria alliacea) y oriji machacadas en agua, con sangre de paloma, para frotarse el cuerpo. Hojas de ẹ̀sọ (Elytraria marginata) con iyẹ̀rẹ (pimienta, Piper guineense) cocinadas con caracol en sopa; ẹ̀sọ con òrí para uso externo, o machacadas con jabón para baño."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 110.1 (yorùbá): Èèsin-wara: / a dífá f'Ọlófin. / A ni: Àwọn èniyàn kan mbowa baa ni qjo aipẹ. / Wọ̀n yoo maade ará ilú l'okun nilé / tabi loko losi ilẹ miran. / A niki Ọlọ̀fin rúbọ: / Epo kiafi bọ Eṣú nipa tituusii lori, / ẹyẹlé mẹrindilógún, kio maafi okẹṣkan bo orí lojojumo / ati ewé Ifá / naa si qjà ki gbogbo ilú maa fi pa'ra.", "Verso 110.2 (yorùbá): Igbá ori-amu awo àwọn Obirin, / a dífá f'Agbèrè obirin / gbogbo okunrin, / li o nfi Ìdí ba Ìdí rè. / Wọ̀n ni: / Owò aipe ni o nṣe yi. / Obirin agbere kiiniyi di alẹ. / Obirin kii f'owó Ìdí ila. / A niki o jéwọ̀ òbùn kiowa rúbọ: / Eyẹlé Méjì, igbín Méjì, òrí, / egbàárin owó ati ewé Ifá.", "REZO: OBARA DI BARA BARADI BARA BARADI. ADIFAFUN AWO OLUWO EKOROKO OMA SHOKOYO EURE, OWO LA MENI ELEBO.", "REZO: BARA BARA DI BARA DI ADIFAFUN AWO OLOBU OCO ROCO OMA KONKOLLO EURE LEBO OWO MENI.", "SUYERE: NAMIBA ORE NAMIBA OSIRE IKU BOFOWAO NAMIBA OSIRE OFO BA FOEBO NAMIBA OSIRE EYO BA FOWAO NAMIBA OSIRE ARUN BA FOWAO NAMIBA OSIRE.", "SUYERE: OBARA DILA OMO LAYE EBBO ODARA NILE IYE MAFUN.", "REZO: POPO ELEBURO EYE OKUN ARARE GOZAYE OSA IYO ELEBURE OBAKUE NIBI ARARE.", "SUYERE: NAMBA ORE NAMBA OSIRE IKU BAFOWAO MAMIBA OSIRE ORUN BAFOWAO MAMBA OSIRE EYOM NAMBA OSIRE OFO BAFOWAO, NAMBA OSIRE OGO.", "SUYERE: OBARA DILA, OMO LAYE EBBO OBARA NILE IYE MAFUN", "SUYERE: OMODE FOGUOFA OBA FESUCUA EFUREFIGUO OGUN KUKUTEBARA."]}]$q$::jsonb),
(111,'7d70dfbb779463cc00528c97d87d2c5f',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ìrosùn llama a la persona a iniciarse en Ifá para asegurar sus bendiciones: su éxito depende de su crecimiento espiritual. Ifá le pide hacer regalos a los niños y a los gemelos. Para tener riqueza e hijos, la riqueza debe llegar primero. No debe dejarse arrastrar a peleas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que para avanzar necesita aprender y profundizar en su práctica (relato de Ọ̀bàrà Ìrosùn en la arboleda de Ifá).", "Se pregunta si debe estudiar Ifá o iniciarse.", "Desea tener hijos (relato de la hierba Esùsú)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ser babaláwo: el hijo de Ọ̀bàrà Ìrosùn es babaláwo.", "Hijos, incluso gemelos.", "Riqueza que llega antes que los hijos para poder criarlos.", "Paz mental."]}, {"titulo": "Ibi y advertencias", "puntos": ["Tener hijos sin recursos: penuria y enfermedad.", "Pelear por ser el primero.", "Descuidar el aprendizaje de Ifá."]}, {"titulo": "Enseñanza principal", "texto": "Antes de ponerle nombre a un hijo se mira alrededor: el rey llama a su hijo Corona y el rico lo llama Dinero. La riqueza va primero y el hijo después, porque con la riqueza se cuida al hijo."}, {"titulo": "Relatos reunidos", "puntos": ["El hijo de Ọ̀bàrà Ìrosùn es babaláwo. Cuando vieron a Ọ̀bàrà Ìrosùn en el bosque de Ifá, le pidieron diez ratas, diez pescados, un osù y 20,000 cauríes. La persona debe empezar a aprender Ifá, y cuando lo domine, se le planta su osù.", "Ẹsúsú tendrá hijos. 'Ifá nos favorece, adoremos a Ifá; Òrìṣà-ńlá nos dio hijos.' Le dijeron a ẹsúsú, una hierba parecida a la caña, que tendría hijos, y le pidieron una chiva, 3,200 cauríes y medicina de Ifá.", "La paloma y los gemelos. La paloma lloraba por hijos y preguntó si la vida le sería grata. Ofreció muchas bolas de osùn y empezó a tener gemelos, un macho y una hembra. Por eso la paloma pone dos huevos y nunca uno. 'Ọ̀bàrà se frota osùn en brazos y piernas, pero evita los ojos.'", "La riqueza y el niño. La Riqueza y el Niño venían juntos del cielo a la tierra, y discutían cuál era el mayor. El Niño se plantó y no cedió; la Riqueza, viendo que la pelea podía impedir que ambos llegaran, le dejó pasar primero. El Niño nació, pero para comprarle la esponja, el jabón y la ropa, todos pedían riqueza, y el niño vivía en penuria y enfermo. Entonces dijeron: 'Que la riqueza venga primero, porque con ella se cuida al hijo'. Desde entonces la Riqueza es la mayor y el Niño el menor."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Diez ratas, diez pescados, un osù y 20,000 cauríes; iniciarse y aprender Ifá.", "Ẹsúsú: una chiva, 3,200 cauríes y medicina de Ifá.", "Para hijos: muchas bolas de osùn y regalos a los niños y a los gemelos (ìbejì)."]}, {"titulo": "Relaciones espirituales", "texto": "Òrìṣà-ńlá da hijos. Ìbejì, los gemelos, reciben regalos. Osù es el báculo que se le planta al iniciado."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹsúsú (Saccharum spontaneum), osùn (madera roja de Angola) para frotar brazos y piernas sin tocar los ojos, ratas, pescados."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 111.1 (yorùbá): Ọba bimo rè, / ó sọ qmọ rẹ̀ l'Ade. / Olowó bimo rè, / Ol'owó o sọ ọmọ rẹ̀ l'Ajé. / Ehinkulé eni li aiwo / kia too sọ ọmọ eni l'oruko. / Eyin ko mope pmọ Ọ̀bàrà-İrosù, / Babaláwo niise?: / a daa fún wọn nijọ tiari Ọ̀bàrà-İrosù / ni Igbó-Ifá. / A niki wọ̀n rú: / Eku mẹwà, eja méwà, Osù / ati egbàáwa owó / ki o bẹrẹsiiko Ifá, / biobamo Ifá kiari Osù fún un.", "Verso 111.2 (yorùbá): Ifá gbe'ni luyi kiabo Ifá, / Òriṣà gbe'ni luyi kiabọ Ọ̀riṣà, / Oriṣà-nlá li o ngbe'niluyi ọmọ: / a daa f'esusú / Wọ̀n ni: / \"esüsú mi a niyi omọ\". / Nitorinaa kiò rú: / ewurẹ, ẹgberindilógún owó ati ewé Ifá.", "REZO: OBARA KOSO IFA DURO IFA NIRE IREKU KAFEREFUN ORUNLA,ESHU ATI OGUN.", "REZO: OBARA ROSO IFA DURA IFANIRE IREKU KAFEREFUN ORUNLA KAFEREFUN ESHU KAFEREFUN SHANGO OMA OBINI ACUEBABA OBA AWO ALARA ADIFAFUN ALARA INTORI BELU AURE LEBO ADIE ERE EREBE RELOGUO ADIFAFUN EYELE TINCHOSA OLOKUN ELLO EWE IBANARI TOMATE CIMARRON ADIE EKU LEBO. IFANIRE ARICU KAFEREFUN ORUNLA Y OLOKUN.", "LLAMADA A SHANGO: OBASHE NI SHANGO OMO ALARA OBA EKUN OBASHE NI SHANGO OMO ALARA OBA EKUN.", "REZO: OBARA KOSO AGOU IBODE NI SHANGO AWO OBA ALARA OMO OBA OLUO POPO KOYE BI OSOBO LEYEBE INLE SHANGO OBARIYE OBA ASHE OMO OKUN AGBA ISHE OMO SAGUASHE NI OMO ASHE OKOKONO OKUN IBASHE NI SHANGO.", "REZO: AZOJUANO OLUO POPO, ADIFAFUN WARA ARUN INLE, LODAFUN SHANGO BOLELE OBARA OLUOPOPO."]}]$q$::jsonb),
(112,'88b3d8e618e35d4cebf98636eafd670f',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ọ̀wọ́nrín, en lo malo, habla de alguien que actúa sin razonar; en lo bueno, de mucho potencial para prosperar. La persona necesita calmarse para tener éxito. Todo lo que desea le llegará, pero debe ser paciente: cuando deje de perseguir y descanse, la fortuna llegará a su mano. No verá ajogun si ofrenda en el río."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita calmarse antes de decidir.", "Teme la envidia después de destacar (relato del antílope Egbin en el baile).", "Busca mejorar su economía o ser reconocido en su trabajo (relatos de Ọ̀rúnmìlà y de Yemeké)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Brillar en una reunión o fiesta.", "El año de la riqueza para el que estaba en la pobreza.", "Que todo lo bueno llegue a su casa sin esfuerzo.", "Que la guerra no alcance a su ciudad."]}, {"titulo": "Ibi y advertencias", "puntos": ["Actuar como loco, sin pensar.", "Envidiosos que preparan veneno.", "Correr detrás de la fortuna sin alcanzarla."]}, {"titulo": "Enseñanza principal", "texto": "A veces se busca la fortuna por todas partes y no se alcanza, y llega cuando uno se recuesta. Y el veneno preparado para otro termina dañando a quien lo carga."}, {"titulo": "Relatos reunidos", "puntos": ["El antílope en la fiesta. Ifá consultó para Ẹgbin, el antílope, que iba a una fiesta de baile, y le pidió dos gallinas y 3,200 cauríes. Ofreció y en la fiesta brilló más que todos. Los demás, celosos, mandaron al caballo por una medicina para matarlo. Cuando el caballo regresaba, empezó a llover, la gente se dispersó, la lluvia cayó en la medicina y le salpicó el cuerpo al caballo. El veneno lo enloqueció. Desde entonces los caballos salen de estampida sin que nadie los guíe.", "El año de la riqueza. Ọ̀rúnmìlà estaba rodeado de dificultades y pobreza. Le dijeron que su año de riqueza había llegado. Ofreció una paloma, sal y 2,000 cauríes.", "Yemeké busca la riqueza. Yemeké, muy hábil en Ifá, fue a ejercer a los bosques de Ẹ̀gbá y preguntó si ahí tendría riqueza. Ofreció y la buscó por todas partes: se paraba y no la alcanzaba, se agachaba y no la alcanzaba, viajaba y no llegaba. Cuando por fin se recostó a descansar en su cama, su mano tocó toda la fortuna que deseaba.", "Olúwòó y el río Ọbà. Olúwòó, rey de Ìwó, preguntó si la guerra que se acercaba lo atraparía. Ofreció en una calabaza ògbún y la puso en el río Ọbà, que entonces era apenas un canal. El río aceptó la ofrenda, sorprendido de recibir tanto. Se cerró el cielo, tronó, cayó una lluvia torrencial y el río se llenó. La guerra llegó a la otra orilla y no pudo cruzar; los guerreros buscaron otra ruta y no la hallaron, y como no podían quedarse más de siete días sin botín y se les acababa la comida, se fueron jurando no volver. Desde entonces es tabú sacar agua del río Ọbà con una calabaza ògbún."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El antílope: dos gallinas y 3,200 cauríes.", "Ọ̀rúnmìlà: una paloma, sal y 2,000 cauríes.", "Contra la guerra: la ofrenda en una calabaza ògbún, puesta en el arroyo."]}, {"titulo": "Relaciones espirituales", "texto": "Ọbà, el río que protege a Ìwó, acepta la ofrenda y detiene la guerra."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Calabaza ògbún, gallinas, paloma, sal. Tabú: sacar agua del río Ọbà con calabaza ògbún."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 112.1 (yorùbá): Àgbe l'olohun-ere, / Àlùkò l'olohun-oro, / Ọ̀bàrà'Wọ̀nrín / olohun-maṣoromaṣoro: / a dífá f'Egbin ol'orun-gogoro / nlọ s'ajo ijó, / wọ̀n niki ó rú: / Agbẹbo-adiyẹ Méjì / ati egberin-dilógún owó. / Egbin gbó ó rú, / o de ajo, / o f'ijó tẹ gbogbo wọ̀n biatiso fún un. / Inú bi àwọn elẹgbẹ rẹ̀ ni ajoijó, / wọ̀n ran Ẹṣin lọ mu oògùn / wa ki wọn lefipa Egbin, / Ẹṣin nbọ lọna, / ojo de, o tu agbo ijó, / o pa-òogùn mọ Eṣin l'ara, / oro-oògùn mu Ẹṣin, / o di wèrè, o nsare kiri kaakiri, / atijonaa ni oro oògùn naa tiimaamu / Ẹṣin tiimaa tu puu lojiji tiomaa / ntikaraarẹ sare kiri laisi eniti nle e. / Àgbe tiene la voz del juego, / Àlukò tiene la voz del veneno, / Ọ̀bàrà'Wọ̀nrin tiene voz de maṣoromaṣoro'", "Verso 112.2 (yorùbá): Kil'alemo-eyisi? / Ayo-lialemo-eyisi. / a dá f'Ọ̀rúnmìlà Alade / nbẹ laarin iponjú, / Wọ̀n ni: odún Ọrò de. / Eyẹlé, iyọ ati egbèwá owó li ebọ. / Ó gbọ̀ ó rú. / ¿Sabes tú qué es esto?. / Nosotros lo conocemos como alegría:", "REZO: OBARA JUANI OBARA NIFE JU JU OMO OLUWO ATOPOLO OBARA KELEYE OBARA NI WANI ALEYE OTORI LAYE O OSOBO. OÑI WANI ELEGBARA KUNHEYEKUN OBARA OÑI WANI KOTOKUN.", "REZO: ONIPAN OLLE ADIFAFUN OLOFIN EYELE LEBO AKUKO LEBO OTOMORO AWO AUOÑO.", "REZO: OBARA NIDE JUJU OMO OJUO ATOLOPO OBARA KEYOLE NI OBARA NI GUANI ALEYO OTORI LAYE OSODE ENI GUANI KABEYEKUN ELEGBA KABEYE KUN OBARA ENI GUANI LOTUTON ALEYO INTORI ARAYE EFA NILE ILEKUN INTORI LONI OBU FUN SHANGO OUNLO ALEYO ONIFUN OMO NIFUN OBARA NI GUANI JUJU OMOLUO AFOLOPO OBA OFUN OLO FUN LASHIREO AOFIFE OYU MOFA A OBARA NI GUANI."]}]$q$::jsonb),
(113,'68a8f5b24185560f7e06a2b96b024be8',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ọ̀kànràn habla de posibles desacuerdos y pleitos con amigos y socios, y da cómo controlarlos. La persona tiene conflictos en el trabajo o en sus relaciones. Con la ofrenda vence a sus enemigos 'como por arte de magia'. Con este signo se pone a prueba si un babaláwo de verdad sabe."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un pleito en el trabajo o en sus relaciones (relato del ave Iwo).", "Siente que no lo escuchan o teme que lo que diga cause rechazo.", "Quiere callar las críticas, pero no por la fuerza."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vencer a los enemigos.", "Ganar una guerra o un pleito tenso.", "Que el ofendido no pueda acusarlo ante el mundo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Caer mal a todos, como el pájaro carnívoro.", "Desacuerdos con amigos y socios."]}, {"titulo": "Enseñanza principal", "texto": "Lo frío vence: Ọ̀bàrà Ọ̀kànràn es más frío que el pasto con el rocío de la mañana, y con esa calma se gana la guerra."}, {"titulo": "Relatos reunidos", "puntos": ["El pájaro que cae mal. Le pidieron al pájaro Iwo, carnívoro, ẹ̀kọ de maíz, pimienta de guinea y 2,000 cauríes para no caerles mal a las demás aves del monte. Dijo que no ofrecería.", "La vara que calla. La vara que atraviesa a la rata no la deja hablar; la que atraviesa al pescado no lo deja hablar. Así, la persona a la que uno ofendió quiere reclamar y no puede, porque Ọ̀bàrà Ọ̀kànràn no se lo permite.", "Ọ̀rúnmìlà, las hojas de odán y la chiva. Ọ̀rúnmìlà estaba en medio de sus enemigos. Le pidieron una chiva y hojas de odán rociadas con ẹfun y osùn. Le dieron las hojas a la chiva, que comió algunas, y con el resto hicieron la ofrenda. Venció como por arte de magia. Con la piel de la chiva se hizo un tambor para tocar cada día.", "Bèmbé gana en Lìkì. Ifá consultó para Bèmbé, el tambor grave, que iba a la guerra en la tierra de Lìkì. Ofreció; la guerra fue muy dura, pero Bèmbé ganó, y cantaba: '¿Se ganó la guerra? Ọ̀bàrà kànhìn, la guerra se ganó'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El pájaro: ẹ̀kọ, pimienta de guinea y 2,000 cauríes.", "Contra los enemigos: una chiva y hojas de odán con ẹfun y osùn; con la piel, un tambor para tocar a diario.", "Contra la acusación: el amuleto de las varas de asar."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù recibe la ofrenda de la victoria. Bèmbé, el tambor, gana la guerra."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de odán, ẹfun (tiza), osùn. Amuleto: una vara de asar pescado y otra de asar rata, una kola amarga, hojas de ẹlẹmbẹrun e iyẹ̀-ìrosùn con el rezo, envueltos en algodón y atados con hilo blanco y negro; se lleva en el bolsillo y se reactiva soplando nueve pimientas de guinea masticadas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 113.1 (yorùbá): Ọ̀bàràkànràn: / li o difá fEyẹ-lwo. / Wọ̀n niki o wa rúbọ, / kiomale ṣ'ọ̀ràn ti àwọn ẹyẹ-oko / maa fi maa binusii. / Ẹbọ: Qkà (àgbàdo), / ataare ati ẹgbewà owó. / Ó gbọ̀ ó ni: / \"Òun ko maa rúbo\"", "Verso 113.2 (yorùbá): Ewé Ifá (kiwi imú èniyàn): Igi tiafisin eku, igi tiafisin ẹja, / kölawẹ kan ati ewé elẹmbẹrun. Kiakowon jọ sinu òwú gbẹrẹwu, / kiafi òwú düdú ati funfun di wọn po, Kiole danyindanyin. / Kiomaawa ninu apo-ẹwu. Ki a maa jẹ ataare mẹsàn fi wusa rè. / Ó nfẹwi-koleewi, / Obàràkànràn kojẹ. / Enitimoṣẹ. / Ó nfẹfo-koleefo, / Ọbàràkànràn kojẹ / ki o ro jọ mi fún ayégbọ / Igi-eku niiki'ran m'ekuninu, / Igi-eja niiki'ran m'ẹjaninu. / Ṣlẹmbẹrun kiwi ti ẹnú rẹ̀ f'ayé gbọ.", "REZO: OBARA KANA OLODAFUN ORUNLA OÑI PATE KI KODAPA ESHU IFA ELEGBARA LATOMI ATELE AWO ATI IWE ESE NITASI ADIFAFUN OBARA BINIROGUN UNBATI LA YELA IBENEKU OSUN ISHU, AWADO, AKUKO, ELEBO. IFA NI KAFEREFUN SHANGO ATI OYA.", "REZO: ONI MELEKU MAKU ONI MELELE ADIFAFUN TINLE ANA ESCHINLE ORUBO BIMOLAKU MAKU BIMELACU MALA ADIFAFUN SHANGO AÑALE AFIEDINE MELLE EGU META.", "REZO: OBARA UN KANA OYO MORE LE INLE ABIODUN OMINIFA SHANGO QUE KONDIFA WOWIFO OMO IÑA AWO OBARA KETE BOFUN ORINIBOSHE IYANSA ORI OPA OMO IFA GUANBEYE UNIOLOSHE LEGUA AWO ORISOÑI EWE ODUNDUN. ADIFAFUN EPO OWO IÑA OTA ORABAN IKU OWO TOEO OBARA OKAPAN ANALO UN OYA LODAFUN SHANGO.", "REZO: ONI MOLEKUN AWO MORDE ENI SHANGO MEYI ONI MOLELE ADIFAFUN TINLE ANO KOSHIDE IGBODUN IFA ERIN OKE LOPA BOGBO OMODE ONIFA KAFERE FUN SHANGO, OGUN, ELEGBA."]}]$q$::jsonb),
(114,'0b418eb8820c2c521ee80ef845d3ea97',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ògúndá habla de reparar una mala reputación para asegurar el éxito. Los negocios están atrasados y mejorarán con una acción espiritual. Ifá le desea el apoyo de su Orí: debe preguntar qué acepta su cabeza como ofrenda y dárselo. Antes de que lo manden a tratar con cierta gente, debe ofrendar para no meterse en problemas en el camino."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Los chismes le están afectando el trabajo o la relación con otros (relato de Olú-Iwo).", "Quiere recuperar su buen nombre después de un conflicto.", "Su casa o su negocio se quedó sin gente y quiere volver a llenarlo (relato de Ọlọ́fin Iwatuka).", "Necesita descanso y atender su cabeza (Orí)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Casa llena de gente.", "No caer nunca en descrédito; que los chismes no lo dañen.", "Que el Orí lo ayude y le traiga riqueza, pareja, hijos y casa.", "Escapar de una trampa en el camino."]}, {"titulo": "Ibi y advertencias", "puntos": ["Mala reputación.", "Muerte prematura.", "Ir a una fiesta sin ofrendar y caer en la red."]}, {"titulo": "Enseñanza principal", "texto": "El Orí de cada uno es el que lo ayuda: el de los caracoles ayuda a los caracoles, el de los peces a los peces. Quien ofrenda no cae en la red aunque vaya detrás de todos."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlófin Iwatuka y su casa llena. Le dijeron a Ọlófin Iwatuka que para tener su casa llena de gente ofreciera una paloma, 20,000 cauríes y medicina de Ifá. Después de la ofrenda, la persona debe cambiar de nombre.", "Olú-Iwo nunca caerá en descrédito. Le dijeron a Olú-Iwo, el señor de buena apariencia, que nunca tendría mala reputación, y que ofrendara para no morir joven: una carnera, una tortuga, 44,000 cauríes y medicina de Ifá. 'El ruido de las semillas de ifosi no daña a la hoja; el chisme del mundo no te dañará.'", "Olọ̀bàrà y su Orí. Olọ̀bàrà probaba de todo y nada le salía. Le dijeron que su Orí lo ayudaría y ofreció a su cabeza. Llegó la riqueza y exclamó: '¡El Orí de uno puede ayudar tanto!'. Cantaba: 'Que todo se acomode pronto para tener riqueza, esposa, hijos y casa'.", "Àrúwọ́n y la red. Los peces iban a celebrar el aniversario de Olókun y les pidieron ofrendar antes de salir. El pez respondió que él sabía deslizarse en el agua y no ofreció; lo siguieron el òkàsà, los caracoles y todos los animales del agua. Àrúwọ́n, el último, sí ofreció: una rama en forma de V que llevó colgada al cuello. Èṣù había enseñado a los hombres a tender una red en el arroyo, y todos los demás entraron en ella. Cuando llegó Àrúwọ́n, Èṣù le puso la rama en la entrada de la red; la rama le impidió el paso, miró y vio adentro a todos los peces atrapados. 'Mi cabeza no entra en la red; mi cabeza es como la de Àrúwọ́n.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọlófin: una paloma, 20,000 cauríes y medicina de Ifá; luego cambiar el nombre.", "Olú-Iwo: una carnera, una tortuga, 44,000 cauríes y medicina de Ifá.", "A Orí: lo que la cabeza acepte, un chivo grande o pescado.", "Antes de un encargo: una rama en forma de V al cuello durante la ofrenda, que luego se pone encima de toda la ofrenda."]}, {"titulo": "Relaciones espirituales", "texto": "Orí es el que da la riqueza. Olókun celebra su aniversario. Èṣù tiende la red y protege al que ofrenda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de olúṣesájú (Petiveria alliacea) machacadas con un hormiguero pequeño y jabón negro, con sangre de paloma, para lavar el cuerpo. Hojas de ifosi (Gouania longipetala), iru (Parkia biglobosa) y oriji cocinadas con carne de jicotea, para comer muy temprano. Rama en forma de V."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 114.1 (yorùbá): \"A wo iwájú ao r'ẹnikan, / a wo èhin ao r'ẹnikan\": / a daa fún Ọlófin Iwatuka. / Wọ̀n ni bi Ọlófin Iwatuka / ba nfẹ ki ilé oun jọ / (ki ọpọ èniyàn wa ni ilé rè) / kiowa ṣẹbą (ajolé). / Ó ni: \"kinni ẹbo?\" / Wọ̀n ni: / Eyẹlé, ẹgbàáwa owó ati ewé Ifá / Ki ẹniti a dá'Fá fún pa oruko / da bioba rúbọ. / A ko niiso fún un pe kiopa oruką / da bi ko ba rúbọ. / \"Miramos hacia delante y no vemos a nadie, / miramos hacia atrás y no vemos a nadie\":", "Verso 114.2 (yorùbá): Ilé Olú dára, / Odẹdẹ Olú sunwòn: / A dífá fún Olú-Iwo. / Wọ̀n ni: \"Olú-Iwo koniitẹ laelae\" / Wọ̀n niki o rúbo, / kiomatètè kú. / Ó ni: \"kili ebọ?\" / Wọ̀n niki o rú: / àgùtàn, ijapá, egbàá méjilélógún owó ati ewé Ifá. / Ó gbọ̀ ó rú. / Wọ̀n ṣe ewé Ifá fún un / Wọ̀n ni: / \"Ariwo ifosi kiipa elẹti, / ariwo ayé koniipa iwọ.\" / \"La casa de Olú es buena, / su patio también es bueno\":", "REZO: OBARA GUÑA SHANGO ABITI INTORI OYA INTORI OGU OFO NI OGUN INTORI OTI NI OBINI OFO INA LA OBA KAFEREFUN OSHUN, LODAFUN SHANGO OTI OYA.", "REZO: ORGULENA ELEGUEDE ADIFAFUN OLU ERI COGUO COMOBARU LODO ADAFUN ABAELLA EGUN UMBE ACICE LEBO AKUKO ELLA LEBO."]}]$q$::jsonb),
(115,'de159348f1da86c27ac45180acacf7bd',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ọ̀sá advierte sobre clientes o deudores que no pagan, estafas, robos o insolvencias que pueden dañar la economía. El malestar emocional lleva a la persona a cometer errores prácticos. Ifá le desea hijos en abundancia, y pide ofrendar a su padre y a Egúngún."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Dio mercancía o dinero a crédito y teme no recuperarlo (relato de Ẹta y el deudor).", "La angustia no le deja revisar con calma sus cuentas y acuerdos.", "Desea una familia numerosa (relato de Kànsièrè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que los deudores paguen con gusto.", "Muchos hijos.", "Vencer a los enemigos en medio de ellos.", "Que ni la muerte ni la enfermedad lo alcancen."]}, {"titulo": "Ibi y advertencias", "puntos": ["Un cliente que se lleva la mercancía a crédito y huye.", "Errores por el desorden emocional.", "Enemigos alrededor."]}, {"titulo": "Enseñanza principal", "texto": "El padre de uno es su egúngún en el cielo. Si está vivo, se le pregunta qué acepta su Orí y se le da; si murió, se le pide en silencio sobre un chivo y se le ofrece."}, {"titulo": "Relatos reunidos", "puntos": ["Ẹta y el cliente que quiere huir. Le avisaron a Ẹta, el retoño de las plantas, que uno de los que le compraban a crédito planeaba escaparse con su dinero. Ofreció una paloma, una gallina, 2,200 cauríes y medicina de Ifá para que sus clientes pagaran con gusto.", "El hijo de Ọ̀bàrà Ọ̀sá. 'Cuando el hechicero, la bruja, la muerte, la enfermedad y Èṣù me preguntan quién soy, respondo: soy hijo de Ọ̀bàrà Ọ̀sá. El hijo de Ọ̀bàrà Ọ̀sá no huye, no muere, no enferma, no cae en descrédito.'", "Kànsièrè, la gallina madre. Kànsièrè, la gallina madura, estaba triste porque no tenía hijos. Ofreció y empezó a tenerlos, y todos sus hijos la siguen a donde va.", "Ológbojò, padre de Egúngún. Ológbojò estaba en medio de sus enemigos y ofreció. Llegó al lugar del baile de los egúngún vestido de máscara y con un hacha pesada; los tambores bàtá tocaron un ritmo de guerra y le señalaron a su enemigo. Caminó con calma y le arrojó el hacha. 'Hoy Ọ̀bàrà no huye; mañana tampoco.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ẹta: una paloma, una gallina, 2,200 cauríes y medicina de Ifá.", "Para hijos: la ofrenda que marque Ifá.", "Al padre: si vive, lo que su Orí acepte (kola u orógbó); si murió, un chivo.", "Ológbojò: ofrenda a Èṣù antes de ir con los egúngún."]}, {"titulo": "Relaciones espirituales", "texto": "Egúngún y el padre difunto. Èṣù recibe las ofrendas de victoria ante el rey de los Òrìṣà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de ẹ̀ẹ̀sìn (Urera mannii o Mucuna pruriens) y tàgiri (Lagenaria breviflora) machacadas con jabón negro y sangre de gallina, para baño. Corteza seca de erùn con hojas de jásókè (Ehretia cymosa) y jabón negro, en una calabaza con tapa marcada con el signo, para baños."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 115.1 (yorùbá): Ọ̀bàrà-Ọ̀sá: / a dífá f'Ẹta. / Wọ̀n ni: / \"okan ninu àwọn ti o nra qjà. / Lowọ rẹ̀ nfẹẹ salọ kiolejẹ / owó rè gun nitorinaa kiowa rúbo. / Kiole maa ri àwon Qnibara rè, / ki owó le maa wuwọn on san fún un\": / Ẹyẹlé, agbebo-adiyẹ, ggbokànlá owó ati ewé Ifá. / Ó gbọ̀ ó rú. / Wọ̀n s'ewé Ifá fún un. / Wọ̀n ni: / \"ljọ ti èèsin ba sin owó rè niigbaa\"", "Verso 115.2 (yorùbá): Ewé Ifá: Lo eepo igi-ẹrùn gbigbẹ, gun ewé jásókè ati Ọ̀ṣẹ́ po. / Koosinu igbá adému dáradára kan, da ẹbu naa lee lori ki o tẹẹ ni / odù Ọ̀bàrà-Ọ̀sá, Kiosi kesi Ifá bayi. / Akiyesi: Gbe igbá-Ọ̀ṣẹ́ naa sinu apo aṣg fúnfún, kiofi kos'oke / Biobafẹ, kiomaa bu Ọ̀ṣẹ́ naa fiwẹ ara. / Oṣó ri mi, o ni: \"emi omọ tani?\" / \"Mo l'emi omo Ọ̀bàrà-Ọ̀sá\" / Àjé ri mi, o ni: \"emi omọ tani?\" / \"Mo l'emi omọ Ọ̀bàrà-Ọ̀sá\". / Àrùn ri mi, o ni: \"emi omo tani?\" / \"Mo l'emi omo Ọ̀bàrà-Ọ̀sá\". / Èṣú ri mi, o ni: \"emi omo tani?\" / \"Mo l'emi ọmg Ọ̀bàrà-Ọ̀sá\" / Ọmo Ọ̀bàrà-Ọ̀sá kiisa, / Ikú kiipa qmọ Ọ̀bàrà-Ọ̀sá, / Àrùn kiigbe ọmọ Ọ̀bàrà-Ọ̀sá de, / Ọmọ Ọ̀bàrà-Ọ̀sá kiitẹ.", "REZO: OBARA SA KUKUTO KUKU ADIFAYOKO KUNLE ADIFAYOKO KOMI NIBOGUELE ARORO LOURE SIKOTA AIKORDIE, EYELE MEYI INTORI IKU OTULEBO.", "REZO: KUKUQUEQUE ADIFALLOCO CONLE ADIFALLOCO NI NIBO GUELE A RORO LOURO SICOTA AIKORDIE EYELE MEDILOGUN ETU EYELE ELEBO.", "REZO: COFERU OLOFIN AWOFI ADIFAFUN ORUNLA UMBATIMLEMBA ERILOGUO BICU EYELE LE ATANA MEDILOGUN EYELE MEDILOGUN ETU EYELE ELEBO.", "REZO: OBARA SA KAFEREFUN OLOFUN AMOFI ADIFAFUN ORUNLA UMBATI LEMPA ORI LOMO BIKU EYELE IFANI, KAFEREFUN ELEGBA.", "REZO: ADIFAFUN AGAYU SHOLA SHOLA KINIBA KINIBANARO OKUO E WINIKI SOKU IYA LORO TI BAKO MANA MANA OLODUMARE UKAWO KABIE AYURO OTA ASHORO EWO AYA ITORO KOLUYO SHANGO INLE NI OKENLA AINA OROIÑA IYAMASE UNSORO SORO NI ELEGBA ONIBODE INLE AINA BEDE BEDE NI AGGAYU OMORISHA ALABA NI ADE ORISHA OSHON ATINI SHANGO KAFEREFUN SHANGO LODAFUN ORUNLA."]}]$q$::jsonb),
(116,'0204b6776a7f3be78d0eb254f473dd79',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ìká habla de conservar el poder y la influencia. Las dificultades pasajeras se apartan con una experiencia emocional o espiritual nueva. Ifá le desea riqueza, paz y el amor de mucha gente, pero le pide no caer en excesos, no romper los tabúes y escuchar los consejos, sobre todo los de su pareja. Debe cuidar a su esposa y ofrendar a su Orí."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder propiedades, posición o apoyo (relato de Olubolaji).", "Pasa por dificultades temporales y busca algo que le ayude a cambiar.", "Se siente rodeado de oposición (verso de Ọ̀rúnmìlà).", "Puede estar exagerando en su búsqueda de bienestar (relato del cazador)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ser una persona importante y querida por muchos.", "Vencer a los enemigos que lo rodean.", "Riqueza al lado de donde está.", "Riqueza duradera si atiende a su pareja."]}, {"titulo": "Ibi y advertencias", "puntos": ["Los excesos.", "Romper un tabú y perderlo todo.", "Cuidar más a un animal o una cosa que a su pareja.", "Perder propiedades o poder."]}, {"titulo": "Enseñanza principal", "texto": "En todo lo que hagamos no debemos excedernos. El cazador lo tuvo todo en la ciudad de las mujeres, pero entró al cuarto prohibido y amaneció desnudo en el basurero donde empezó."}, {"titulo": "Relatos reunidos", "puntos": ["Olubọlaji, querido por todos. Le dijeron a Olubọlaji que sería una persona importante y querida, y que ofrendara para no perder sus bienes y su poder: una paloma, una gallina, una tortuga y 3,200 cauríes. Ofreció y cantaba: 'Estoy feliz, Ọ̀bàrà Ìká; bailamos y nos alegramos'.", "Ọ̀rúnmìlà rodeado de enemigos. Kowee, el adivino de la tierra, y Ogbigbi, el adivino del cielo, hicieron un rezo para Ọ̀rúnmìlà cuando lo rodeaban sus enemigos: cuando llora uno se van los mayores al cielo; cuando llora el otro llegan niños a la tierra. Le aseguraron que vencería, que las hojas de ẹwọ arrastrarían a sus enemigos y que Ọ̀bàrà Ìká los tendría bajo control.", "El cazador y la ciudad de las mujeres. Un cazador buscó durante tres años un caimán para hacerse rico, y le dijeron que la riqueza estaba junto a él. Al tercer año, recogiendo basura, encontró un caimán que le pidió no matarlo. Le preguntó qué buscaba, y el cazador dijo que hacerse rico. El caimán le pidió quitarse el pantalón, la camisa y el gorro, y jalar una soga. Al jalarla apareció en una ciudad llena de mujeres, sin un solo hombre. Lo recibieron, tuvo muchos hijos con ellas, le dieron una casa como palacio con tres cuartos y le dijeron que podía entrar a los dos primeros, pero nunca al tercero. Vivía como rey. Un día se preguntó por qué unas mujeres iban a prohibirle algo, y entró al tercer cuarto: cayó de golpe en el mismo basurero donde se había quitado la ropa.", "Oládùbádà, el caballo y la esposa. Oládùbádà tenía una esposa en casa y un caballo en el establo, y cuidaba al caballo pero no a la mujer; ofrendaba al Orí del animal y dejaba el de su esposa. Le dijeron: 'Deja el Orí del animal y ofrenda al Orí de tu esposa, para que tu riqueza te dure toda la vida'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Olubọlaji: una paloma, una gallina, una tortuga y 3,200 cauríes.", "Para la riqueza: una paloma madura.", "Al Orí de la esposa: pollo, huevos, carne de cerdo y hojas de malanga."]}, {"titulo": "Relaciones espirituales", "texto": "Orí de la pareja recibe ofrenda. Ọ̀bàrà Ìká controla a los enemigos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de ẹwọ (Smilax kraussiana) arrancadas con los dientes, un ẹẹru caído y un caracol, quemados y hechos polvo en una calabaza; se riega en el piso limpio, se marca el signo con el rezo, se lame de rodillas y se gotea aceite de palma alrededor, una vez al mes. Hojas de malanga."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 116.1 (yorùbá): Ọ̀bàrà-Ká: / a difá fún Olubolaji, / wọ̀n ni: / \"Esè rè agbilẹ, / a l'ẹniyan ka ibigbogbo\". / Wọ̀n niki o wa rúbọ / kio ma baa s'ofo pupo. / Ẹbọ: Ẹyẹlé, adiyẹ, ijapá / ati ẹgbẹrindílógún owó. / Ó gbọ̀ ó rú. / Ó ṣẹbọ tan a nkọrin: / Mo ka'le mo ka'ko Ọ̀bàràká. / Mo r'ojú mo r'ayé Obàràká. / A njó a nyọ̀", "Verso 116.2 (yorùbá): Kowee awo ayé, / Ogbigbi awo Isalu orun, / Bi Kowee-awo-ayé ba ke; / àwọ̀n àgbàgbà ayé / a maa gb'ode orun lọ. / Bi Ogbigbi awo Isalu orun ba ke; / àwọn omowewẹ orun / amaa bowa si ayé. / Esẹ̀ Ọba a ka'yé / esè Ọba ajaká. / Wọ̀n sa'gèdè fún Ọ̀rúnmìlà, / ọ̀tá rọgba yii ká. / Wọ̀n ni: / \"iwo a ṣégun odi, / iwọ a r'ẹ̀hin ptá\" / Ewé ẹwọ ni yoo maa wọ àwọn ọ̀tá rẹ̀ / gb'ode ọ̀run lọ. / Eeru niyoo maa ru ibi to wọn lọ. / Ọ̀bàrà-Ká / ki o bami káwọ àwọn ọ̀tá mi.", "REZO: OBARA KASIKU LEGUN OMODO OLOFIN IKA LELE ARAMANAMANA AKA TANPO ADIFAFUN OLEYE ADIFAFUN ESHIYE OMO OLOFIN AGBORAN LIMELE AKATI ASHOTELUWA OLOFIN, SHANGO UNBO WA BELEFUN ADDE OLOFIN LODAFUN AGUNGUN ORUN NI MALE.", "REZO: OSIKABARA ORUNLA ADIFAYOKO KANFUN ELLUERE EKU EBBO CORUELLA EBO CORUELLUORO AIKORDIE AGERE.", "REZO: OBARANLA AGUA ORU ORE OBA OFELLU ENICAN INA LAGUE OMO OBARA ENIMBALE AGUETI ITA BABA AGUELA ORE MABAO ETU LEBO AKUKO EKU LEBO."]}]$q$::jsonb),
(117,'b8ee74ca71d6539e1f497064db3b543c',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Òtúrúpọ̀n da soluciones para la infertilidad y los abortos; aconseja ofrendar a los Òrìṣà para lograr el embarazo. Si sale para una mujer, un hombre rico no es su esposo destinado: ella misma será rica y debe ser respetuosa con su pareja. Ifá protege de una enfermedad repentina que desfigura."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una pareja desea hijos y busca orientación (relato de Aroko y su esposa).", "Hay preocupación por un embarazo o por pérdidas anteriores.", "Una relación de pareja es difícil de llevar."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Muchos hijos cargados en la espalda.", "Una mujer fértil y sin pérdidas.", "Riqueza y vida larga para la mujer que respeta a su pareja.", "Conservar la belleza hasta la vejez."]}, {"titulo": "Ibi y advertencias", "puntos": ["Abortos y pérdidas de embarazo.", "Casarse por dinero.", "Una enfermedad que cambia la apariencia."]}, {"titulo": "Enseñanza principal", "texto": "El pájaro agbe era blanco y hermoso; despreció la ofrenda y una enfermedad le cambió el color. 'Ifá, déjanos ser hermosos hasta viejos.'"}, {"titulo": "Relatos reunidos", "puntos": ["Aroko y su esposa. Ọladipupo consultó para Aroko, el quimbombó, que lloraba porque su esposa no tenía hijos. Le aseguraron que ella cargaría muchos hijos en la espalda si ofrecía una chiva y 16,000 cauríes.", "Ọlófin y la mujer que perdía embarazos. Ọmọ-Maara consultó para Ọlófin cuando iba a tomar a una mujer que perdía sus embarazos. Ofreció una tortuga, una carnera y 16,000 cauríes, y le aseguraron que la mujer sería fértil y ganaría con ella sin arrepentirse.", "Ọ̀bàrà Òtòkú compra a su esposo. Ọ̀bàrà Òtòkú no encontraba hombre que la quisiera. Le dijeron que sería rica, pero que debía ser respetuosa con su pareja y 'comprarse' un esposo para no perder el camino. Ella pagó lo que hizo falta, escogió a Èdú, es decir a Ọ̀rúnmìlà, como esposo, tuvo vida larga, hijos y riqueza.", "El pájaro agbe. El agbe era blanco como la nieve. Le pidieron ofrendar para que una enfermedad no le cambiara la apariencia, y respondió con desdén. Un día la enfermedad lo atacó, probó todos los remedios y no se curó; todo su cuerpo cambió de color. Ahora es negro."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Aroko: una chiva y 16,000 cauríes.", "Ọlófin: una tortuga, una carnera y 16,000 cauríes.", "Contra la enfermedad que desfigura: un paquete de tela blanca y otro de tela negra."]}, {"titulo": "Relaciones espirituales", "texto": "Los Òrìṣà reciben la ofrenda para el embarazo. Ọ̀rúnmìlà (Èdú) es el esposo destinado."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Quimbombó, chiva, tortuga, carnera, tela blanca y negra. Ante pérdidas de embarazo o cambios en la piel, se debe consultar también al médico."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 117.1 (yorùbá): Ọladipupo: / a dífá fún Aroko (ilá), / Aroko nsẹkún / àiromogbepon ti aya rẹ̀, / Wọ̀n ni: / \"biobarúbo a r'omggbepon\". / Ebọ: Ewúrẹ ati Ẹgbàájo owó. / Ó gbọ̀ ó rú.", "Verso 117.2 (yorùbá): Ọmọ-Maara: / a difá fún Ọlófin. / Wọ̀n ni: / Obirin kan ti o nwu Ọlọ̀tin / lati ra (l'ẹrú) yi, / obirin na a rẹ (Bimg) pupo, / sùgbọ̀n ki Ọlófin wa rubọ / nitoripe ki àwọn omo obirin / naa mamaakú / ki Ọlọ̀fin baa leri ere pupp / jẹ laisi ibanujẹ. / Ebọ: ljapá, àgùtàn / ati egbàájo owó. / Ó gbọ̀ ó rú.", "REZO: OBARA TUMBUN ÑEDE ÑEDE ADIFAFUN BABA LONTOBI OMA ARETO YU EBBO OMA SUNEKE NANGA. OBARA TUNBUN ÑADE ADIFAFUN BABA LONTORI ERA TEYU EBBO ASONI NANAGA EYELE LEBO PUENO ADIE, AKUKO LEBO.", "REZO: OBARA TUMBAN ÑADE ADIFAFUN BABA LONTORI ONA ORATELLU EBBO ESENE QUE ÑAGA EYELE LEBO ALLI PUEBO ADIE O AKUKO LEBO.", "SUYERE PARA DARLE DE COMER AYA A OZAIN: AYA TOLO BI AYA NI AYA TOLOBUN UNYEN AYA MORABI AYA TOLO.", "SUYERE PARA HACER BRUJERIA CON EL PERRO: OBANIRE OGU OBANIDE BALELOGUN AYALA AYA GUA ERERE OBA NI OGU.", "SUYERE A ELEGBA EN ESTE IFA: EYELIRE UNKO YANKARO EYELIRE UNKO YANKARO ELEGBA TANDE YANKARO IBORI TANDE KOIMA MI SHAKURUMA ELEGBA TANDE SHAKURUMA ELEGBA TANDE.", "REZO: OBARA TUMBON ÑADE NADE, ADIFANFUN BABA LONTORI ENA OSATUYU EBBO ENSENEKE ÑAGA EYELE LEBO, EYA DURNO ADIE AKUKO LEBO.", "REZO: OBARA TUMU ELEGBA NARA ÑARA BI ISHI AYA PARAYE AYA OBA OBARA TUMU OBARA NI BATUTO IFA ORUNLA ELERIPINI AÑAÑANA LORUN WAWA OBA ELEGBA LAROYE OBARA NI KIKIÑO LAYE MOÑAÑA OBARA TUMU OBA OGU AYA AÑI OFO ESHISHI ELEGBA INTORI ODE BEYE BEYE LERI AJUA URO ALAGBEDE OGUN MOFA ELEGBA MOFARE OGUN ONIRE OBARA TUMU OYA INTORI ARAN ELEGBA AYA YOGUN."]}]$q$::jsonb),
(118,'8f0b22998a9139224a3a01dc71e53435',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Òtúrá pide cuidar el respeto dentro de la casa para resolver los problemas, y cuidar las inversiones y los negocios. La relación de pareja está trayendo inquietud. Sus cosas no se echarán a perder: se queja de no avanzar, y el avance llegará cuando Ifá lo quiera."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La relación de pareja trae tensión a la casa (relato del rey que no escuchó el consejo).", "Teme que alguien cercano lo perjudique o que el chisme afecte su trabajo (relato de la gallina y el halcón).", "Busca prosperar después de probar varios caminos (relato de Gése)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ser respetado; que el enemigo fuerte no pueda herirlo.", "Avance, riqueza, pareja e hijos.", "Que le 'desaten' las buenas fortunas."]}, {"titulo": "Ibi y advertencias", "puntos": ["Meter en casa a alguien desordenado que todo lo trastorna.", "Un enemigo poderoso que se acerca.", "Huir de la casa y que el enemigo lo persiga."]}, {"titulo": "Enseñanza principal", "texto": "El halcón no puede herir al caracol; solo puede mirarlo. Quien ofrenda es respetado aunque sea pequeño."}, {"titulo": "Relatos reunidos", "puntos": ["El rey de Ọ̀yọ́ y la mujer desordenada. Kékeré consultó para el rey de Ọ̀yọ́, que quería tomar a una mujer, y le advirtió que no lo hiciera porque era desordenada y le trastornaría la casa. Le pidió ocho caracoles, una cazuela de ñame asado machacado, cuatro palomas, 16,000 cauríes y medicina de Ifá. No ofreció.", "La gallina y el halcón. A la gallina y a sus hijos les dijeron que se acercaba un enemigo poderoso; si dejaban su casa en la granja, los perseguiría, pero con la ofrenda triunfarían. Algunas ofrecieron un caracol, 3,200 cauríes y medicina de Ifá. 'El halcón no puede herir al caracol; solo puede mirarlo. Serás respetado.'", "Gése logra su avance. Gése probaba de todo sin avanzar. Ofreció una paloma madura y todo lo demás, y quedó rodeado de cosas buenas. 'Los retoños del ñame en la granja lograrán lo suyo.'", "Itú y las fortunas desatadas. Itú preguntó si tendría esposas e hijos. Ofreció un chivo con barba y le dijeron que su vida no sería miserable y que le desatarían las fortunas. Empezó a tener esposas e hijos. 'Desaten nuestras fortunas, para todos.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El rey: ocho caracoles, una cazuela de ñame asado machacado, cuatro palomas, 16,000 cauríes y medicina de Ifá.", "La gallina: un caracol, 3,200 cauríes y medicina de Ifá.", "Gése: una paloma madura.", "Itú: un chivo con barba; ofrenda por la pareja."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù recibe los regalos de la ofrenda. Ifá desata las fortunas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de ọwọ (Brillantaisia) molidas en sopa con caracol, para beber. Ñame asado, chivo con barba, paloma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 118.1 (yorùbá): Kékeré awo Ọlọ̀yọ̀: / a difá fún Ọba Ọlọ̀yọ̀, / nfẹẹ ra obirin tiowuu l'erú. / Wọ̀n niki Ọba Ọloyó ma raa, / tu'le tu'le nii. / Ó ni: / \"kil'ebo bi òun ba raa kioma le tư'le?\" / Ẹbọ: İgbin méjo, igbá ewo, / eyẹlé mẹrin, egbàá mẹjo owó ati ewé Ifá. / Ó gbọ̀ ko rúbọ.", "Verso 118.2 (yorùbá): Apapatiako, / Atuwon-niletuwon-loko: / a difá fún Onilé-Adiyẹ ati àwọ̀n omọ rẹ̀, / wọ̀n ni: / \"ọ̀tá ti o lagbára ju wọn nbọwa bawon\". / \"Biẹbasa kuro ni'le los'oko / iyoo tun wa ba yin l'oko; / ṣügbọ̀n biẹba ṣebo eo ye, / owọ a jẹ fún yin\" / Ẹbọ: İgbín, ẹgbẹrindilógún owó ati ewé Ifá. / Onilé-adiyẹ diẹ rúbọ. / Wọ̀n ni: / \"Awodi koleri f'igbín ṣe: / Awodi wo igbin kọrọ\".", "REZO: OBARA KUSHIYO AKE EURE AHOBONI BO URO GULANDA BARABANIRO OGUN ORUNLA LORUGBO, ESHU ELEBO OUNKO, AIKORDIE, EYELE,AKUKO, OMI ELEBO, OWO ELEBO.", "REZO: AQUE AURE CHIBENI BAURONGUNLEDA BARABANIREGUN ORUNLA ERUBO. ESHU ELEBO AIKORDIE EYELE BIRUTA OMI EBELLO OWO. TIREFUN ABAÑO ADIFAFUN TONI BUEGUE OMA APITA LEBO MELON DE CASTILLA TOMAGU EKU EYELE LEBO."]}]$q$::jsonb),
(119,'3fd3168b2d4dff45a99fb6d7dfaf1322',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ìrẹtẹ̀ habla de éxito y estabilidad con las ofrendas indicadas. Hay buenas perspectivas para un trabajo o negocio nuevo. Las bendiciones que se perdieron están regresando. Ifá pide ser generoso con todos los que encuentre y no ser tacaño; le desea la fortuna de reunir gente a su alrededor. Si busca hijos, no debe mirarse en espejos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa en un empleo o negocio nuevo.", "Busca estabilidad después de un avance reciente (relato de Akintẹlu y la villa que fundó).", "Puede venir buena fortuna si evita grandes problemas (versos de Ọ̀rúnmìlà).", "Busca pareja."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Bendiciones que regresan.", "Estar siempre en la cima, sin obstáculos.", "Que el pueblo que fundó no decaiga.", "Ser rey y tener buena pareja por su generosidad.", "Hijos."]}, {"titulo": "Ibi y advertencias", "puntos": ["La tacañería.", "Una mujer que busca hijos y se mira al espejo."]}, {"titulo": "Enseñanza principal", "texto": "El que da de comer y beber al que pasa por el camino termina con un pueblo a su alrededor. Y el espejo, por grande que sea, no muestra lo que viene el año siguiente: el hijo es el espejo de uno."}, {"titulo": "Relatos reunidos", "puntos": ["Las bendiciones de Ọ̀rúnmìlà regresan. 'Ọ̀bàrà Ìrẹtẹ̀, las bendiciones vienen a mis manos': le dijeron a Àgbọnnìrègún que la fortuna reservada para él venía de regreso. Ofreció una paloma, un caracol y medicina de Ifá.", "Ọ̀rúnmìlà siempre en la cima. Ọ̀rúnmìlà ofreció un caracol, tela blanca, 3,200 cauríes y medicina de Ifá para que ninguna dificultad se le presentara y estuviera siempre arriba. Se inició solo en Ifá, y siempre iniciará a todos los estudiantes de Ifá.", "Akintẹlu y su villa. Akintẹlu ofreció ocho caracoles, una carnera, 16,000 cauríes y medicina de Ifá para que la villa que fundó no decayera.", "Olọ̀bàrà alimenta a los viajeros. Olọ̀bàrà iba a cultivar a la orilla del camino y preguntó si tendría una buena esposa. Le dijeron que no fuera tacaño. Empezó a dejar comida y bebida en el camino para todos los que pasaban con hambre. Los viajeros dijeron: 'Por aquí pasamos siempre; hagamos aquí un pueblo'. Fundaron el pueblo, hicieron rey a Olọ̀bàrà, y un rey no puede quedarse sin esposa: le dieron una.", "Adéyokùn y el espejo. Adéyokùn lloraba por hijos. Le pidieron ofrecer un espejo grande. Lo hizo, y nueve meses después llegaron los hijos. 'Ningún espejo, por grande que sea, muestra lo que viene el año siguiente; el hijo es el espejo de uno.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: una paloma, un caracol y medicina de Ifá; o un caracol, tela blanca, 3,200 cauríes y medicina de Ifá.", "Akintẹlu: ocho caracoles, una carnera, 16,000 cauríes y medicina de Ifá.", "Para hijos: un espejo grande; ofrenda a Ọ̀ṣun."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà se inició solo y es el que inicia. Ọ̀ṣun recibe ofrendas constantes de este signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Caracoles, tela blanca, carnera, espejo grande. Comida y bebida para los que pasan."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 119.1 (yorùbá): Ọ̀bàrà-Rẹtẹ̀, / Ire tẹ mi lọwọ: / a difá fún Àgbọnnìrègún. / Wọ̀n ni: / \"Ire mbowa baa\" / Wọ̀n niki o rúbọ: / eyẹlé, igbin ati ewé Ifá. / Ó gbọ̀ ó rú.", "Verso 119.2 (yorùbá): Ọ̀bàrà-Retẹ̀: / a dífá fún Ọ̀rúnmìlà. / Wọ̀n niki o rúbọ / ki ohun ti o wuwoju ma le de sii. / Pe oun niki o le maa tẹ (ori) / ohungbogbo ati ara rẹ. / Ẹbọ: İgbín, aṣo funfun, egberindílógún owó ati ewé Ifá. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Ohun ti o wuwoju kiide si Ọ̀rúnmìlà\". / Ọ̀rúnmìlà liotẹ ara rè n'Ifá, / òun ni yoo maa tẹ wọ̀n nibigbogbo\".", "Verso 119.3 (yorùbá): Ọ̀bàrà-Rẹte: / a dífá fún Akintẹlu. / Wọ̀n ni ilú tiotẹ (do) yi kiowa rúbọ / ki ilú naa le jọ sii lowọ. / Ebọ: Igbín méjo, àgùtàn, / egbàájo owó ati ewé Ifá. / Ó gbọ̀ ó rú.", "REZO: OBARA RETE IFA OÑI RETEWA ADIFAFUN ASHIWITA INTORI AWO SHUBU LORI OKUNI SINI OLOKUN.", "REZO: ADIFAFUN OMA OLOKUN UMBATI UNLO INLE ORUNLA OFIVA LA TRUPAN OLO INLE EBARA OFICA LOTRUPON EGUN INEA OBE YEMAYA. OBARA RETE ADIFAFUN ODE EOLO LLUPA EYELE OWO MENI MAFEREFUN YALORDE Y OBATALA.", "SUYERE PARA LA LLUVIA: ONI ONI LAYERE OLORUN OWO MOWA KUN ONI LAYERE OBANIYEGUN.", "REZO: IROKO NAYEBI ALABA NUYE SEDA ABODA ALABAMBA."]}]$q$::jsonb),
(120,'0d0bf030cde6c21801750febe636dc1a',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Ọ̀ṣẹ́ habla de los caminos para controlar las fuerzas de la naturaleza. La persona necesita limpiarse de toda energía negativa. Ifá le da la fortuna de una buena pareja; a los padres les pide no enojarse por el esposo que elija la hija, sino dejarla escoger. Puede tener bienes valiosos, y debe cuidar a quien manda a comprar por él."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Carga un peso familiar o emocional que quiere aliviar.", "Quiere proteger una actividad o algo valioso (relato de Ọ̀rúnmìlà y la prenda bajo la lluvia).", "Hay un asunto de relación o de matrimonio."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que el hijo de Ọ̀bàrà Ọ̀ṣẹ́ no sufra sin necesidad.", "Detener la lluvia cuando hace falta.", "Una buena esposa.", "Riqueza y bienes valiosos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Energías negativas encima.", "Padres que imponen esposo a la hija y luego son motivo de burla.", "Comprar algo o a alguien que termina comiéndose lo de uno."]}, {"titulo": "Enseñanza principal", "texto": "La cucaracha rica no escuchó, compró a la gallina como esclava y la gallina se la comió. Quien tiene riqueza debe ofrendarla y ser paciente antes de comprar."}, {"titulo": "Relatos reunidos", "puntos": ["El hijo que no sufre. '¿Cómo está mi padre? Muerto. ¿Y mi madre? En la tumba, hablando fuerte. ¿De quién soy hijo? De Ọ̀bàrà Ọ̀ṣẹ́, que echó a un lado las reglas. Me golpearon por todas partes, pero el hijo de Ọ̀bàrà Ọ̀ṣẹ́ no sufre.' Es un rezo para alejar a los enemigos.", "La lluvia que no moja. 'Si pido lluvia, llueve; si pido que pare, para.' Le aseguraron a Ọ̀rúnmìlà que la lluvia nunca mojaría su vestido precioso. Cantaba: 'No dejes que llueva, Ọ̀bàrà Ọ̀ṣẹ́'.", "La hija de Onídòko. Ọ̀pẹ́ẹ̀rẹ́, el sacerdote de la casa de Onídòko, les dijo que su hija ya estaba en edad de casarse y debía hacerlo con un babaláwo, y les pidió ofrendar. No ofrecieron. Ọ̀bàrà Ọ̀ṣẹ́ llegó a trabajar a esa casa y se interesó en la muchacha, pero cuando llegó el momento de irse con él, el padre y la madre cambiaron su palabra. Por eso el pájaro ọ̀pẹ́ẹ̀rẹ́ sigue cantando hasta hoy: 'La hija de Onídòko no vale nada; ya no la queremos'.", "La cucaracha y la gallina. La cucaracha se hizo rica y quería comprar un esclavo. Le pidieron ofrecer la tela de su riqueza y esperar. Con desdén dijo que los esclavos andaban por todas partes pidiendo ser comprados. Salió, vio a la gallina, le gustó y la compró. La gallina se quedó mirando la riqueza de la cucaracha, y Èṣù le dijo: '¿No ves que no ofrendó? ¡Cómetela!'. Hasta hoy, si se ponen granos de maíz junto a una cucaracha, la gallina se come primero a la cucaracha."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra los enemigos: polvo de hojas de ẹjá y de àrèrè caídas del árbol, dentro de un caracol marcado con el signo, envuelto en tela negra e hilo negro, lanzado con los ojos cerrados dentro del bosque.", "Para detener la lluvia: el signo marcado en iyẹ̀-ìrosùn sobre tierra seca, recogido en tela blanca y colgado en lo alto de un árbol.", "Para la riqueza: una tela brillante."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù castiga a la cucaracha que no ofrendó. Ọ̀rúnmìlà controla la lluvia con el signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de ẹjá (Mallotus oppositifolius), hojas de àrèrè (Annona senegalensis), caracol, tela negra e hilo negro, tela blanca, iyẹ̀-ìrosùn."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 120.1 (yorùbá): Wọ̀n ni: babami nkọ? / Mo ni: baba mi kú o. / Wọn ni: iyá mi nkọ? / Mo ni: iyá mi nbẹ l'aja ilè o nfọ rererere. / Wọ̀n ni: emi omọ tani? / Mo ni: emi qmọ Ọ̀bàrà-Ọ̀ṣẹ́ tiip'Ọlọ̀jà. / Gbogbo wọ̀n ngba mi loju ipoki-ipoki; / wọ̀n nkanmi ni'kun / igbọ̀ngbọ̀n-igbóngbón. / Wọ̀n nṣe mi ṣibaṣire / bi ewúrẹ ilé mu ohun baale ilé jẹ. / lya kiijẹ qmọ Ọ̀bàrà-Ọ̀ṣẹ́. / Ọ̀bàrà-Ọ̀ṣẹ́ mama jẹki ọmọ awo jiya. / Ewé ẹja maṣaiba mija (àwọn ọ̀tá mi) / wọn r'orun, / Iya kiijẹ omọ Ọ̀bàrà-Ọ̀ṣẹ́, / Ọ̀bàrà-Ọ̀ṣẹ́ mama jẹki omo awo jiya.", "Verso 120.2 (yorùbá): Aisirẹ f'agbón isalẹ palẹ, / Biobawipe ki eji ṣu Eji a ṣu. / Biobawipe ki eji fo, Eji a fo: / Wọ̀n sa'gèdèfún Ọ̀rúnmìlà, / wọ̀n ni: / \"ojo ko maa pa Erinwo Oṣin / kiofun aṣo\" / \"Aṣo ti mo muwa s'ode yi\" / \"Ọ̀bàrà-Ọ̀ṣẹ́ ma jẹki ojo paa\". / Orin: / Mama j'eji rọ o, / Mama j'eji rọ. / Ọ̀bàrà-Ọ̀ṣẹ́ o mama j'eji rọ o.", "REZO: OBARA SHE OFUYERE OBARA SHEKE MI SHEKE ODIKARA KORUBO OGU SHE AWO OBARA OBASHE AWO EYELE AWO EYELE AWO AUN AWO KAFEREFUN OBA KAFEREFUN ODUN, KAFEREFUN ORUNLA.", "REZO: OFUYURE ONARA SHEKA NISHERE ODILERA KORUBO PGUNSHE AWO OBARA OBASHE. AWO EYELE AWO AUN AWO KAFEREFUN OBA KAFEREFUN ODDUN KAFEREFUN ORUNLA.", "REZO: OFULLELRE EBARA CHEGUE NICHEGUE ORDILERE CORUBO.", "REZO: ONILE ALAFILA OBARA SHE FUN KUAKUA SHANGO OMO OBATALA ONI SHANGO BA OSO ONILE, ONILE ALAFIA, ONILE ALAFIA (ES EL NOMBRE DE ABASHE, ES EL MISMO SHANGO HIJO DE OBATALA QUE CUANDO SE ENFURECE TIEMBLA LA TIERRA)."]}]$q$::jsonb),
(121,'ad2bcf72e70a74e3a66919affa3dc8c2',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Òfún habla de grandes éxitos económicos. Es buen momento para un trabajo nuevo, una inversión o una empresa. Ifá advierte al babaláwo que la persona o el grupo que consulta puede meterlo en un problema serio, y pide ofrendar mucho àmàlà. La persona no debe creer que su conocimiento vale más que la ofrenda."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa empezar un trabajo o una empresa.", "Busca recursos después de muchos problemas (relato de Bara Àgbọnnìrègún).", "Puede llegarle una oportunidad de lejos (relato de Tẹwogbolá).", "Puede estar desatendiendo a la gente que lo rodea."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Mucho dinero: nadie cuenta los granos de maíz del suelo.", "Visitantes del extranjero que traen dinero.", "Un pájaro que trae fortuna de lejos.", "Hijos que viven; un hijo que se levanta."]}, {"titulo": "Ibi y advertencias", "puntos": ["Creer que el conocimiento basta y no ofrendar.", "Hacer justo lo que Ifá prohibió.", "Culpar al babaláwo de lo que uno mismo causó."]}, {"titulo": "Enseñanza principal", "texto": "El conocimiento no está por encima de la ofrenda. Ọlófin hizo ñame machacado cuando Ifá lo había prohibido, y su hijo se desmayó; solo Ọ̀rúnmìlà, que llegó al final, pudo levantarlo."}, {"titulo": "Relatos reunidos", "puntos": ["Mucho dinero en este lugar. Aralemikaka consultó para Bara Àgbọnnìrègún. Canto: 'Hay mucho dinero en este lugar; nadie contará nunca los granos de maíz en el suelo'.", "Visitantes que traen dinero. 'Ifá arrastra a todos hacia mí con su dinero; los visitantes extranjeros me buscan.' Ọ̀rúnmìlà ofreció tela blanca, una paloma blanca, una gallina blanca y 4,400 cauríes para ver cosas buenas todos los días de su vida.", "Tẹwogbọlá. 'El dinero me rodea, las esposas me rodean.' A Tẹwogbọlá le dijeron que un pájaro le traía fortuna desde tierra lejana. Ofreció cuatro palomas, una gallina y 16,000 cauríes.", "Ọlófin y el ñame machacado. Ọlófin dirigía su vida con su conocimiento y no le iba bien; decía que el conocimiento era mejor que la ofrenda, y tenía a su lado a adivinos de agua, de kola y de arena, que siempre se contradecían. Un día su hijo se enfermó por algo que comió. Los babaláwo pidieron un chivo y mucha comida, y advirtieron con firmeza: 'No preparen ñame machacado'. En cuanto salieron, mataron la chiva y prepararon ñame machacado; al sacar el mazo del mortero, el niño se desmayó. Ọlófin, furioso, mandó al verdugo Tèètú contra los babaláwo. Èṣù les avisó, y les dijo que Ifá pedía mucho àmàlà en lugar de ñame. Los babaláwo llegaron cantando, señalaron al niño con el báculo de osùn y rezaron: 'El día que la cabra pare, el cabrito se levanta; que este niño se levante'. El ñame machacado se partió en dos y el niño se puso de pie. Ọlófin, que quería matarlos, les tendió una alfombra roja y los invitó a comer, pero ellos respondieron: 'Solo alguien sin conciencia comería el ñame machacado de Ọ̀bàrà Òfún. ¿No fuiste tú quien lo preparó?'.", "Aréfunwè y los hijos. Ifá consultó para varios que habían probado sin éxito: Lámoko en casa de Alárá, que preguntó por sus hijos y ofreció una gallina; Èrìgì Igbódù, que temía morir él o su esposa y ofreció un gallo; el cazador de ratas de Àkúré, que quería prosperar en el comercio y ofreció muchas ratas; y Aréfunwè, esposa de Àgbọnnìrègún, que quería hijos y ofreció una chiva. Les dijeron que ya iban por buen camino. Sus cosas mejoraron, y a Aréfunwè le cantaron: 'Ya llegaste a la fuente de los hijos'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para el dinero: semillas de ajé y maíz de guinea pulverizados con jabón negro, marcados con el signo y el canto, en una lámpara nueva de barro con plumas de loro, cauríes alrededor, sangre de paloma sobre el jabón y kola de cuatro gajos; el jabón es para lavarse las manos cada día.", "Ọ̀rúnmìlà: tela blanca, una paloma blanca, una gallina blanca y 4,400 cauríes.", "Tẹwogbọlá: cuatro palomas, una gallina y 16,000 cauríes.", "Mucho àmàlà; no preparar ñame machacado.", "Muchas ratas; gallina, gallo o chiva según el caso."]}, {"titulo": "Relaciones espirituales", "texto": "Bara Àgbọnnìrègún trae la abundancia. Èṣù avisa a los babaláwo. Ọ̀sanyìn y los demás adivinos no reemplazan a Ifá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Semillas de ajé (Aerva lanata), ẹ̀sọ (Hildegardia barteri), maíz de guinea, jabón negro, plumas de loro, lámpara de barro, kola de cuatro gajos, àmàlà, ratas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 121.1 (yorùbá): Aralemikaka awo Ọ̀bàrà-Òfún, / Aralemikaka awo Ọ̀bàrà-Òfún, / Aralemikaka awo Ọ̀bàrà-Òfún, / O rọ mi gbẹdẹgbẹdẹ awo Olipomojẹ, / O rọ mi gbẹdẹgbẹdẹ awo Olipomoje, / O rọ mi gbẹdẹgbẹdẹ awo Olipomojẹ, / Ọrọ mi pọ o kele, (lẹẹmẹta) / Ọrọ mi po o kele, / Ọrọ mi pọ o kele, / Li o difá fún Bara Àgbọnnìrègún. / Orin: / Owó yeyé ni'lẹ yi, / o Omuka kiika ẹyo okà nilẹ, / Owó yeyé ni'le yi o, / Omuka kiika eyọ okà ni'lẹ.", "Verso 121.2 (yorùbá): Itun ntun mii ṣe, / Ifá nfá wọn wa towótowó; / èrò òkèèrè nwa mii bowa: / a difá fún Ọ̀rúnmìlà. / Wọ̀n niki Ọ̀rúnmìlà wa rúbọ / a maa ri're lojo gbogbo. / Ẹbọ: Aṣo fünfún, ẹyẹlé fúnfún, / adiyẹ fünfun ati egbejilelógún owó. / Ó gbọ̀ ó rú.", "Verso 121.3 (yorùbá): Owó (Ajé) npoyika, / aya npoyika: / a difá fún Tewọgbọlá. / A niki o wa rúbo: / Eyẹlé merin, adiyẹ / ati egbàájo owó / nitoripe / ẹyẹ maa gbé ire òkèèrè / wa fún un. / Ó gbó ó rú.", "REZO: OBARA FUN IKI AWO INLE ADO IRIRE AWO IBA ASESI ADABA AWO OBI OTA OBINI SHAWO IBA IRO ADIFAFUN OLOFIN LUBA OMO ADAIBI ABEBOADIE MEYI ELEBO.", "REZO: OBARA GUOFUN IQUI AWO INLE ADO ERIRE AWO IBA ACESI EDABA AWO OBI ETA OBINE CHAWO IBA IRE ADIFAFUN OLOFIN LUBA OMO IBI ABEBEADIE MEYI FUN FUN.", "REZO: KUKUTE KUKU ADIFAFUN LUBA ERAADA EYELE ENIN ADIE EFUN OWO MELLO.", "REZO: BABA LERI BABA OBATA JEKUA ONI LOMA WA ONIBA OBARA MAFUN BABA OTONO NIFA ELESE OTUN ELESE OSI OBATALA OTA ENIFA OBATALA MANE YIRE AWO LERI IFA OBARA TOWA TELEUN OBATALA MONIRE ONIRE JEKUA BABA AWO LERI IFA.", "SUYERE: BABA NI LADEO BABA LO MA JEKUA BABA AWO OMO MI IFA", "+++ 161"]}]$q$::jsonb),
(122,'62f67ceda1492989f474022c70d2a78f',$q$[{"titulo": "Idea central", "texto": "Ọ̀kànràn Ogbè habla de vencer a los enemigos y a los competidores para alcanzar una posición destacada. Se ve un empleo nuevo, un ascenso o un aumento de sueldo. Ifá dice que la vida le será fácil, aunque ahora esté pasando tiempos duros. Para la mujer, pide comportarse con su pareja como Ifá indica."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Ve venir un empleo, un ascenso o un aumento, pero todavía no está confirmado.", "Se prepara para un puesto con obligaciones nuevas (relato de Olitikun nombrado Tẹ̀wíṣé).", "Quiere destacar ante sus competidores sin creer que todos son enemigos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Victoria sobre los enemigos.", "Un cargo de vocero o de confianza.", "Facilidad en la vida y riqueza.", "Ser una persona rica en la tierra."]}, {"titulo": "Ibi y advertencias", "puntos": ["Competidores que estorban el ascenso.", "Tiempos difíciles antes de la mejora."]}, {"titulo": "Enseñanza principal", "texto": "La ofrenda que se reparte a muchos trae la victoria: Olitikun repartió ciento ochenta tortas de frijol. La esposa que se comporta como pide Ifá vuelve rica su casa."}, {"titulo": "Relatos reunidos", "puntos": ["Olitikun, primogénito del Ewí. Ifá consultó para Olitikun, hijo mayor del Ewí, rey de Ado, y le pidió repartir ciento ochenta tortas de frijol, además de un chivo y 3,200 cauríes, para vencer a sus enemigos. Ofreció.", "Olitikun, vocero del rey. En otra consulta le pidieron seis gallos y 12,000 cauríes. Ofreció y fue nombrado vocero del Ewí.", "Ológun Ìsẹ̀sẹ̀, el sacerdote del camino. Ológun Ìsẹ̀sẹ̀ era sacerdote a la orilla del camino y pasaba tiempos duros. Preguntó si la vida se le haría fácil, y le dijeron que se sorprendería de lo fácil que sería. Ofreció, se hizo rico y exclamó sorprendido. Prometió marcar con una cuenta de iyùn su idè, su collar de Ifá.", "Jìngbìnní, esposa de Ọ̀rúnmìlà. A Jìngbìnní, esposa de Ọ̀rúnmìlà, le pidieron comportarse como Ifá le indicaba. Lo hizo y la vida le fue grata; se volvió una mujer rica. 'Un babaláwo sabio se pone su collar de idè.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para vencer: ciento ochenta tortas de frijol repartidas, un chivo y 3,200 cauríes.", "Para el cargo: seis gallos y 12,000 cauríes.", "Una cuenta de iyùn en el idè."]}, {"titulo": "Relaciones espirituales", "texto": "El Ewí de Ado, rey, da el cargo de vocero. Ọ̀rúnmìlà guía a su esposa Jìngbìnní."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tortas de frijol, gallos, chivo, cuenta de iyùn, hojas de ògúnsẹ̀rẹ̀ (usadas para envolver comida)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 122.1 (yorùbá): Panderẹ-folu-omi-likiti: / li o difá fOlitikun / tiiṣe aremo Ewí l'Ado, / wọ̀n niki ó fi ogosan akara ṣe'tẹ. / Öbúką ati ẹgberindilógún owó / Olitikun gbọ̀ ó rú.", "Verso 122.2 (yorùbá): Pandẹrẹ-folu-omi-likiti: / li o dífá f'Olitikun / tiiṣe aremo Ewi l'Ado. / Akuko mefà ati ẹgbaafa owó li ebọ. / Olitikun gbọ̀ ó rú. / Wọ̀n fi joyé T'Ewiṣẹ.", "REZO: OKANA SODDE OLE MIJILLA TIFI EFON MALU ILE NI OLE VALEGUN OBA SHONSHON OLE OUN SODDE NITA ORUNMILA OPALAYE OKANA JUN.", "REZO: OKANA SODDE OLE MIJILLA TIFI EFON MALU ILE NI OLE YALEGUN OBA SHONSHON OLE OUN SODDE NITA ORUNMILA OPALAYE OKANA JUN.", "REZO: OYA OLEDE ABORE IODE ADIFAFUN AULODE EPO OBI EKO AKUKO EYELE LEBO.", "REZO: OKANOBE OKANA BOBE ESHU UMBETINA SADE ANSI LEBO.", "REZO: OKANA UN ELODE AWO ELODE OMUA UNLLE LOCUTE MAFEREFUN ORUMILA ERUBO AIKORDIE AYA AKARA MEFA OBI MEFA AGUADO EÑA.", "REZO: OYA ELEDE ABEBOADIE ADIFAFUN AULEDE ABUKE, EPO, OBI, EKO, EYELE LEBO.", "REZO: OKANA SODE OMI LORI ATE BODO LORI ATE BODO SAKETE WALA EGUN LAIYERE EGUN LAYE BURUKU OMO ADETI WALAKUA SAKATE KATE LODAFUN DIDE LEKE LEKE PUAPUA FUN FUN KILOBO ADIFUN OKANA BODE NI AGBA OLOFIN ADASHE OLOFIN OLUO FIFITU INLE AINA EKU ORUBOSHE ADAFUN ORUNMILA, LODAFUN OGUN, LODAFUN OSHOSI, ASHE OWO EYO KAFEREFUN ELEGBA.", "REZO: OLE MIGILA TIFIEFON MALU ILE NI OLE YALOGUN OGBA", "SHONSHON OLE UN SORDENITA ORUNMILA OPALAYE OKAN JUN.", "REZO: OKANA SODE OMI LORI ATE BODO LORI ATE BODO SAKETE WALA EGUN LAIYERE EGUN LAYE BURUKU OMO ADETI WALAKUA SAKATE KATE LODAFUN DIDE LEKE LEKE PUAPUA FUN FUN KILOBO ADIFUN OKANA BODE NI AGBA OLOFIN ADASHE OLOFIN OLUO FIFITU INLE AINA EKU ORUBOSHE ADAFUN ORUNMILA, LODAFUN OGUN, LODAFUN OSHOSI, ASHE OWO EYO KAFEREFUN ELEGBA.", "REZO: OLE MIGILA TIFIEFON MALU ILE NI OLE YALOGUN OGBA SHONSHON OLE UN SORDENITA ORUNMILA OPALAYE OKAN JUN.", "SUYERE: OKANA JUN JUN JUN OPALAYE UNLO ASHELU UNLO GBOGBO ASHO ILU UNLO."]}]$q$::jsonb),
(123,'9fc90c839441eac484c8808c5af74e49',$q$[{"titulo": "Idea central", "texto": "Ọ̀kànràn Ọ̀yẹ̀kú dice que la ofrenda trae riqueza y estabilidad, y que negarse a ofrendar trae destrucción, guerra y pérdidas. A la persona le gusta arriesgarse o no aprende de los errores ajenos; debe tomar experiencia de los fracasos de otros y trabajar con sus ancestros para evitar trampas. Tiene un hermano al que debe ayudar a quitarse un mal de encima."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Toma riesgos sin aprender de lo que les pasó a otros.", "Teme que un pleito se extienda a su familia o a su proyecto (relato de Igbeyin-Odo y la casa de Itori).", "Busca bienestar económico y apoyo de sus antepasados.", "Pregunta por un hermano."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza en abundancia, como la jícara llena del vendedor de aceite.", "Salvar a un hermano de la muerte.", "Que los hijos dejen de morir.", "Comodidad en la casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Guerra y pérdidas por no ofrendar.", "Tomar riesgos sin aprender de lo que les pasó a otros.", "Hijos que mueren uno tras otro."]}, {"titulo": "Enseñanza principal", "texto": "La guerra que acabó con un pueblo pasó al siguiente que tampoco ofrendó. Hay que aprender de lo que le pasa al vecino y hacer la ofrenda el mismo día que se marca."}, {"titulo": "Relatos reunidos", "puntos": ["La guerra de Igbeyin-odo. Ifá consultó para la gente de Igbeyin-odo y para la casa de Itori, y les pidió diez gallos y 20,000 cauríes. La gente de Itori no ofreció, y la guerra que mató a los de Igbeyin-odo llegó también a su casa.", "Riqueza y más riqueza. 'Ọ̀kànràn Ọ̀yẹ̀kú dice riqueza; yo digo más riqueza, tanta como la jícara del vendedor de aceite, del vendedor de òrí y del vendedor de cuentas.' La comodidad de una casa se reconoce en el baño húmedo y en la vasija llena de agua. Se ofrecen ocho caracoles y 16,000 cauríes.", "Olọ̀kànràn salva a su hermano. Le dijeron a Olọ̀kànràn que su hermano tenía un ajogun, un hechizo de muerte, en el cuello, y que sería el hermano menor quien lo salvaría. Le pidieron hacer la ofrenda ese mismo día: agua, ayunar y soplar sobre la mano. Ofreció, el hermano también ofreció, y se quitó el mal de su cuello.", "Los hijos de Olọ̀kànràn. Los hijos de Olọ̀kànràn morían uno tras otro. Le pidieron un chivo grande. Ofreció, la enfermedad no volvió a tocarlo ni a él ni a sus hijos, y empezaron a disfrutar la vida."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Diez gallos y 20,000 cauríes.", "Para la riqueza: ocho caracoles y 16,000 cauríes.", "Para el hermano: la ofrenda el mismo día, con agua.", "Para que vivan los hijos: un chivo grande."]}, {"titulo": "Relaciones espirituales", "texto": "Los ancestros ayudan a evitar las trampas. Ifá protege a los hermanos que se ayudan."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Gallos, caracoles, chivo, agua, aceite de palma, òrí, cuentas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 123.1 (yorùbá): Tẹkutu awo omodé / Tẹkata awo àgbàlagbà / O kù Ìká kan kio di Eji-Qyè / li o difá fún wọn n'lgbeyin-Odo, / ó bu fún wọn nile Itori. / A niki wọ̀n rú: / Akuko méwà, / egbàá méwà owó. / Ará òde Itori ko rúbo / Njẹ ogun tiiba pa İgbeyin-odo / lọ sile Odo-Itori.", "Verso 123.2 (yorùbá): Ọ̀kànràn'Yẹ̀kuI: orp, / Mi: Aromọ / I riro niiro lgbá elépo, / 1 rirọ niiro lgbá olòri, / I rirg niiro Igba aladin, / Kiidẹ'lede'na ko ni ojuto (baluwẹ) lara / Gbẹdẹgbẹdẹ niirg'di iponmi. / Igbin méjo / ati egbàájo owó li ebọ. / Biobarubo, / Ifá ni a rọ eni-ohun lọrùn.", "REZO: TEKITE AWO TAKITI OKANA YEKU ALALUYE TAKI BOMBO ADIFAFUN ALUFIN RUDA TEKITE AWO MIODE TEKATA AWA LAWUAKOKATE OWASUN LODIDE TORIKI IYA ELEKE FUN FUN ILEKE DUN DUN TEKITE KON ADIFAFUN ORUNMILA ADIFAFUN ARUFIN ARUDA.", "REZO: OKANA YEKU IFA ARUFIN ARUDA AKITIFA BONBE WA LASHE ASHETO AKITIBONBO ORUNMILA NARE BABA SHE ORUN ARAFIN ARUDA. OKANA YEKU OBERE LERE OLOKUN BABA KASHIRE, OLUWO POPO OBERE LERE OMAYERE ASHE BOGBO ARUNMALE LIKOTUN BOGBO ARUNMALE YIKOSI TO IBAN ESHU.", "REZO: OKANILELE ODI OFA ERONA OCHUCA ORI LEBO ABEBOADIE MEFA OWO AKUKO EYELE LEBO.", "REZO: ONILLE LASA OSHINDINILLE ODAFUN OMO TINTUN TOMBOA OKANA YEKU KILLELASA ORUBO AKUKO IGA OSHO YARAKO YARAKO IBA MEYI.", "REZO: TEKIRE AWO NIODE TEKATA AWALAWA KOKATE AWASAFUN LODIDE TORIKI TORIKI OGGUN AWASAFUN LODIDE TORIKI BUENE LEKE LEKE DUNDUN LEKE FUN FUN TEKITE BONEBO ADIFAFUN ARUFIN ADIFAFUN ORUNLA.", "REZO: OKANA YEKU ONI BORO OKANA OMO NI YERENI AWO KUAORIN AKIKINIBOBO YANIRE AJIO BEBEFULANA FOKO NIRE ENIBASHEO OKANA YEKUN YEKUN ASHOBI ASHO AWO ABANERI.", "REZO: ASHEDA ESEDOMI UNYEKO SHA ASHE AKEDA INLENI ESHAKUA- RIBE LORUN OSHA FILERE SHARALOKUE ORIKOSHE OMARI", "ITA SHILEDUN OSHA OMOTOKUE LERI YEKUE LESO OSHA ALAYA IFAORI IKOKO BOKELE MAFILELE OLERUN ESIN LAYE- NI OSHAWO KASHERA BABWA OGGUN KADUMINA.", "SUYERE: ARUFIN ARUDA SHISHEBO ADA ARUFIN ARUBA OMONI SHEGBO ADAWE.", "REZO: OKANA YEKU ONI BORO OKANA OMO NI YERENI AWO KUAORIN AKIKINIBOBO YANIRE AJIO BEBEFULANA FOKO NIRE ENIBASHEO OKANA YEKUN YEKUN ASHOBI ASHO AWO ABANERI.", "REZO: ASHEDA ESEDOMI UNYEKO SHA ASHE AKEDA INLENI ESHAKUA- RIBE LORUN OSHA FILERE SHARALOKUE ORIKOSHE OMARI ITA SHILEDUN OSHA OMOTOKUE LERI YEKUE LESO OSHA ALAYA IFAORI IKOKO BOKELE MAFILELE OLERUN ESIN LAYE- NI OSHAWO KASHERA BABWA OGGUN KADUMINA."]}]$q$::jsonb),
(124,'3e51fdf81024a0e64152528b0c9ba039',$q$[{"titulo": "Idea central", "texto": "Ọ̀kànràn Ìwòrì advierte que la persona debe compartir sus problemas con otros para encontrar soluciones; el miedo y la costumbre de callarlo todo le bloquean el avance. Hay una visita cercana y se ofrenda para que traiga prosperidad. Habla también de dos personas que deben ofrendar para que a una no le pase algo malo de improviso."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se guarda sus preocupaciones por miedo a contarlas (relato del lagarto Alaamu).", "Espera a alguien que puede traer noticias o bienestar (relato de Moyebo).", "Una colaboración está parada por falta de comunicación (relato del Día y la Lluvia)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un visitante que trae bendiciones.", "El regreso de alguien que tardaba.", "Que nadie le quite su lugar.", "Orden, respeto y una tierra extensa, como los reyes."]}, {"titulo": "Ibi y advertencias", "puntos": ["Callarse los problemas y golpearse solo.", "Una ofrenda incompleta que deja que otro opaque su brillo.", "Pleitos entre dos mayores."]}, {"titulo": "Enseñanza principal", "texto": "Si uno se calla lo que le pasa, nadie puede ayudarle. El lagarto no le contaba a nadie sus penas y se golpeaba la cabeza contra la palma y la pared; por eso nadie lo compadece."}, {"titulo": "Relatos reunidos", "puntos": ["El lagarto que no cuenta sus penas. Ifá consultó para el lagarto y los demás reptiles. El lagarto dijo que no le contaba sus problemas a nadie, y se golpeaba la cabeza contra el tronco de la palma y contra la pared. Le pidieron un chivo, un gallo, una paloma y 8,000 cauríes. No ofreció, y desde entonces nadie se compadece de él.", "Moyebo regresa. Moyebo se fue de viaje y no volvía; su padre y su madre lo esperaban. El adivino les dijo que regresaría si ofrecían una gallina, una paloma, una langosta y 12,000 cauríes. Ofrecieron. Ifá dice que se espera a un visitante que trae bendiciones.", "El día y la lluvia. Al día y a la lluvia les pidieron ofrendar. La lluvia hizo su ofrenda completa; la del día quedó incompleta. Por eso, por brillante que esté el día, cuando empieza a llover se oscurece: donde la lluvia encuentra al día, lo alcanza.", "Los reyes y los tres pájaros. Cuando los reyes venían del cielo a la tierra, preguntaron a Ọ̀rúnmìlà si la tierra sería buena. Les dijo que prevalecerían sobre todos, pero que debían ofrecer tres pájaros: el buitre, para que el mundo se ordenara; el òsìn, para que los que no los honraban los honraran; y el tẹ̀ntẹ̀rẹ́, para que la tierra fuera llana y extensa. Ofrecieron los tres y así sucedió. Al llegar vieron a los jefes de Ifá, Akódá, Aṣẹ̀dá, Olúwo y Odùgbọ̀nà, y dijeron que el orden del sacerdocio estaba completo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El lagarto: un chivo, un gallo, una paloma y 8,000 cauríes.", "Moyebo: una gallina, una paloma, una langosta y 12,000 cauríes.", "Los reyes: un buitre, un pájaro òsìn y un pájaro tẹ̀ntẹ̀rẹ́."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà aconseja a los reyes. Akódá, Aṣẹ̀dá, Olúwo y Odùgbọ̀nà son jefes del sacerdocio de Ifá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Langosta, paloma, gallina, pájaros (buitre, òsìn, tẹ̀ntẹ̀rẹ́)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 124.1 (yorùbá): Bi a dakẹ t'ara eni a bani dakẹ, / Bi a ko wi t'enu eni fAyé / gbọ a kiin'agborandun: / a dífá fún Alaamu, / a bu fun kokoro gbogbo, / o ni ràn ti o de ba òun yì, / òun ko nii ro f'ẹnikan. / O nf'orí sọ pè ati egbẹ ogiri. / Won ni: / \"Elegbe a wọn on nidi rán naa\". / Ebọ: Ọbúko, akuko-adiyẹ, ẹyẹlé ati egàárin owó. / Ko rúbo.", "Verso 124.2 (yorùbá): Ayunboli-owo-nyun-ẹnú: / li a dá fún Moyebo, / Moyebo los'ajo e tete de. / lyá nreti rẹ, Baba nreti rẹ. / Wọ̀n ni: / “Mọyẹbọ a de, ẹbọ niki a ṣe”. / Agbebo-adiyẹ, eyẹlé, ede, egbèfà owò. / Wọ́n gbọ́ wọ́n rú. / Ifá ni: / \"Ẹ nreti àlejò kan, / òun yoo de biẹba rúbo\"", "REZO: OKANA WORI AGAROFI ADIFAFUN OSAIN OBANISHAWO MAFEREFUN SHANGO, ABO, AKUKO, ETU LEBO.", "REZO: OKANA WORI AGAROFI ADIFAFUN OZAIN OBANISHAWO MAFEREFUN SHANGO, ABO, AKUKO, ETU LEBO.", "REZO: OKARA FI ADIFAFUN OZAIN ABENI SHANGO O SHANGUO ASHO LEBO ETU EYA EURE LEBO."]}]$q$::jsonb),
(125,'7932f6f449b2ed1d0668eb0366234f64',$q$[{"titulo": "Idea central", "texto": "Ọ̀kànràn Ìdí habla de una relación de pareja que al final saldrá bien. Una sociedad, un trabajo o una relación que antes se buscó sin lograrlo puede revivir ahora. La persona tendrá vida larga y buena salud con la ofrenda, y no debe regatear lo que Ifá pide."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una oportunidad de amor o de trabajo que no se dio puede volver (relato de Ọ̀rúnmìlà y Ẹhìnmọlá).", "Se impacienta porque la otra persona no responde como quisiera.", "Debe ver si la relación respeta lo que quieren los dos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una pareja que al final llega.", "Salud y vida larga.", "Resistir los golpes de la vida."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enojarse si la otra persona no responde de inmediato.", "Regatear la ofrenda.", "Enfermedad que no deja levantarse."]}, {"titulo": "Enseñanza principal", "texto": "La paciencia gana: Ẹ̀hìnmọ̀la rechazó a Ọ̀rúnmìlà y un año después fue ella quien llegó a su casa. Y la ofrenda no se rebaja: si se rebaja lo que se paga, se rebaja también la medicina."}, {"titulo": "Relatos reunidos", "puntos": ["Ẹ̀hìnmọ̀la. Todas las deidades trataron de ganar el amor de Ẹ̀hìnmọ̀la y ninguna lo logró. A Ọ̀rúnmìlà le pidieron una paloma, 12,000 cauríes y medicina de Ifá, y le aconsejaron no perder la calma ni enojarse si ella no le hacía caso de inmediato, porque terminaría siguiéndolo. Ella lo rechazó, y él se fue a Ado. Un año después Ẹ̀hìnmọ̀la quiso casarse, pero ninguna deidad pudo quitarle lo que había quedado sobre ella. Hizo su maleta y llegó a la casa de Ọ̀rúnmìlà justo cuando celebraba la fiesta del ñame nuevo; a él se le habían acabado el aceite de palma y la sal, y ella los sacó de su equipaje. Al terminar la ofrenda, Ọ̀rúnmìlà le preguntó qué hacía ahí, y ella dijo: 'Vine por ti'. Él le dio dos pedazos del ñame ofrendado y le dijo que ya podía comer y beber. Así se volvió su esposa. Su nombre quiere decir 'la riqueza y el honor me siguen'.", "El molde del herrero. El molde estaba enfermo en la herrería y no se podía levantar. Le pidieron ofrendar para tener salud y fuerza: lo golpearían y golpearían, pero nada lo vencería y tendría vida larga. Ofreció y se puso fuerte. Por eso hasta hoy suena en la herrería: 'din din kúù din'.", "Olọ̀kànràn y el regateo. Olọ̀kànràn fue a la casa de Ìdin a regatear el costo de la ofrenda. Le dijeron: 'Si rebajas lo que pagas, rebajamos la medicina; no vuelvas a regatear'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: una paloma, 12,000 cauríes y medicina de Ifá.", "Para la salud: la ofrenda completa, sin rebajas."]}, {"titulo": "Relaciones espirituales", "texto": "Las Irúnmọlẹ̀ (deidades) no pueden deshacer lo que Ọ̀rúnmìlà decide. Ọ̀rúnmìlà conoce el futuro."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame nuevo, aceite de palma, sal, paloma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 125.1 (yorùbá): Ikoko dúdú kogbọ ti ara rè / ó ngbọ ti eni-eleni kiri: / a difá f'Ọ̀rúnmìlà / nlọ m'ẹ̀hinmọ̀la ṣ'aya. / Gbogbo Irúnmalè lioti fẹ Ehinmola ti. / Wọ̀n niki Ọ̀rúnmìlà rú: / eyẹlé, egbẹfà owó ati ewé Ifá. / Ọ̀rúnmìlà gbọ̀ ó rú. / Wọ̀n ni: / bi obirin naa ko ba tètè gbọro / naa sii lẹnu ki o ma binu o. / Esẹ ara obirin naa niyo / fi wa p wa sibikibi tiowu kiowa. / Nijọ ti Ọ̀rúnmìlà ti fẹẹ tiokọ ni oun / ti paale lee tiositi ba tirẹ / lọ si'le Ado Ayiwọ. / O to odún kan gbako lẹhin ti Ọ̀rúnmìlà / ti lọ tan ni okan Ehinmọ̀la wa yipada. / O nfẹ lati ni okọ. / O wa nyi odọ gbogbo àwọn Irúnmalẹ ka, / sugbọ̀n kosi okan ninu gbogbo wọn / tioleṣi aale ti Ọ̀rúnmìlà pa lee. / Wọ̀n fẹ ṣee titi sùgbón / wọ̀n ṣee ti wọn ko le ṣee. / Nigbanaa ni Ẹhinmola wa di erù / bi eniti nlọ ile-okọ / ti o si tọ Ọ̀rúnmìlà lọ ni ile Ado. / Ọ̀rúnmìlà nṣe odún iṣu-titun / gẹẹ lọ̀wo ni Ehinmọ̀la yọ sii. / Ọ̀rúnmìlà pẹla iṣu-titun tan ko ri epo / ati iyo bus'oju rẹ. / Bẹẹni Ẹhinmola yara tu erù rẹ̀. / O si mu epo ati iyọ jade fún Ọ̀rúnmìlà. / Nigbati Ọ̀rúnmìlà ṣetutu tan, / o wa pe Ẹ̀hinmola, / o biileere o ni: / Kini o tilẹ wa de ihinyi? / Ehinmola dahun pe: / Iwọ ni. / Nigbanaa ni Ọ̀rúnmìlà ko ẹla-iṣu Méjì / ninu àwọn tiotifiṣ'ebọ. / O nfi ojú wọn kirin ara wọn. / O gbe fun Ẹ̀hinmola ó wipe: / O di jüjẹ, Ehinmola. / O di mumu, Ẹ̀hinmọ̀la. / Bayi ni òun di aya Ọ̀rúnmìlà si, / ti a siimaa bere pe: / \"Tani-m'ẹ̀hin-ọla?\" / Wọ̀n a ni: / \"Ọ̀rúnmìlà li o m'ẹ̀hin ola ó\" / Lati igba naa wa titi di òni.", "REZO: OKANA DI TOBATO EFAN KARE BEYA ADIFAFUN ODOLOFA TOLOYO LOSHELE ABE ELEBO, IWO OBINI KAN LOLEFUN EYELE AKUKO LEBO. OKANA DI IFA NIRE KAFEREFUN SHANGO, OSHANLA ATI ESHU.", "REZO: OKANA DI TOBATO EFAN KARE BEYA ADIFAFUN ODOLOFA TOLOYO LOSHELE ABE ELEBO, IWO OBINI KAN LOLEFUN EYELE AKUKO LEBO. OKANA DI IFA NIRE KAFEREFUN SHANGO, OSHANLA ATI ESHU.", "REZO: TBATE EFUN CARE BELLA ADIFAFUN ODOLOFA TOLELLO LECHE LE ABA LEBO IGUO OBINI CAN LOFECU EYELE AKUKO LEBO. NIRE KAFEREFUN SHANGO OSHANLA Y ESHU."]}]$q$::jsonb),
(126,'487a379e447b5aaa284ca1e820eb7165',$q$[{"titulo": "Idea central", "texto": "Ọ̀kànràn Ìrosùn avisa del peligro de las acciones y palabras irresponsables que bloquean el progreso; con arrepentimiento sincero, siempre se perdonan. La persona suele tener problemas con su pareja o sus hijos. La pareja es de trato difícil, y Ifá le pide hablarle bien para que se quede. Recibirá buena acogida de reyes y personas importantes, y regalos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene pleitos con su pareja o sus hijos.", "Se arrepiente de algo que dijo o hizo y necesita disculparse.", "Quiere moverse con libertad sin que un problema del pasado le estorbe (relato de la gallina y sus pollitos).", "Hay un conflicto amoroso (relato de Bàtá y Koko)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Perdón por los errores si se disculpa.", "Conservar a la pareja con buenas palabras.", "Regalos y buena acogida de los poderosos.", "Moverse libremente sin tropiezos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Palabras y actos irresponsables.", "Que las brujas y Èṣù bloqueen la fortuna.", "Problemas con la pareja o con los hijos."]}, {"titulo": "Enseñanza principal", "texto": "El daño hecho a propósito no es bueno, pero si uno se disculpa no hay problema: la gente perdona al que no sabía. Hasta Ṣàngó perdonó a Bàtá cuando el tambor siguió sus pasos y le pidió perdón."}, {"titulo": "Relatos reunidos", "puntos": ["La gallina y sus pollitos. Ifá consultó para la gallina y sus pollitos, que andaban sueltos, para que pudieran seguir yendo de un lado a otro sin perder la vida. Les pidieron un osù, una rata, un pescado, 2,800 cauríes y medicina de Ifá.", "El que pide perdón. Todo el mundo se quejaba de Ọṣ'ọ̀ràn-ṣ'akin. Las brujas, los hechiceros y Èṣù le estaban cerrando la fortuna que venía de Olódùmarè. Le dijeron que si se disculpaba sería perdonado, y le pidieron cuatro palomas, una carnera, nueces de kola, 3,200 cauríes y medicina de Ifá. Ofreció, y le aseguraron que Olódùmarè le diría a Èṣù que lo perdonara.", "Bàtá y Koko, la mujer de Ṣàngó. Koko, mujer de Ṣàngó, se encariñó con Bàtá y quería casarse con él. Bàtá sabía lo difícil que era Ṣàngó y se negaba, pero ella hizo sus cosas y se fue a su casa. Ṣàngó llegó furioso a pelear. Bàtá se levantó y tocó: 'Olúbámbí, perdóname; déjamela por Koko', y los golpes del tambor iban al compás de los pasos de Ṣàngó. Ṣàngó dijo: 'Tu tambor sigue mis pasos; está bien, te doy a Koko para siempre'.", "El cazador y los viajeros perdidos. El cazador preguntó si la vida le sería buena y le pidieron ñames. Los babaláwo se quedaron con la mitad como regalo. Se fue al bosque y puso unos ñames a asar. Unos viajeros que llevaban mucho tiempo perdidos y tres días sin comer vieron el humo, llegaron y comieron. Le dijeron: 'Tú eres nuestro guía a casa', y él los llevó con el rey. Al cumplirse el año, los visitantes le daban diez cargas de ñame al cazador y él cinco al rey. Así le llegaron los regalos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La gallina: un osù, una rata, un pescado, 2,800 cauríes y medicina de Ifá.", "Para el perdón: cuatro palomas, una carnera, nueces de kola, 3,200 cauríes y medicina de Ifá.", "El cazador: ñames, la mitad para los babaláwo."]}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó (Olúbámbí) perdona a Bàtá. Olódùmarè ordena a Èṣù perdonar. Las brujas bloquean la fortuna del que no se disculpa."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de olúṣesájú (Petiveria alliacea) y oriji trituradas con jabón negro, para baño. Ñames asados, kola, tambor bàtá."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 126.1 (yorùbá): Ọ̀ràn-kiiba'nikiayè-ori, / Enibari-pràn-Heepa-onada, / Qnaniyiadurotiwon. / a dífá f'Adiyẹ / a bu f'awọn omo adiyẹ / nigbati wọn maa kiri de'gbo ewọn. / A niki wọn wa rubo / bi wọn ti nfẹ lati maa rin kiri yi, / kiwọn maa baa ṣegbe sibi idaduro. / Ẹbọ: Osù, eku, eja, / egbèrinlá owó ati ewé Ifá.", "Verso 126.2 (yorùbá): Imoràn-ṣe-ibikosunwòn, / Eniti-nṣe-ibi-biobabẹbẹ oràn, oràn-a-tán. / Gbogbo ayé ni nfi ori ji Memo. / Imoràn-ṣe-ibi-kosunwọn: / A difá f'Oṣ'öràn-ṣ'akin Mẹbẹlufẹ. / Gbogbo wọn ni nfi ejó rẹ̀ sun, / bioba bẹbẹ-oràn wọ̀n a ni: Ó tán. / Ó wa di ijọ kan. / Wọ̀n ni: / Oṣó, Ajẹ ati Èṣú baba wọn / di're mọ odọ Olódùmarè. / Nitorinaa ki o wa rúbo: / Eyẹlé merin, àgùtàn, Obi, / ẹgberindilógún owó ati ewé Ifá. / 0 rúbọ. / Wọ̀n ni: / Olódùmarè a sọ fún Èṣú / ki wọn fi ori jii.", "REZO: OKANA ROSO ADIFAFUN OKUNA ARATAKO OLE ESON OZAIN NILE KAFEREFUN ORUNMILA.", "REZO: ASAYE DARICO EYE AKUKO ADIFAFUN BOLELE ADIE LEBO MODURO DURU ARACE COMIMOBORE EÑI INDIMU MOLLO COLLO- CO IDIAMITI MERETI RETI ATIMIDE ATIMISE ADIFAFUN ORUMILA UMBANTILO CHAGUE MIBO AGUTAN LEBO BA UNA MOENITAN ENLOQUENO PUEDA EYELE AKUKO LEBO. ODAFUN ORUMILA OLODAFA YALORDE.", "REZO: OKANA ROSO ADIFAFUN OKUN ARATAKE ELE ESEN OZAIN NILE KAFEREFUN ORUNMILA.", "REZO: ADIFAFUN OKUNI ARATAKE ELE ESEN OZAIN NILE MAFEREFUN ORUNMILA.", "REZO: ADIFAFUN OKUNI ARATAKE ELE ESEN OZAIN NILE MAFEREFUN ORUNMILA."]}]$q$::jsonb),
(127,'4463e629cba46e83a44fdc81087ce327',$q$[{"titulo": "Idea central", "texto": "Ọ̀kànràn Ọ̀wọ́nrín habla de problemas legales y sus consecuencias: el delito se castiga. La persona tendrá con frecuencia problemas con el gobierno o con hacienda; debe evitar la desobediencia, la soberbia y la vanidad. Todo lo que ha intentado sin avanzar saldrá bien con la ofrenda, y unos seres del cielo le harán regalos. No debe ser descuidado con su pareja ni dejar pasar la primera fortuna que le llegue."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Enfrenta un problema legal o de trámites (relato de Ọ̀kànràn y el juicio).", "Siente ganas de desobedecer o menospreciar una obligación.", "Debe reparar lo que dañó antes de que el conflicto crezca (relato del grupo que presumía de hacer daño)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Salir con vida de un proceso judicial.", "Éxito en lo que antes no avanzaba.", "Regalos que vienen del cielo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Problemas legales y castigo.", "Hacer el mal porque por ahora le va bien.", "Descuidar a la pareja y perderla.", "Dejar pasar la primera oportunidad."]}, {"titulo": "Enseñanza principal", "texto": "Por tarde que parezca, la cuenta del daño llega, como las olas del mar que deshacen la carga poco a poco. Y quien maltrata a su pareja termina buscándola y aullando, como el perro."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀kànràn en el juicio. Le abrieron un proceso judicial a Ọ̀kànràn. Le pidieron una paloma, una carnera y 22,000 cauríes para no morir durante el juicio. 'Ọ̀kànràn descansará; las palomas traen fortuna cuando entran a la casa; larga es la vida de la carnera.' La mayor parte del dinero ofrecido se reparte a otras personas; solo una parte pequeña es para el babaláwo.", "Los que hacían el mal. Unos presumidos decían que Ọ̀rúnmìlà estaba lleno de advertencias pero que ellos harían lo que quisieran; hacían maldades y crueldades y les iba bien. Ọ̀rúnmìlà dijo que, por tarde que pareciera, el pago por el daño venía en camino, como las olas del mar, y que cuando llegara huirían. Se ofrecen dieciséis caracoles, aceite de palma y 18,000 cauríes para que esas maldades no entren en nosotros.", "Awógbádé, hijo de Dios. Awógbádé probaba de todo sin éxito. Le aseguraron que todo saldría bien y ofreció. Dios, que había tapado el carácter con una jícara, la destaparía ese año.", "El perro y Àlá Òru. El perro descuidaba y maltrataba a su esposa, Àlá Òru. Ella se fue. Cuando el perro volvió a casa y la llamó, ya no le respondió nadie. Por eso el perro aúlla cuando oscurece: anda buscando a Àlá Òru. 'Te dijimos que no jugaras con lo bueno que tenías.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["En un juicio: una paloma, una carnera y 22,000 cauríes; la mayor parte del dinero se reparte.", "Contra la maldad: dieciséis caracoles, aceite de palma y 18,000 cauríes.", "Ofrenda por la pareja."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà advierte a los soberbios. Olọ́run guarda el carácter bajo la jícara."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Palomas, carnera, caracoles, aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 127.1 (yorùbá): Rojuforitii, / a difá fQkànràn, / Ejọ de, ti Arin ni (Afi'nirerin) lo ju. / Wọ̀n ni: / ẹbọ niki a ṣe / ki Ọ̀kànràn maa kús'ẹjó. / Ebọ: Ẹyelé, àgutàn ati egba mokànla owó. / Ó gbọ̀ ó rú. / Wọ̀n nì: / Ọ̀kànràn a simi o, / ọ̀tún ati òsin ni eyẹlé / fi nko'ree wọle, / igbagigun niti àgùtàn, / Agutàn ti gba're Karojuṣayé, / gbogbo ayé niifẹran owó.", "Verso 127.2 (yorùbá): Jẹkoṣeka ngbe Oṣiká, / Jẹkoṣebi ngbe Aṣebi, / a difa fawon Afpigbọ / ti nwipe Ọ̀rúnmìlà nkilo ràn jù, / ti inú awọn li awọn maaṣe, / wọ̀n nṣe ibi, / wọ̀n nṣe Ìká, / ohun ayé ndara fún wọn, / a lọ wi fún Ọ̀rúnmìlà, / O ni: / Bobapẹtiti-ẹlẹsan mbowa, / gbirigbiri-ayikan, / Otumolerukalẹ, aṣejejẹṣiṣe, / bioba de gbogbo wọ̀n a sa. / Wọ̀n niki a ṣebo / ki jẹkoṣeka ati Jẹkoṣebi / ma le r'aye bosi ikun eni, / ki àwọn egbẹ ati ogba / ma ba fi wa rẹrin elẹya ni igbẹhin. / Ebọ: İgbin mẹrindilógún, epo, egbàá mésàn owó. / Wọ̀n gbó wọ̀n rú.", "REZO: OKANA JUANI OKAWA WA WA ADIFAFUN EBBO LEYE ADIE ELEN LEBO. KURE KURE EURE, EKU LEBO. IFA NIRE KAFEREFUN YALORDE ATI ESHU.", "REZO: OKANA GUA GUA ADIFAFUN OBOLOLLE ADIE CIEN LEBO LEBO CURE CUERE EKU LEBE. IFAMIRE KAFEREFUN YALORDE Y ESHU.", "REZO: OKANA ONIKAN NI OSHE OKO YABILE OPON OJUANI POKON TOBABI BINU TOBALA OKUTA NIGRE OKUTA MASHAYE AWO KAÑI YOKO OMO AYOSHE ELEGBA OKEKE OPON INLE ADA- KUNSHE SIERU ADE ESHU BI OYE OWUNKO LOBI LODAFUN ORUNMILA KAFEREFUN ESHU Y OPON.", "REZO: OKANA JUANI APUORI EDABO AÑI MARUN EBBO AUN BABALAWO LODAFUN BRILOWO LEIE EYA KUO ARO EYA ORUN KUADAN NI ASHERE LODO ORUNMILA POKUYE FIABILE PURAN ADIFAFUN AWO AUMBI YABILE OKARAN JAU JUANI EYELE AKUKO EBBO MOSOSA ENDENI BOSHE ABE EURE EYELE LEBO.", "REZO: OKANA ONIKAN NI OSHE OKO YABILE OPON OJUANI POKON TOBABI BINU TOBALA OKUTA NIGRE OKUTA MASHAYE AWO KAÑI YOKO OMO AYOSHE ELEGBA OKEKE OPON INLE ADA- KUNSHE SIERU ADE ESHU BI OYE OWUNKO LOBI LODAFUN ORUNMILA KAFEREFUN ESHU Y OPON.", "REZO: OKANA JUANI APUORI EDABO AÑI MARUN EBBO AUN BABALAWO LODAFUN BRILOWO LEIE EYA KUO ARO EYA ORUN KUADAN NI ASHERE LODO ORUNMILA POKUYE FIABILE PURAN ADIFAFUN AWO AUMBI YABILE OKARAN JAU JUANI EYELE AKUKO EBBO MOSOSA ENDENI BOSHE ABE EURE EYELE LEBO."]}]$q$::jsonb),
(128,'ef6ead8e7f1331a3ec7d0d8b25acd359',$q$[{"titulo": "Idea central", "texto": "Ọ̀kànràn Ọ̀bàrà habla de evitar la muerte prematura y de que los desastres naturales no sorprendan en casa. Hay posibilidad de conflictos con los hijos y con los padres. Ifá le desea una buena pareja y muchos hijos que prosperen. En su casa hay una herencia de los ancestros que no debe dejar morir."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene conflictos con sus hijos o con sus padres (relato de Ọlaṣoni).", "Le preocupa la seguridad de su casa ante una tormenta (relato de Ọla-Ogún y el rayo).", "Espera bienestar en la pareja y con los hijos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vida larga y salud.", "Que el rayo no caiga sobre la casa.", "Muchos hijos y regalos.", "Que las tradiciones de la familia sigan vivas."]}, {"titulo": "Ibi y advertencias", "puntos": ["Muerte prematura por no ofrendar.", "Desastres naturales en casa.", "Abandonar las prácticas de los antepasados."]}, {"titulo": "Enseñanza principal", "texto": "Cuando uno envejece va a reunirse con los padres que conoció desde el principio; si abandonó sus costumbres, lo regresan. Por eso no se deja morir el egúngún, el Òrìṣà ni nada de lo heredado en la casa."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlaṣoni. Le pidieron a Ọlaṣoni una carnera y 44,000 cauríes para tener vida larga y sana. No ofreció.", "Ọla-Ògún y el rayo. A Ọla-Ògún le pidieron un carnero, un caracol, bastante aceite de palma, plátanos maduros pequeños, 24,000 cauríes y medicina de Ifá para que el rayo de Ṣàngó no cayera en su casa.", "Olóbà Abèdú y sus hijos. Olóbà Abèdú preguntó si recibiría regalos y si su vida sería buena. Le prometieron muchos hijos que prosperarían. Ofreció, tuvo tantos que les partía la comida en la boca, y vivió de los regalos.", "La herencia de la casa de Olóbà. A Olóbà le dijeron que ofrendara para que el monumento de sus antepasados no muriera: el egúngún, el Òrìṣà y todo lo venerado en su casa. Cuando uno envejece va a encontrarse con sus padres, y si no siguió sus costumbres lo mandan de vuelta. Cumplió, y todo le salió bien. 'Que no muera el egúngún de la casa de Olóbà; que no muera nada de lo heredado.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para vida larga: una carnera y 44,000 cauríes.", "Contra el rayo: un carnero, un caracol, aceite de palma, plátanos maduros pequeños, 24,000 cauríes y medicina de Ifá.", "Ofrenda a los ancestros para mantener la herencia."]}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó manda el rayo. Egúngún y los Òrìṣà de la casa deben mantenerse vivos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Contra el rayo: hojas de ẹ̀sọ (Elytraria marginata), plátanos maduros pequeños y el caracol, puestos en un hoyo en el piso de la casa sobre todo el aceite de palma, cubiertos con arena y aplanados con agua."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 128.1 (yorùbá): Ọ̀kànràn-Bàrà: / a difá fún Ọlaṣoni. / Wọ̀n niki o wa rúbọ / emigigun ninu ayé ati aralile / kiomabaakú l'ojo aipẹ. / Ebọ: Agutàn / ati egbàá méjilélógún owó. / Ó gbọ̀ ko rú.", "REZO: OKANA BARA OLODAFUN ORUNMILA OÑI PATAKI KODAFA ESHU IFE LEDOYA ELEGBARA LATILE MIATELE AWO ANOTIWO ATELE ESE NITASE ADIFAFUN ONIBARA BANIREGUN AMBATELE YOLAIBENEKU ASUNSHE AWADO. AKUKO LEBO. KAFEREFUN SHANGO ATI OYA.", "REZO: OKANA BARA OLODAFUN ORUNMILA OÑI PATAKI KODAFA ESHU IFE LEDOYA ELEGBARA LATILE MIATELE AWO AMOTIWO ATELE ESE NITASE ADIFAFUN ONIBARA BANIREGUN AMBATELE YOLAIBENEKU ASUNSHE AWADO AKUKO LEBO. KAFEREFUN SHANGO ATI OYA.", "REZO: EBBO NIKUELEZO, EBBO NIYEWEYI, EBBO NIYIWETAN, AKUGDA, EBBO LOINDA ORUNMILA TAYESHE, ORUNMILA AWELERIKUIN, ORUNMILA AWELERIKUIN, ORUNMILA AWEDE- WUEYO AWEYE YOROMI MISELARA .", "REZO: OKANA BARONA, ORUNMILA YADE ONI IKU ENA AINA IBENIGBATI WAKO MESHERE ENA BARA YEYE KULOSO AKUKO MOUNLE AKUKO AKUNDA ODARA TOBI ORUNMILA ILU ILE TERU TERU MUDA NI ONIONI OPOLOPO OWO.", "REZO: ORUNMILA PATAKI KOGADA ELEDA ESHU ELEGBA LATELAMI GBOGBO OWO.", "REZO: EBBO NIKUELEZO, EBBO NIYEWEYI, EBBO NIYIWETAN, AKUGDA, EBBO LOINDA ORUNMILA TAYESHE, ORUNMILA AWELERIKUIN, ORUNMILA AWELERIKUIN, ORUNMILA AWEDE WUEYO AWEYE YOROMI MISELARA .", "REZO: EBBO NIKUELEZO, EBBO NIYEWEYI, EBBO NIYIWETAN, AKUGDA, EBBO LOINDA ORUNMILA TAYESHE, ORUNMILA AWELERIKUIN, ORUNMILA AWELERIKUIN, ORUNMILA AWEDE- WUEYO AWEYE YOROMI MISELARA ."]}]$q$::jsonb))
update estera_sintesis e set secciones=v.sec from nuevas v where e.numero=v.numero and md5(e.secciones::text)=v.viejo returning e.numero;
